import { Injectable, Logger } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { Inject } from '@nestjs/common';
import { sql } from 'drizzle-orm';
import { PG_CONNECTION } from '../../database/database.module';
import type { AppDb } from '../../database/db.types';
import { RankingsService } from './rankings.service';

const RETRY_CAP = 5;
const LEASE_TIMEOUT_MINUTES = 5;

/**
 * ELO transactional outbox worker (NOTE-3, T13).
 *
 * Claims PENDING rows (or PROCESSING rows with an expired lease) via an atomic
 * CTE `UPDATE ... FROM candidate ... FOR UPDATE SKIP LOCKED` — safe for
 * multiple backend instances. State machine (schema `match_elo_outbox`):
 *   PENDING(retryable) → PROCESSING(lease) → PROCESSED(ok) | FAILED(terminal)
 *   retryable failure returns to PENDING with exponential backoff.
 *
 * Idempotency is already guaranteed by RankingsService.processMatchResult
 * (pg_advisory_xact_lock + unique elo_history_logs index + alreadyProcessed
 * check), so a crash after ELO success but before marking PROCESSED cannot
 * double-count.
 */
@Injectable()
export class EloOutboxProcessor {
  private readonly logger = new Logger(EloOutboxProcessor.name);
  private readonly instanceId: string;
  private running = false;
  private clubMatchUpdatePublisher?: (matchId: string) => Promise<void>;
  private standaloneMatchUpdatePublisher?: (matchId: string) => Promise<void>;

  constructor(
    @Inject(PG_CONNECTION) private readonly db: AppDb,
    private readonly rankingsService: RankingsService,
  ) {
    this.instanceId =
      process.env.HOSTNAME || process.env.POD_NAME || `${require('os').hostname()}-${process.pid}`;
  }

  @Cron(CronExpression.EVERY_30_SECONDS)
  async processOutbox(): Promise<void> {
    if (this.running) return;
    this.running = true;
    let claimed = 0;
    try {
      while (claimed < 20) {
        const row = await this.claimOne();
        if (!row) break;
        claimed += 1;
        await this.processClaimed(row);
      }
    } catch (err) {
      this.logger.error(`ELO outbox cycle failed: ${(err as Error).message}`, (err as Error).stack);
    } finally {
      this.running = false;
    }
  }

  /** Fire-and-forget safe entry point used only after the score transaction commits. */
  async dispatchNow(): Promise<void> {
    await this.processOutbox();
  }

  setClubMatchUpdatePublisher(
    publisher: (matchId: string) => Promise<void>,
  ): void {
    this.clubMatchUpdatePublisher = publisher;
  }

  setStandaloneMatchUpdatePublisher(
    publisher: (matchId: string) => Promise<void>,
  ): void {
    this.standaloneMatchUpdatePublisher = publisher;
  }

  private async publishClubMatchUpdate(matchId: string | null): Promise<void> {
    if (!matchId || !this.clubMatchUpdatePublisher) return;
    try {
      await this.clubMatchUpdatePublisher(matchId);
    } catch (error) {
      this.logger.warn(
        `Unable to publish club match ELO update for ${matchId}: ${(error as Error).message}`,
      );
    }
  }

  private async publishStandaloneMatchUpdate(matchId: string | null): Promise<void> {
    if (!matchId || !this.standaloneMatchUpdatePublisher) return;
    try {
      await this.standaloneMatchUpdatePublisher(matchId);
    } catch (error) {
      this.logger.warn(
        `Unable to publish standalone match ELO update for ${matchId}: ${(error as Error).message}`,
      );
    }
  }

  private async claimOne(): Promise<
    | {
        id: string;
        match_id: string | null;
        club_match_session_match_id: string | null;
        standalone_match_id: string | null;
      }
    | null
  > {
    const result = (await this.db.execute(sql`
      WITH candidate AS (
        SELECT id FROM match_elo_outbox
        WHERE (
          (status = 'PENDING' AND (next_attempt_at IS NULL OR next_attempt_at <= now()))
          OR
          (status = 'PROCESSING' AND locked_at IS NOT NULL
             AND locked_at < now() - interval '${sql.raw(String(LEASE_TIMEOUT_MINUTES))} minutes')
        )
          AND attempts < ${RETRY_CAP}
        ORDER BY created_at
        LIMIT 1
        FOR UPDATE SKIP LOCKED
      )
      UPDATE match_elo_outbox
      SET status = 'PROCESSING',
          locked_at = now(),
          locked_by = ${this.instanceId},
          attempts = attempts + 1,
          last_error = NULL
      WHERE id IN (SELECT id FROM candidate)
      RETURNING id, match_id, club_match_session_match_id, standalone_match_id
    `)) as unknown as Array<{
      id: string;
      match_id: string | null;
      club_match_session_match_id: string | null;
      standalone_match_id: string | null;
    }>;

    return result[0] ?? null;
  }

  private async processClaimed(row: {
    id: string;
    match_id: string | null;
    club_match_session_match_id: string | null;
    standalone_match_id: string | null;
  }): Promise<void> {
    try {
      if (row.club_match_session_match_id) {
        await this.rankingsService.processClubMatchResultFromOutbox(
          row.club_match_session_match_id,
        );
      } else if (row.standalone_match_id) {
        await this.rankingsService.processStandaloneMatchResultFromOutbox(
          row.standalone_match_id,
        );
      } else if (row.match_id) {
        await this.rankingsService.processMatchResultFromOutbox(row.match_id);
      } else {
        throw new Error('ELO outbox row has no match context');
      }
      await this.db.execute(sql`
        UPDATE match_elo_outbox
        SET status = 'PROCESSED', processed_at = now(), locked_at = NULL, locked_by = NULL
        WHERE id = ${row.id}
      `);
      await this.publishClubMatchUpdate(row.club_match_session_match_id);
      await this.publishStandaloneMatchUpdate(row.standalone_match_id);
    } catch (err) {
      const message = (err as Error).message ?? String(err);
      // Retryable (transient) + under cap → back to PENDING with backoff.
      const attemptsResult = (await this.db.execute(sql`
        SELECT attempts FROM match_elo_outbox WHERE id = ${row.id}
      `)) as unknown as Array<{ attempts: string }>;
      const attempts = attemptsResult[0] ? Number(attemptsResult[0].attempts) : 1;

      if (attempts < RETRY_CAP) {
        const backoffSeconds = Math.min(2 ** attempts, 300);
        await this.db.execute(sql`
          UPDATE match_elo_outbox
          SET status = 'PENDING',
              next_attempt_at = now() + interval '${sql.raw(String(backoffSeconds))} seconds',
              locked_at = NULL, locked_by = NULL,
              last_error = ${message}
          WHERE id = ${row.id}
        `);
        if (row.club_match_session_match_id) {
          await this.db.execute(sql`
            UPDATE club_match_session_matches SET elo_status = 'FAILED_RETRYABLE', updated_at = now()
            WHERE id = ${row.club_match_session_match_id}
          `);
        }
        if (row.standalone_match_id) {
          await this.db.execute(sql`
            UPDATE club_standalone_matches SET elo_status = 'FAILED_RETRYABLE', updated_at = now()
            WHERE id = ${row.standalone_match_id}
          `);
        }
        await this.publishClubMatchUpdate(row.club_match_session_match_id);
        await this.publishStandaloneMatchUpdate(row.standalone_match_id);
        this.logger.warn(`ELO outbox retry (attempt ${attempts}/${RETRY_CAP}) for match ${row.match_id ?? row.club_match_session_match_id}: ${message}`);
      } else {
        // Terminal failure after retry cap.
        await this.db.execute(sql`
          UPDATE match_elo_outbox
          SET status = 'FAILED', locked_at = NULL, locked_by = NULL, last_error = ${message}
          WHERE id = ${row.id}
        `);
        if (row.club_match_session_match_id) {
          await this.db.execute(sql`
            UPDATE club_match_session_matches SET elo_status = 'FAILED_TERMINAL', updated_at = now()
            WHERE id = ${row.club_match_session_match_id}
          `);
        }
        if (row.standalone_match_id) {
          await this.db.execute(sql`
            UPDATE club_standalone_matches SET elo_status = 'FAILED_TERMINAL', updated_at = now()
            WHERE id = ${row.standalone_match_id}
          `);
        }
        await this.publishClubMatchUpdate(row.club_match_session_match_id);
        await this.publishStandaloneMatchUpdate(row.standalone_match_id);
        this.logger.error(`ELO outbox FAILED (terminal) for match ${row.match_id ?? row.club_match_session_match_id}: ${message}`);
      }
    }
  }
}

  private async completeMatchInTx(
    tx: any,
    id: string,
    winnerId: string | null,
    details: {
      p1SetsWon: number;
      p2SetsWon: number;
      scoreDetails: Record<string, unknown> | null | undefined;
      auditUserId?: string | null;
      isBye?: boolean;
      expectedRevision?: number;
    },
  ) {
    const [existing] = await tx
      .select()
      .from(schema.matches)
      .where(eq(schema.matches.id, id))
      .limit(1);

    if (!existing) return null;

    // 1. Conditional update: only the FIRST transaction that flips
    // status away from COMPLETED may run side effects (NOTE-1).
    // Optional optimistic lock: when the caller supplies expectedRevision
    // (from a client-visible match), the update only wins if revision matches.
    const [updated] = await tx
      .update(schema.matches)
      .set({
        status: 'COMPLETED',
        winnerId,
        p1SetsWon: details.p1SetsWon,
        p2SetsWon: details.p2SetsWon,
        scoreDetails: details.scoreDetails,
        isBye: details.isBye ?? existing.isBye,
        completedAt: new Date(),
        updatedAt: new Date(),
        revision: sql`${schema.matches.revision} + 1`,
      })
      .where(
        and(
          eq(schema.matches.id, id),
          ne(schema.matches.status, 'COMPLETED'),
          ...(details.expectedRevision !== undefined
            ? [eq(schema.matches.revision, details.expectedRevision)]
            : []),
        ),
      )
      .returning();

    // Affected-row gate: no row updated means either already COMPLETED
    // (idempotent — return null, zero side effects) or a stale revision
    // conflict (client saw an older match) — surface as 409 in the service.
    if (!updated) {
      const [current] = await tx
        .select({
          status: schema.matches.status,
          revision: schema.matches.revision,
        })
        .from(schema.matches)
        .where(eq(schema.matches.id, id))
        .limit(1);
      if (!current || current.status === 'COMPLETED') return null;
      return { conflict: true, currentMatch: current } as never;
    }

    const oldValues = {
      p1SetsWon: existing.p1SetsWon,
      p2SetsWon: existing.p2SetsWon,
      scoreDetails: existing.scoreDetails,
      winnerId: existing.winnerId,
      status: existing.status,
    };
    const newValues = {
      p1SetsWon: updated.p1SetsWon,
      p2SetsWon: updated.p2SetsWon,
      scoreDetails: updated.scoreDetails,
      winnerId: updated.winnerId,
      status: updated.status,
    };
    await this.auditService.logUpdate(
      tx,
      details.auditUserId ?? null,
      'matches',
      id,
      oldValues,
      newValues,
    );

    // 1b. ELO transactional outbox (NOTE-3, T12): enqueue ONLY from the winning
    // transaction, and ONLY for ranked tournaments. Ranked determination is done
    // INSIDE the tx (no TOCTOU against a service-level read). UNIQUE(match_id) +
    // ON CONFLICT DO NOTHING guarantees one row per match ever.
    const [eloTournament] = await tx
      .select({ isRanked: schema.tournaments.isRanked })
      .from(schema.tournaments)
      .where(eq(schema.tournaments.id, existing.tournamentId))
      .limit(1);

    const participantIds = [
      existing.participant1Id,
      existing.participant2Id,
    ].filter((participantId): participantId is string =>
      Boolean(participantId),
    );

    // Mock fixtures are useful for previewing a bracket, but they must never
    // create an ELO outbox item.  The processor also guards this path, yet
    // skipping at enqueue keeps the ranked history clean and avoids needless
    // background work when a mock bracket is finalized.
    const mockParticipants = participantIds.length
      ? await tx
          .select({ isMock: schema.tournamentParticipants.isMock })
          .from(schema.tournamentParticipants)
          .where(inArray(schema.tournamentParticipants.id, participantIds))
      : [];
    const mockRosterUsers = participantIds.length
      ? await tx
          .select({ isMock: schema.users.isMock })
          .from(schema.tournamentRosters)
          .innerJoin(
            schema.users,
            eq(schema.tournamentRosters.userId, schema.users.id),
          )
          .where(
            inArray(schema.tournamentRosters.participantId, participantIds),
          )
      : [];
    const hasMockParticipant =
      mockParticipants.some((participant) => participant.isMock) ||
      mockRosterUsers.some((roster) => roster.isMock);
    // Consent lives on tournament_rosters, one row per USER — matching how
    // processMatchResult applies ELO (rankings.service.ts:600-617 / 628-645 read
    // tournamentRosters.userId per participant). Reading it off the participant
    // would let one team-mate's confirmation hand every other user their score.
    //
    // The roster predicate must stay exactly `.where(eq(participantId, X))` — no
    // status filter. Adding `status = 'ACTIVE'` would give a REMOVED/INVITED row
    // a NULL consent forever and silently kill ELO for the whole participant.
    //
    // A participant with NO roster row (Excel import, no account) must fail:
    // `[].every()` is true, so an empty roster would otherwise pass the gate and
    // such entrants — who have no account to confirm — would be scored anyway.
    //
    // All-or-nothing is deliberate: scoring only the consenting side would let a
    // player farm rating by facing opponents who never confirmed.
    const consentRosterRows = participantIds.length
      ? await tx
          .select({
            participantId: schema.tournamentRosters.participantId,
            rankingConsentAt: schema.tournamentRosters.rankingConsentAt,
          })
          .from(schema.tournamentRosters)
          .where(inArray(schema.tournamentRosters.participantId, participantIds))
      : [];
    const allParticipantsConsented =
      participantIds.length > 0 &&
      consentRosterRows.length > 0 &&
      participantIds.every((participantId) => {
        const rows = consentRosterRows.filter(
          (row) => row.participantId === participantId,
        );
        return (
          rows.length > 0 && rows.every((row) => row.rankingConsentAt !== null)
        );
      });

    const footballTeamRows = participantIds.length
      ? await tx
          .select({
            footballTeamId: schema.tournamentParticipants.footballTeamId,
          })
          .from(schema.tournamentParticipants)
          .where(inArray(schema.tournamentParticipants.id, participantIds))
      : [];
    const isFootballTeamMatch =
      footballTeamRows.length === participantIds.length &&
      footballTeamRows.length === 2 &&
      footballTeamRows.every((row) => Boolean(row.footballTeamId));

    // Football group-stage draws have no winner, but still produce a team-ELO
    // event. Individual/pair ELO keeps the historical winner-only contract.
    if (
      eloTournament?.isRanked &&
      (winnerId || isFootballTeamMatch) &&
      allParticipantsConsented &&
      !hasMockParticipant
    ) {
      await tx
        .insert(schema.matchEloOutbox)
        .values({
          matchId: id,
          status: 'PENDING',
          attempts: 0,
          nextAttemptAt: new Date(),
        })
        .onConflictDoNothing({ target: schema.matchEloOutbox.matchId });
    }

    // 2. Two-legged knockout (bóng đá): chỉ advance khi CẢ2 leg COMPLETED.
    //    Tính aggregate = tổng bàn thắng 2 lượt; hòa tổng → luân lưu (penaltyShootout).
    let effectiveWinnerId = winnerId;
    // Use the row returned by the completion UPDATE. `existing` is a
    // pre-completion snapshot and therefore cannot establish this leg's status.
