describe('RankingConsentService.sendDueReminders', () => {
  const hoursAgo = (h: number) => new Date(NOW.getTime() - h * HOUR);

  /**
   * Resolves by call order: the first select is the candidate scan, every later
   * select is a dispatch looking up its own roster detail row.
   */
  const createDb = (candidates: unknown[]) => {
    let call = 0;
    const chain: Record<string, unknown> = {};
    const self = () => chain;
    chain.select = jest.fn(self);
    chain.from = jest.fn(self);
    chain.innerJoin = jest.fn(self);
    chain.where = jest.fn(self);
    chain.limit = jest.fn(self);
    chain.update = jest.fn(self);
    chain.set = jest.fn(self);
    chain.then = (resolve: (value: unknown) => unknown) =>
      Promise.resolve().then(() => {
        const value = call === 0 ? candidates : [detailRow()];
        call += 1;
        resolve(value);
      });
    return chain;
  };

  const build = (candidates: unknown[], sendOk = true) => {
    const db = createDb(candidates);
    const mailService = { sendMail: jest.fn().mockResolvedValue(sendOk) };
    const service = new RankingConsentService(
      db as never,
      mailService as never,
    );
    return { service, mailService };
  };

  beforeEach(() => {
    jest.useFakeTimers().setSystemTime(NOW);
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('retries a send that never landed, anchoring on the join time', async () => {
    // The reason notifiedAt NULL rows stay in scope: one mail outage must not
    // permanently silence the reminders, or the player never learns their
    // matches will go unscored.
    const { service, mailService } = build([
      { id: 'r1', attempts: 0, notifiedAt: null, joinedAt: hoursAgo(25) },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(1);
    expect(mailService.sendMail).toHaveBeenCalledTimes(1);
  });

  it('waits when the first reminder is not due yet', async () => {
    const { service, mailService } = build([
      { id: 'r1', attempts: 0, notifiedAt: null, joinedAt: hoursAgo(10) },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(0);
    expect(mailService.sendMail).not.toHaveBeenCalled();
  });

  it('sends the first reminder 24h after the send at add time', async () => {
    // attempts === 1 means exactly one send landed — the one at add time — so the
    // first reminder is due 24h after THAT send, not 72h.
    const { service, mailService } = build([
      {
        id: 'r1',
        attempts: 1,
        notifiedAt: hoursAgo(30),
        joinedAt: hoursAgo(100),
      },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(1);
    expect(mailService.sendMail).toHaveBeenCalledTimes(1);
  });

  it('waits before the second reminder', async () => {
    // Two sends landed, so the 72h delay runs from the second one.
    const { service, mailService } = build([
      {
        id: 'r1',
        attempts: 2,
        notifiedAt: hoursAgo(30),
        joinedAt: hoursAgo(100),
      },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(0);
    expect(mailService.sendMail).not.toHaveBeenCalled();
  });

  it('sends the second reminder once 72h have passed', async () => {
    const { service, mailService } = build([
      {
        id: 'r1',
        attempts: 2,
        notifiedAt: hoursAgo(73),
        joinedAt: hoursAgo(200),
      },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(1);
    expect(mailService.sendMail).toHaveBeenCalledTimes(1);
  });

  it('stops at the notification cap so nobody is nagged forever', async () => {
    const { service, mailService } = build([
      {
        id: 'r1',
        attempts: CONSENT_MAX_NOTIFICATIONS,
        notifiedAt: hoursAgo(200),
        joinedAt: hoursAgo(400),
      },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(0);
    expect(mailService.sendMail).not.toHaveBeenCalled();
  });

  it('does not count a failed send as a delivered one', async () => {
    const { service } = build(
      [{ id: 'r1', attempts: 0, notifiedAt: null, joinedAt: hoursAgo(25) }],
      false,
    );

    await expect(service.sendDueReminders()).resolves.toBe(0);
  });
});

describe('RankingConsentGate', () => {
…

  /** drizzle-like chainable stub resolving queued results in order. */
  const createDb = (results: unknown[][]) => {
    const queue = [...results];
    const chain: Record<string, unknown> = {};
    const self = () => chain;
    chain.select = jest.fn(self);
    chain.from = jest.fn(self);
    chain.where = jest.fn(self);
    chain.limit = jest.fn(self);
    chain.then = (resolve: (value: unknown) => unknown) =>
      Promise.resolve().then(() => resolve(queue.shift() ?? []));
    return chain;
  };

  const buildService = (
    rosterRows: unknown[],
    opts: { completedAt?: string | null; withFootball?: boolean } = {},
  ) => {
    const { completedAt = COMPLETED, withFootball = false } = opts;
    const db = createDb([
      [
        {
          completedAt: completedAt ? at(completedAt) : null,
          participant1Id: P1,
          participant2Id: P2,
        },
      ],
      rosterRows,
    ]);
    const football = withFootball
      ? { processCompletedMatch: jest.fn().mockResolvedValue(undefined) }
      : undefined;
    const service = new RankingsService(
      db as never,
      {} as never,
      {} as never,
      { delByPattern: jest.fn(), get: jest.fn(), set: jest.fn() } as never,
      football as never,
    );
    return { service, football };
  };

  const gate = (service: RankingsService) =>
    (
      service as unknown as {
        hasEligibleRankingConsent(id: string): Promise<boolean>;
      }
    ).hasEligibleRankingConsent(MATCH_ID);

  const consented = (participantId: string, iso = '2026-05-01T09:00:00Z') => ({
    participantId,
    rankingConsentAt: at(iso),
  });

  it('allows a match completed after every roster user confirmed', async () => {
    const { service } = buildService([
      consented(P1, '2026-05-01T09:00:00Z'),
      consented(P2, '2026-05-01T09:30:00Z'),
    ]);

    await expect(gate(service)).resolves.toBe(true);
  });

  it('rejects a match completed BEFORE the player confirmed (the V7 rule)', async () => {
    // Consent at 11:00, match finished at 10:00. Counting it would let an
    // organizer force-enrol someone and have old results land against them.
    const { service } = buildService([
      consented(P1, '2026-05-01T09:00:00Z'),
      consented(P2, '2026-06-01T11:00:00Z'),
    ]);

    await expect(gate(service)).resolves.toBe(false);
  });

  it('rejects when one user on a shared participant never confirmed', async () => {
    // A doubles team carries several users on one participant. If consent were
    // read off the participant, one confirmation would hand every team-mate their
    // score — this is the hole that per-user consent exists to close.
    const { service } = buildService([
      consented(P1),
      { participantId: P1, rankingConsentAt: null },
      consented(P2),
    ]);

    await expect(gate(service)).resolves.toBe(false);
  });

  it('rejects a participant that carries no roster row at all', async () => {
    // Excel-imported entrant with no account: nobody can ever confirm, so nothing
    // about it is scorable. An empty row set must not slip through as "all good".
    const { service } = buildService([consented(P1)]);

    await expect(gate(service)).resolves.toBe(false);
  });

  it('rejects a match with no completion time to compare against', async () => {
    const { service } = buildService(
      [consented(P1), consented(P2)],
      { completedAt: null },
    );

    await expect(gate(service)).resolves.toBe(false);
  });

  it('scores a REMOVED roster row exactly as the ELO award does', async () => {
    // processMatchResult reads roster rows by participantId with no status filter,
    // so a REMOVED row still receives a delta. The gate must not be stricter than
    // the thing it guards, or that participant's ELO silently stops.
    const { service } = buildService([
      consented(P1),
      consented(P2),
      consented(P2, '2026-05-01T09:00:00Z'),
    ]);

    await expect(gate(service)).resolves.toBe(true);
  });

  it('skips the football ELO path entirely when consent is missing', async () => {
    // The football branch writes its own ELO and returns early, so a gate placed
    // after it would silently never run for football matches.
    const { service, football } = buildService([], { withFootball: true });

    await expect(
      service.processMatchResultFromOutbox(MATCH_ID),
    ).resolves.toBeUndefined();
    expect(football!.processCompletedMatch).not.toHaveBeenCalled();
  });

  it('does not throw when consent is missing, so the row is not retried forever', async () => {
    // elo-outbox.processor.ts marks a row PROCESSED only when the call returns
    // without throwing; throwing would spin the retry/backoff loop indefinitely.
    const { service } = buildService([]);

    await expect(
      service.processMatchResultFromOutbox(MATCH_ID),
    ).resolves.not.toThrow();
  });
});

import { RankingsService } from './rankings.service';

/**
 * recalculateEloChain DELETEs + REINSERTS elo_history_logs per user inside its
 * match loop. Without a consent filter, one admin call re-scored every completed
 * match — including ones whose players never consented — silently voiding the
 * enqueue and apply gates.
 *
 * These drive the real loop and assert on the destructive call itself. A spy on a
 * helper, or a source-text check, could pass while the gate was wired to the wrong
 * place or computed from rows the loop never loads.
 */
describe('recalculateEloChain consent gate', () => {
  const COMPLETED_AT = new Date('2026-06-01T10:00:00Z');

  const matchRow = () => ({
    match: {
      id: 'm1',
      winnerId: 'p1',
      participant1Id: 'p1',
      participant2Id: 'p2',
      completedAt: COMPLETED_AT,
      updatedAt: COMPLETED_AT,
    },
    stage: { id: 'stage-1' },
    tournament: { id: 't-1', categoryId: 'cat', matchType: 'KNOCKOUT' },
  });

  const roster = (userId: string, consentedAt: Date | null) => ({
    userId,
    rankingConsentAt: consentedAt,
  });

  /** tx stub: resolves queued results in await order, [] once exhausted. */
  const createTx = (results: unknown[][]) => {
    const queue = [...results];
    const deletes: unknown[] = [];
    const chain: Record<string, unknown> = {};
    const self = () => chain;
    chain.select = jest.fn(self);
    chain.from = jest.fn(self);
    chain.innerJoin = jest.fn(self);
    chain.where = jest.fn(self);
    chain.orderBy = jest.fn(self);
    chain.delete = jest.fn(() => {
      deletes.push('deleted');
      return { where: jest.fn().mockResolvedValue(undefined) };
    });
    chain.then = (resolve: (value: unknown) => unknown) =>
      Promise.resolve().then(() => resolve(queue.shift() ?? []));
    return { tx: chain, deletes };
  };

  const runRecalculate = (tx: unknown) => {
    const service = new RankingsService(
      tx as never,
      {} as never,
      {} as never,
      { delByPattern: jest.fn(), get: jest.fn(), set: jest.fn() } as never,
    );
    return (
      service as unknown as {
        recalculateEloChain(
          txArg: unknown,
          playerIds: string[],
          fromTime: Date,
          categoryId: string,
          matchType: string,
        ): Promise<void>;
      }
    ).recalculateEloChain(
      tx,
      ['u1', 'u2'],
      new Date('2026-05-01T00:00:00Z'),
      'cat',
      'KNOCKOUT',
    );
  };

  it('never deletes elo history when a player never consented', async () => {
    const { tx, deletes } = createTx([
      [matchRow()], // matches select
      [roster('u1', new Date('2026-05-01T00:00:00Z'))], // winner rosters
      [roster('u2', null)], // loser rosters — never confirmed
    ]);

    await runRecalculate(tx);

    expect(deletes).toHaveLength(0);
  });

  it('never deletes elo history when consent came after the match completed', async () => {
    // V7: the confirmation instant decides the boundary, so a match finished an
    // hour before consent stays permanently unscored.
    const { tx, deletes } = createTx([
      [matchRow()],
      [roster('u1', new Date('2026-05-01T00:00:00Z'))],
      [roster('u2', new Date('2026-06-01T11:00:00Z'))],
    ]);

    await runRecalculate(tx);

    expect(deletes).toHaveLength(0);
  });

  it('never deletes elo history when a participant carries no roster row', async () => {
    // An Excel-imported entrant with no account cannot confirm; `[].every()` style
    // logic would treat "no rows" as "all good" and score them.
    const { tx, deletes } = createTx([
      [matchRow()],
      [roster('u1', new Date('2026-05-01T00:00:00Z'))],
      [], // loser has no roster rows at all
    ]);

    await runRecalculate(tx);

    expect(deletes).toHaveLength(0);
  });
});

