    .notNull(),
  userId: uuid('user_id')
    .references(() => users.id, { onDelete: 'restrict' })
    .notNull(),
  role: varchar('role', { length: 50 }).default('MAIN').notNull(),
  // Team sport: status mời — INVITED (chưa accept) / ACTIVE / REMOVED
  status: varchar('status', { length: 20 }).default('ACTIVE').notNull(),
