  // Recalculate ELO for a single match manually (via Admin Endpoint)
  async updateMatchElo(dto: UpdateEloDto) {
    const db = this.rankingsRepository.getDbInstance();
    const [matchContext] = await db
      .select({
        status: schema.matches.status,
        isRanked: schema.tournaments.isRanked,
        tournamentType: schema.tournaments.tournamentType,
        communityId: schema.tournaments.communityId,
        categoryId: schema.tournaments.categoryId,
        matchType: schema.tournaments.matchType,
        genderRestriction: schema.tournaments.genderRestriction,
        divisionMatchType: schema.tournamentDivisions.matchType,
        divisionGenderRestriction: schema.tournamentDivisions.genderRestriction,
      })
      .from(schema.matches)
      .innerJoin(
        schema.tournaments,
        eq(schema.matches.tournamentId, schema.tournaments.id),
      )
      .innerJoin(
        schema.tournamentStages,
        eq(schema.matches.stageId, schema.tournamentStages.id),
      )
      .leftJoin(
        schema.tournamentDivisions,
        eq(
          schema.tournamentStages.tournamentDivisionId,
          schema.tournamentDivisions.id,
        ),
      )
      .where(eq(schema.matches.id, dto.matchId))
      .limit(1);

    if (!matchContext) {
      throw new BadRequestException('Trận đấu không tồn tại.');
    }
    if (matchContext.status !== 'COMPLETED') {
      throw new BadRequestException('Chỉ trận đã hoàn tất mới được tính ELO.');
    }
    if (!matchContext.isRanked) {
      throw new BadRequestException('Trận đấu thuộc giải không xếp hạng ELO.');
    }

    const effectiveMatchType =
      matchContext.divisionMatchType ?? matchContext.matchType;
    const rawEffectiveGenderRestriction =
      matchContext.divisionGenderRestriction ?? matchContext.genderRestriction;
    const effectiveGenderRestriction = rawEffectiveGenderRestriction
      ? normalizeGenderRestriction(rawEffectiveGenderRestriction)
      : null;
    if (rawEffectiveGenderRestriction && !effectiveGenderRestriction) {
      throw new BadRequestException('Cấu hình giới tính của trận đấu không hợp lệ.');
    }
    const requestedGenderRestriction = dto.genderRestriction
      ? normalizeGenderRestriction(dto.genderRestriction)
      : null;
    if (dto.genderRestriction && !requestedGenderRestriction) {
      throw new BadRequestException('Cấu hình giới tính không hợp lệ.');
    }
    if (
      effectiveMatchType === 'DOUBLES' ||
      effectiveMatchType === 'MIXED_DOUBLES'
    ) {
      throw new BadRequestException(
        'Trận đôi phải được tính ELO qua luồng hoàn tất trận, không dùng endpoint ELO thủ công cho user đơn.',
      );
    }
    const effectiveCommunityId =
      matchContext.tournamentType === 'CLUB' ? matchContext.communityId : null;
…
  }

const [eloTournament] = await tx
  .select({ isRanked: schema.tournaments.isRanked })
  .from(schema.tournaments)
  .where(eq(schema.tournaments.id, existing.tournamentId))
  .limit(1);

const participantIds = [
  existing.participant1Id,
  existing.participant2Id,
].filter((participantId): participantId is string =>
  Boolean(participantId),
);

// Mock fixtures are useful for previewing a bracket, but they must never
// create an ELO outbox item.  The processor also guards this path, yet
// skipping at enqueue keeps the ranked history clean and avoids needless
// background work when a mock bracket is finalized.
const mockParticipants = participantIds.length
  ? await tx
      .select({ isMock: schema.tournamentParticipants.isMock })
      .from(schema.tournamentParticipants)
      .where(inArray(schema.tournamentParticipants.id, participantIds))
  : [];
const mockRosterUsers = participantIds.length
  ? await tx
      .select({ isMock: schema.users.isMock })
      .from(schema.tournamentRosters)
      .innerJoin(
        schema.users,
        eq(schema.tournamentRosters.userId, schema.users.id),
      )
      .where(
        inArray(schema.tournamentRosters.participantId, participantIds),
      )
  : [];
const hasMockParticipant =
  mockParticipants.some((participant) => participant.isMock) ||
  mockRosterUsers.some((roster) => roster.isMock);
// Consent lives on tournament_rosters, one row per USER — matching how
// processMatchResult applies ELO (rankings.service.ts:600-617 / 628-645 read
// tournamentRosters.userId per participant). Reading it off the participant
// would let one team-mate's confirmation hand every other user their score.
//
// The roster predicate must stay exactly `.where(eq(participantId, X))` — no
// status filter. Adding `status = 'ACTIVE'` would give a REMOVED/INVITED row
// a NULL consent forever and silently kill ELO for the whole participant.
//
// A participant with NO roster row (Excel import, no account) must fail:
// `[].every()` is true, so an empty roster would otherwise pass the gate and
// such entrants — who have no account to confirm — would be scored anyway.
//
// All-or-nothing is deliberate: scoring only the consenting side would let a
// player farm rating by facing opponents who never confirmed.
const consentRosterRows = participantIds.length
  ? await tx
      .select({
        participantId: schema.tournamentRosters.participantId,
        rankingConsentAt: schema.tournamentRosters.rankingConsentAt,
      })
      .from(schema.tournamentRosters)
      .where(inArray(schema.tournamentRosters.participantId, participantIds))
  : [];
const allParticipantsConsented =
  participantIds.length > 0 &&
  consentRosterRows.length > 0 &&
  participantIds.every((participantId) => {
    const rows = consentRosterRows.filter(
      (row) => row.participantId === participantId,
    );
    return (
      rows.length > 0 && rows.every((row) => row.rankingConsentAt !== null)
    );
  });

const footballTeamRows = participantIds.length
  ? await tx
      .select({
        footballTeamId: schema.tournamentParticipants.footballTeamId,
      })
      .from(schema.tournamentParticipants)
      .where(inArray(schema.tournamentParticipants.id, participantIds))
  : [];
const isFootballTeamMatch =
  footballTeamRows.length === participantIds.length &&
  footballTeamRows.length === 2 &&
  footballTeamRows.every((row) => Boolean(row.footballTeamId));

// Football group-stage draws have no winner, but still produce a team-ELO
// event. Individual/pair ELO keeps the historical winner-only contract.
if (
  eloTournament?.isRanked &&
  (winnerId || isFootballTeamMatch) &&
  allParticipantsConsented &&
  !hasMockParticipant
) {
  await tx
    .insert(schema.matchEloOutbox)
    .values({
      matchId: id,
      status: 'PENDING',
      attempts: 0,
      nextAttemptAt: new Date(),
    })
    .onConflictDoNothing({ target: schema.matchEloOutbox.matchId });
}

# mcp__ripwire_explore — ripwire/explore

ONE-call task orientation: the routed+anchored ranking, full bodies of the top hits, their 1-hop callers, field notes, and tests_to_run — ALL under one deterministic byte budget, in a fixed section order (ranking > bodies > callers > notes > tests) that degrades gracefully and reports every truncation. Replaces the for -> fetch_body -> find_referencing_symbols -> memory_recall dance when you want the whole orientation at once; for JUST the ranked inventory use 'for'. Same handler as the CLI --pack-task. ALIAS: tools/call name='pack_task' answers this exact tool with these exact arguments (it gets no separate tools/list entry). task = the task in plain words; budget_tokens = optional (default 6000); partition = optional 2..16, refused outside that band — FANNING OUT to N agents on ONE task? Ask for it and get one shared core plus N minimally-overlapping slices carved along the call graph's own communities, budget_tokens then meaning ONE agent's budget. Read overlap_max/split before trusting the slices. tests_to_run rows: the path key is 'test' on situational_awareness and 'p' on explore and the edit receipts; its value is a path STRING, or an ARRAY of paths beside n when several runner-less tests share their attributes and are served as ONE row; every row carries run (the command) or run_unknown:true. 

## Schema
```ts
type Args = {
  /** a STRING repo directory */
  path?: string;
  /** an ARRAY of 1..16 repo roots */
  paths?: string[];
  /** the task in plain words */
  task: string;
  /** a positive integer token budget (omit it for the verb's own default) */
  budget_tokens?: number;
  /** an integer in 2..16 (omit it for one un-split bundle; 1 IS the un-split one) */
  partition?: number;
  /** a STRING legend posture: compact (the default) or full (restores the full legend) */
  legend?: string;
  /** a BOOLEAN: true forces plain subtoken+body BM25 (omit it for the default router) */
  no_route?: boolean;
};
```
Execute by writing JSON to xd://mcp__ripwire_explore.

# mcp__ripwire_memory_recall — ripwire/memory_recall

Most relevant memory notes / docs for a task, full text — the few that matter, not the whole corpus. path = docs/memory dir; task = what you're working on; top_k = docs to return, 1..1000 (default 8), refused outside that band, never clamped; budget_tokens = the body ceiling in tokens (default 8000) — it SHAPES to fit, the CLI --recall's --max-tokens, not --token-budget's refuse-if-over GATE, and the header discloses max_tokens= and every cut.

## Schema
```ts
type Args = {
  /** a STRING repo directory */
  path?: string;
  /** the task in plain words */
  task: string;
  /** an integer in 1..1000 (omit it for the verb's own default) */
  top_k?: number;
  /** a positive integer token budget (omit it for the verb's own default) */
  budget_tokens?: number;
  /** an ARRAY of 1..16 repo roots */
  paths?: string[];
};
```
Execute by writing JSON to xd://mcp__ripwire_memory_recall.

