  /**
   * V7 gate: a match only reaches the ranking board if BOTH participants had
   * confirmed before the match completed. Deliberately all-or-nothing — scoring
   * only the consenting side would let a player farm rating by facing opponents
   * who never confirmed.
   *
   * Runs at APPLY time, not just at enqueue time: an outbox row queued before the
   * player confirmed is still PENDING when they click, and applying it would
   * count exactly the pre-confirmation matches V7 forbids.
   *
   * Returns false (skip) rather than throwing, so the processor marks the row
   * PROCESSED instead of retrying forever. A skipped match stays unscored for
   * good — that is the intended outcome, not a transient failure.
   */
  private async hasEligibleRankingConsent(matchId: string): Promise<boolean> {
    const [match] = await this.db
      .select({
        completedAt: schema.matches.completedAt,
        participant1Id: schema.matches.participant1Id,
        participant2Id: schema.matches.participant2Id,
      })
      .from(schema.matches)
      .where(eq(schema.matches.id, matchId))
      .limit(1);

    // Without a completion time there is nothing to compare the consent instant
    // against, so the match is not provably post-consent and stays unscored.
    if (!match?.completedAt) return false;

    const participantIds = [match.participant1Id, match.participant2Id].filter(
      (id): id is string => Boolean(id),
    );
    if (participantIds.length === 0) return false;

    // Read consent per USER from tournament_rosters, matching exactly the rows
    // processMatchResult awards ELO to. No status filter, for the same reason:
    // a REMOVED/INVITED roster row still receives a delta there, so filtering it
    // out here would make the gate stricter than the scoring it guards and
    // silently zero out that participant's ELO.
    const consentRows = await this.db
      .select({
        participantId: schema.tournamentRosters.participantId,
        rankingConsentAt: schema.tournamentRosters.rankingConsentAt,
      })
      .from(schema.tournamentRosters)
      .where(inArray(schema.tournamentRosters.participantId, participantIds));

    if (consentRows.length === 0) return false;

    const completedAt = match.completedAt!.getTime();
    return participantIds.every((participantId) => {
      const rows = consentRows.filter(
        (row) => row.participantId === participantId,
      );
      // A participant with no roster row (Excel import, no account) has nobody
      // to confirm, so nothing about it is eligible.
      if (rows.length === 0) return false;
      return rows.every((row) => {
        const consentedAt = row.rankingConsentAt;
        return (
          consentedAt !== null && consentedAt.getTime() <= completedAt
        );
      });
    });
  }

  /**
   * Entry point used by the ELO outbox worker (elo-outbox.processor.ts).
   * Loads the match + tournament context and calls processMatchResult with the
   * same arguments the old inline completion path used, so ELO semantics stay
   * identical while the caller moves out of the completion transaction.
   * Idempotent by design (advisory lock + unique elo_history_logs index).
   */
  async processMatchResultFromOutbox(matchId: string) {
    // Must run BEFORE the football branch: footballTeamEloService writes its own
    // ELO and returns early, so a gate placed after it would never see football
    // matches and V7 would not apply to them at all.
    if (!(await this.hasEligibleRankingConsent(matchId))) return;

    const footballResult =
      await this.footballTeamEloService?.processCompletedMatch(matchId);
    if (footballResult?.handled) return footballResult;

    const [match] = await this.db
      .select({
        winnerId: schema.matches.winnerId,
        participant1Id: schema.matches.participant1Id,
        participant2Id: schema.matches.participant2Id,
        tournamentId: schema.matches.tournamentId,
        stageId: schema.matches.stageId,
      })
      .from(schema.matches)
      .where(eq(schema.matches.id, matchId))
      .limit(1);

    if (!match) {
      throw new Error(`Match ${matchId} not found for ELO outbox processing`);
    }
    if (!match.winnerId) {
      throw new Error(`Match ${matchId} has no winner — cannot compute ELO`);
    }

    const loserId =
      match.winnerId === match.participant1Id
        ? match.participant2Id
        : match.participant1Id;
    if (!loserId) {
      throw new Error(`Match ${matchId} has no loser — cannot compute ELO`);
    }

    const [tournament] = await this.db
      .select({
        categoryId: schema.tournaments.categoryId,
        tournamentMatchType: schema.tournaments.matchType,
        tournamentType: schema.tournaments.tournamentType,
        communityId: schema.tournaments.communityId,
        tournamentGenderRestriction: schema.tournaments.genderRestriction,
        divisionMatchType: schema.tournamentDivisions.matchType,
        divisionGenderRestriction: schema.tournamentDivisions.genderRestriction,
      })
      .from(schema.tournaments)
      .leftJoin(
        schema.tournamentStages,
        eq(schema.tournamentStages.id, match.stageId),
      )
      .leftJoin(
        schema.tournamentDivisions,
        eq(
          schema.tournamentDivisions.id,
          schema.tournamentStages.tournamentDivisionId,
        ),
      )
      .where(eq(schema.tournaments.id, match.tournamentId))
      .limit(1);

    if (!tournament) {
      throw new Error(
        `Tournament ${match.tournamentId} not found for ELO outbox processing`,
      );
    }

    const effectiveMatchType =
      tournament.divisionMatchType ?? tournament.tournamentMatchType;
    const effectiveGenderRestriction =
      tournament.divisionGenderRestriction ??
      tournament.tournamentGenderRestriction;
    const scope =
      tournament.tournamentType === 'CLUB' && tournament.communityId
        ? 'COMMUNITY'
        : 'PUBLIC';

    return this.processMatchResult(
      matchId,
      match.winnerId,
      loserId,
      tournament.categoryId,
      effectiveMatchType,
      scope,
      tournament.communityId || undefined,
      effectiveGenderRestriction || undefined,
    );
  }

