async function findLegacyUser(
  tx: AppTx,
  email: string,
  phone: string | undefined,
): Promise<string | null> {
  let foundUser: typeof schema.users.$inferSelect | undefined;
  if (email) {
    foundUser = await tx
      .select()
      .from(schema.users)
      .where(eq(schema.users.email, email))
      .limit(1)
      .then((rows) => rows[0]);
  }
  if (!foundUser && phone) {
    const foundProfile = await tx
      .select()
      .from(schema.profiles)
      .where(eq(schema.profiles.phoneNumber, phone))
      .limit(1)
      .then((rows) => rows[0]);
    if (foundProfile) {
      foundUser = await tx
        .select()
        .from(schema.users)
        .where(eq(schema.users.id, foundProfile.userId))
        .limit(1)
        .then((rows) => rows[0]);
    }
  }
  return foundUser?.id ?? null;
}
