  const MATCH_ID = 'match-1';
  const P1 = 'participant-1';
  const P2 = 'participant-2';

  const at = (iso: string) => new Date(iso);
  const COMPLETED = '2026-06-01T10:00:00Z';

  /** drizzle-like chainable stub resolving queued results in order. */
  const createDb = (results: unknown[][]) => {
    const queue = [...results];
    const chain: Record<string, unknown> = {};
    const self = () => chain;
    chain.select = jest.fn(self);
    chain.from = jest.fn(self);
    chain.innerJoin = jest.fn(self);
    chain.leftJoin = jest.fn(self);
    chain.where = jest.fn(self);
    chain.limit = jest.fn(self);
    chain.then = (resolve: (value: unknown) => unknown) =>
      Promise.resolve().then(() => resolve(queue.shift() ?? []));
    return chain;
  };

  const buildService = (
    rosterRows: unknown[],
    opts: {
      completedAt?: string | null;
      withFootball?: boolean;
      isRanked?: boolean;
      participant1Id?: string | null;
      participant2Id?: string | null;
      guestParticipantIds?: string[];
    } = {},
  ) => {
    const {
      completedAt = COMPLETED,
      withFootball = false,
      isRanked = true,
      participant1Id = P1,
      participant2Id = P2,
      guestParticipantIds = [],
    } = opts;
    const db = createDb([
      [
        {
          completedAt: completedAt ? at(completedAt) : null,
          participant1Id,
          participant2Id,
          isRanked,
        },
      ],
      rosterRows,
      guestParticipantIds.map((participantId) => ({ participantId })),
    ]);
  ) => {
    const {
      completedAt = COMPLETED,
      withFootball = false,
      isRanked = true,
      participant1Id = P1,
      participant2Id = P2,
    } = opts;
    const db = createDb([
      [
        {
          completedAt: completedAt ? at(completedAt) : null,
          participant1Id,
          participant2Id,
          isRanked,
        },
      ],
      rosterRows,
      [],
    ]);
    const football = withFootball
      ? { processCompletedMatch: jest.fn().mockResolvedValue(undefined) }
      : undefined;
    const service = new RankingsService(
      db as never,
      {} as never,
      {} as never,
      { delByPattern: jest.fn(), get: jest.fn(), set: jest.fn() } as never,
      football as never,
    );
    return { service, football };
  };

  const gate = (service: RankingsService) =>
    (
      service as unknown as {
        hasEligibleRankingConsent(id: string): Promise<boolean>;
      }
    ).hasEligibleRankingConsent(MATCH_ID);

