BEGIN;

ALTER TABLE tournament_participants
  ADD COLUMN IF NOT EXISTS organizer_note varchar(280);

CREATE TABLE IF NOT EXISTS tournament_guest_rosters (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  participant_id uuid NOT NULL
    REFERENCES tournament_participants(id) ON DELETE CASCADE,
  display_name varchar(255) NOT NULL,
  role varchar(50) NOT NULL DEFAULT 'MAIN',
  contact_email varchar(320),
  contact_phone varchar(30),
  claim_token_hash varchar(64) NOT NULL,
  claim_expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS tournament_guest_rosters_participant_idx
  ON tournament_guest_rosters (participant_id);

CREATE UNIQUE INDEX IF NOT EXISTS tournament_guest_rosters_claim_hash_unique_idx
  ON tournament_guest_rosters (claim_token_hash);

COMMIT;

