    const { tx, deletes } = createTx([
      [matchRow()], // matches select
      [roster('u1', new Date('2026-05-01T00:00:00Z'))], // winner rosters
      [roster('u2', null)], // loser rosters — never confirmed
    ]);

    await runRecalculate(tx);

    expect(deletes).toHaveLength(0);
