  1100, 1200, 1300, 1400, 1500, 1600, 1700, 1800,
] as const;
const ELO_DECAY_INACTIVE_MONTHS = 1;
const ELO_DECAY_THRESHOLD = 1400;
const ELO_DECAY_RATES = [
  { minElo: 1700, rate: 0.05 },
