import { RankingsService } from './rankings.service';
import * as schema from '../../database/schema';

/**
 * recalculateEloChain DELETEs + REINSERTS elo_history_logs per user inside its
 * match loop. Without a consent filter, one admin call re-scored every completed
 * match — including ones whose players never consented — silently voiding the
 * enqueue and apply gates.
 *
 * These drive the real loop and assert on the destructive call itself. A spy on a
 * helper, or a source-text check, could pass while the gate was wired to the wrong
 * place or computed from rows the loop never loads.
 */
describe('recalculateEloChain consent gate', () => {
  const COMPLETED_AT = new Date('2026-06-01T10:00:00Z');

  const matchRow = (isRanked = true) => ({
    match: {
      id: 'm1',
      winnerId: 'p1',
      participant1Id: 'p1',
      participant2Id: 'p2',
      completedAt: COMPLETED_AT,
      updatedAt: COMPLETED_AT,
    },
    stage: { id: 'stage-1' },
    tournament: {
      id: 't-1',
      categoryId: 'cat',
      matchType: 'KNOCKOUT',
      isRanked,
    },
  });

  const roster = (userId: string, consentedAt: Date | null) => ({
    userId,
    rankingConsentAt: consentedAt,
  });

  /** Return query rows by source table so each test exercises real side grouping. */
  const createTx = (results: {
    matches: unknown[];
    guestRosterRows?: unknown[];
    rosterRows?: unknown[][];
  }) => {
    const deletes: unknown[] = [];
    const resultQueues = new Map<unknown, unknown[][]>([
      [schema.matches, [results.matches]],
      [schema.tournamentGuestRosters, [results.guestRosterRows ?? []]],
      [schema.tournamentRosters, results.rosterRows ?? []],
    ]);
    let selectedTable: unknown;
    const chain: Record<string, unknown> = {};
    const self = () => chain;
    chain.select = jest.fn(self);
    chain.from = jest.fn((table: unknown) => {
      selectedTable = table;
      return chain;
    });
    chain.innerJoin = jest.fn(self);
    chain.leftJoin = jest.fn(self);
    chain.where = jest.fn(self);
    chain.orderBy = jest.fn(self);
    chain.limit = jest.fn(self);
    chain.insert = jest.fn(self);
    chain.values = jest.fn(self);
    chain.update = jest.fn(self);
    chain.set = jest.fn(self);
    chain.delete = jest.fn(() => {
      deletes.push('deleted');
      return { where: jest.fn().mockResolvedValue(undefined) };
    });
    chain.then = (resolve: (value: unknown) => unknown) => {
      const queue = resultQueues.get(selectedTable) ?? [];
      return Promise.resolve().then(() => resolve(queue.shift() ?? []));
    };
    return { tx: chain, deletes };
  };

  const runRecalculate = (tx: unknown) => {
    const service = new RankingsService(
      tx as never,
      {} as never,
      {
        calculateElo: jest.fn().mockReturnValue({
          newElo: 1001,
          changedPoints: 1,
          newWinStreak: 1,
          newPeakElo: 1001,
        }),
      } as never,
      { delByPattern: jest.fn(), get: jest.fn(), set: jest.fn() } as never,
    );
    // The cast exposes only the private replay entry point and rank-refresh seam to this unit test.
    const rankingTestAccess = service as unknown as {
      recalculateUserRankTier: jest.Mock;
      recalculateEloChain(
        txArg: unknown,
        playerIds: string[],
        fromTime: Date,
        categoryId: string,
        matchType: string,
      ): Promise<void>;
    };
    rankingTestAccess.recalculateUserRankTier = jest
      .fn()
      .mockResolvedValue(undefined);
    return rankingTestAccess.recalculateEloChain(
      tx,
      ['u1', 'u2'],
      new Date('2026-05-01T00:00:00Z'),
      'cat',
      'KNOCKOUT',
    );
  };

  it('never deletes elo history when a player never consented', async () => {
    const { tx, deletes } = createTx([
      [matchRow()],
      [],
      [roster('u1', new Date('2026-05-01T00:00:00Z'))],
      [roster('u2', null)],
    ]);

    await runRecalculate(tx);

    expect(deletes).toHaveLength(0);
  });

  it('never deletes elo history when consent came after the match completed', async () => {
    // V7: the confirmation instant decides the boundary, so a match finished an
    // hour before consent stays permanently unscored.
    const { tx, deletes } = createTx([
      [matchRow()],
      [],
      [roster('u1', new Date('2026-05-01T00:00:00Z'))],
      [roster('u2', new Date('2026-06-01T11:00:00Z'))],
    ]);

    await runRecalculate(tx);

    expect(deletes).toHaveLength(0);
  });

  it('never deletes elo history when a participant carries no roster row', async () => {
    // An Excel-imported entrant with no account cannot confirm; `[].every()` style
    // logic would treat "no rows" as "all good" and score them.
    const { tx, deletes } = createTx([
      [matchRow()],
      [],
      [roster('u1', new Date('2026-05-01T00:00:00Z'))],
      [],
    ]);

    await runRecalculate(tx);

    expect(deletes).toHaveLength(0);
  });

  it('never deletes history for an unranked tournament', async () => {
    const consent = new Date('2026-05-01T00:00:00Z');
    const { tx, deletes } = createTx([
      [matchRow(false)],
      [],
    ]);
    await expect(runRecalculate(tx)).resolves.toBeUndefined();
    expect(deletes).toHaveLength(0);
  });

  it('never deletes history when either side still has a guest roster slot', async () => {
    const consent = new Date('2026-05-01T00:00:00Z');
    const { tx, deletes } = createTx([
      [matchRow()],
      [{ participantId: 'p2' }],
      [roster('u1', consent)],
      [roster('u2', consent)],
    ]);

    await expect(runRecalculate(tx)).resolves.toBeUndefined();
    expect(deletes).toHaveLength(0);
  });

});

