import * as schema from '../../../database/schema';
import { TournamentRegistrationRepository } from './tournament-registration.repository';

describe('TournamentRegistrationRepository ranking consent', () => {
  it('reaches registration lifecycle validation without ranking consent', async () => {
    const resultsByTable = new Map<unknown, unknown[]>([
      [
        schema.tournaments,
        [
          {
            id: 'tournament-1',
            status: 'COMPLETED',
            isRanked: true,
            isRegistrationLocked: false,
          },
        ],
      ],
      [schema.seriesEvents, []],
    ]);
    let selectedTable: unknown;
    const query: Record<string, unknown> = {};
    const self = () => query;
    query.select = jest.fn(self);
    query.from = jest.fn((table: unknown) => {
      selectedTable = table;
      return query;
    });
    query.where = jest.fn(self);
    query.innerJoin = jest.fn(self);
    query.limit = jest.fn(self);
    query.for = jest.fn(self);
    query.then = (resolve: (rows: unknown[]) => unknown) =>
      Promise.resolve().then(() =>
        resolve(resultsByTable.get(selectedTable) ?? []),
      );

    const db = {
      transaction: jest.fn(
        (callback: (transaction: unknown) => unknown) => callback(query),
      ),
    };
    const repository = Object.create(
      TournamentRegistrationRepository.prototype,
    ) as TournamentRegistrationRepository;
    const repositoryTestAccess = repository as unknown as { db: unknown };
    repositoryTestAccess.db = db;

    await expect(
      repository.registerParticipant(
        'tournament-1',
        'player-1',
        {} as never,
      ),
    ).rejects.toThrow('Giải đấu chưa hoặc đã đóng đăng ký.');
  });
});

