import { Injectable, Inject, Logger, Optional } from '@nestjs/common';
import { and, eq, isNull } from 'drizzle-orm';
import { PG_CONNECTION } from '../../../database/database.module';
import type { AppDb } from '../../../database/db.types';
import * as schema from '../../../database/schema';
import { MailService } from '../../../providers/mail/mail.service';

/**
 * Thông báo XÁC NHẬN (không phải lời mời) cho người tham gia.
 *
 * Mail KHÔNG mang token: bấm xác nhận phải đi qua endpoint đã đăng nhập, nên không
 * có bí mật nào nằm trong link để lộ. Link chỉ đưa người chơi tới trang giải để bấm.
 *
 * Tự động nhắc tối đa 3 lần rồi dừng — bấm tay từ phía ban tổ chức là thao tác
 * không còn thiết.
 */
export const CONSENT_MAX_NOTIFICATIONS = 3;

/** Số giờ chờ trước mỗi lần nhắc, tính từ lần gửi gần nhất. */
export const CONSENT_REMINDER_DELAYS_HOURS = [24, 72] as const;

@Injectable()
export class RankingConsentService {
  private readonly logger = new Logger(RankingConsentService.name);

  constructor(
    @Inject(PG_CONNECTION) private readonly db: AppDb,
    @Optional() private readonly mailService?: MailService,
  ) {}

  private get frontendUrl(): string {
    return (
      process.env.FRONTEND_URL?.replace(/\/$/, '') ?? 'http://localhost:3001'
    );
  }

  /** Gửi ngay cho một roster row cụ thể (dùng khi vừa thêm người). */
  async sendConfirmationRequest(rosterId: string): Promise<boolean> {
    return this.dispatch(rosterId, 'Xác nhận tham gia giải đấu');
  }

  /** Nhắc lại cho những ai đã quá hạn mà chưa xác nhận. */
  async sendDueReminders(): Promise<number> {
    const now = Date.now();

    // Rows whose notifiedAt is still NULL are included on purpose. dispatch stamps
    // that column only after a successful send, so filtering NULLs out would mean a
    // single temporary mail outage silently ends all reminders — the player never
    // hears again and never learns their matches go unscored. That is exactly the
    // silent-exclusion failure this feature exists to prevent.
    const due = await this.db
      .select({
        id: schema.tournamentRosters.id,
        attempts: schema.tournamentRosters.consentNotifiedCount,
        notifiedAt: schema.tournamentRosters.consentNotifiedAt,
        joinedAt: schema.tournamentRosters.joinedAt,
      })
      .from(schema.tournamentRosters)
      .innerJoin(
        schema.tournamentParticipants,
        eq(
          schema.tournamentParticipants.id,
          schema.tournamentRosters.participantId,
        ),
      )
      .innerJoin(
        schema.tournaments,
        eq(schema.tournaments.id, schema.tournamentParticipants.tournamentId),
      )
      .where(
        and(
          isNull(schema.tournamentRosters.rankingConsentAt),
          // A tournament that does not rank scores nothing, so asking its players to
          // consent would be noise.
          eq(schema.tournaments.isRanked, true),
        ),
      );

    let sent = 0;
    for (const row of due) {
      // Three sends in total: the one at add time plus two reminders. Past the cap
      // the row is left alone — nobody gets nagged forever.
      if (row.attempts >= CONSENT_MAX_NOTIFICATIONS) continue;

      // attempts === 0 means the first send never landed, so the clock runs from
      // when the player joined instead of from a send that does not exist.
      const anchor = row.notifiedAt ?? row.joinedAt;
      if (!anchor) continue;

      // attempts counts DELIVERED sends, and the send at add time already made it 1.
      // So the first reminder is attempts === 1 → delays[0] = 24h. Indexing by
      // `attempts` would jump straight to 72h and leave delays[0] as dead code.
      // attempts === 0 means nothing was delivered yet, so the 24h delay runs from
      // joinedAt instead.
      const delayHours =
        CONSENT_REMINDER_DELAYS_HOURS[
          Math.min(
            Math.max(row.attempts - 1, 0),
            CONSENT_REMINDER_DELAYS_HOURS.length - 1,
          )
        ];
      const elapsedHours = (now - new Date(anchor).getTime()) / 3_600_000;
      if (elapsedHours < delayHours) continue;

      if (await this.dispatch(row.id, 'Nhắc xác nhận tham gia giải đấu')) {
        sent += 1;
      }
    }
    return sent;
  }

  /**
   * Gửi 1 mail và ghi nhận số lần đã gửi.
   *
   * Chỉ tăng bộ đếm khi gửi THÀNH CÔNG — nếu không, một hệ thống mail hỏng sẽ đốt
   * hết 3 lượt nhắc rồi im lặng, biến "chưa gửi được" thành "đã bỏ qua".
   */
  private async dispatch(rosterId: string, subject: string): Promise<boolean> {
    if (!this.mailService) return false;

    const rows = await this.db
      .select({
        userEmail: schema.users.email,
        participantName: schema.tournamentParticipants.teamName,
        tournamentName: schema.tournaments.name,
        tournamentId: schema.tournaments.id,
        attempts: schema.tournamentRosters.consentNotifiedCount,
        consentedAt: schema.tournamentRosters.rankingConsentAt,
      })
      .from(schema.tournamentRosters)
      .innerJoin(
        schema.users,
        eq(schema.users.id, schema.tournamentRosters.userId),
      )
      .innerJoin(
        schema.tournamentParticipants,
        eq(schema.tournamentParticipants.id, schema.tournamentRosters.participantId),
      )
      .innerJoin(
        schema.tournaments,
        eq(schema.tournaments.id, schema.tournamentParticipants.tournamentId),
      )
      .where(eq(schema.tournamentRosters.id, rosterId))
      .limit(1);

    const row = rows[0];
    if (!row?.userEmail || row.consentedAt) return false;

    const link = `${this.frontendUrl}/tournaments/${row.tournamentId}`;
    const isReminder = row.attempts > 0;

    try {
      const ok = await this.mailService.sendMail(
        row.userEmail,
        `[Sporto] ${subject}: ${row.tournamentName}`,
        this.buildHtml({
          participantName: row.participantName,
          tournamentName: row.tournamentName,
          link,
          isReminder,
        }),
      );
      if (!ok) return false;
    } catch (err) {
      this.logger.warn(
        `Gửi mail xác nhận thất bại cho roster ${rosterId}: ${
          err instanceof Error ? err.message : String(err)
        }`,
      );
      return false;
    }

    await this.db
      .update(schema.tournamentRosters)
      .set({
        consentNotifiedAt: new Date(),
        consentNotifiedCount: row.attempts + 1,
      })
      .where(eq(schema.tournamentRosters.id, rosterId));

    return true;
  }

  private buildHtml(args: {
    participantName: string | null;
    tournamentName: string;
    link: string;
    isReminder: boolean;
  }): string {
    const heading = args.isReminder
      ? 'Bạn chưa xác nhận tham gia'
      : 'Bạn được thêm vào một giải đấu';
    return `
      <div style="font-family: system-ui, -apple-system, sans-serif; max-width: 560px;">
        <div style="background-color: #0f172a; padding: 20px; border-radius: 8px 8px 0 0;">
          <h1 style="color: #ffffff; font-size: 18px; margin: 0;">${heading}</h1>
        </div>
        <div style="background-color: #ffffff; padding: 24px; border: 1px solid #e2e8f0; border-top: none;">
          <p style="font-size: 14px; color: #0f172a; margin: 0 0 16px;">
            Xin chào ${args.participantName ?? 'bạn'},
          </p>
          <p style="font-size: 14px; color: #334155; margin: 0 0 16px;">
            Ban tổ chức đã thêm bạn vào giải
            <strong>${args.tournamentName}</strong>.
          </p>
          <div style="background-color: #fef3c7; border-left: 4px solid #f59e0b; padding: 12px 16px; margin-bottom: 20px;">
            <p style="font-size: 14px; color: #78350f; margin: 0;">
              Muốn được tính Elo và lưu lịch sử trận đấu, bạn cần bấm xác nhận.
              <br />
              Chỉ những trận <strong>hoàn thành từ lúc bạn xác nhận</strong> mới được
              tính — các trận đã đấu trước đó không tính.
            </p>
          </div>
          <a href="${args.link}" style="background-color: #2563eb; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 8px; font-weight: bold; font-size: 14px; display: inline-block;">
            Đăng nhập để xác nhận
          </a>
          <p style="font-size: 13px; color: #64748b; margin: 20px 0 0;">
            Không xác nhận? Bạn vẫn thi đấu bình thường, chỉ là không có Elo.
          </p>
        </div>
      </div>
    `;
  }
}

import {
  RankingConsentService,
  CONSENT_MAX_NOTIFICATIONS,
} from './ranking-consent.service';

const HOUR = 3_600_000;
const NOW = new Date('2026-06-10T12:00:00Z');

/** What dispatch finds for the roster row it is about to notify. */
const detailRow = () => ({
  userEmail: 'player@example.com',
  participantName: 'Nguyễn Văn A',
  tournamentName: 'Cup Đông Nam',
  tournamentId: 't-1',
  attempts: 0,
  consentedAt: null,
});

describe('RankingConsentService.sendDueReminders', () => {
  const hoursAgo = (h: number) => new Date(NOW.getTime() - h * HOUR);

  /**
   * Resolves by call order: the first select is the candidate scan, every later
   * select is a dispatch looking up its own roster detail row.
   */
  const createDb = (candidates: unknown[]) => {
    let call = 0;
    const chain: Record<string, unknown> = {};
    const self = () => chain;
    chain.select = jest.fn(self);
    chain.from = jest.fn(self);
    chain.innerJoin = jest.fn(self);
    chain.where = jest.fn(self);
    chain.limit = jest.fn(self);
    chain.update = jest.fn(self);
    chain.set = jest.fn(self);
    chain.then = (resolve: (value: unknown) => unknown) =>
      Promise.resolve().then(() => {
        const value = call === 0 ? candidates : [detailRow()];
        call += 1;
        resolve(value);
      });
    return chain;
  };

  const build = (candidates: unknown[], sendOk = true) => {
    const db = createDb(candidates);
    const mailService = { sendMail: jest.fn().mockResolvedValue(sendOk) };
    const service = new RankingConsentService(
      db as never,
      mailService as never,
    );
    return { service, mailService };
  };

  beforeEach(() => {
    jest.useFakeTimers().setSystemTime(NOW);
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('retries a send that never landed, anchoring on the join time', async () => {
    // The reason notifiedAt NULL rows stay in scope: one mail outage must not
    // permanently silence the reminders, or the player never learns their
    // matches will go unscored.
    const { service, mailService } = build([
      { id: 'r1', attempts: 0, notifiedAt: null, joinedAt: hoursAgo(25) },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(1);
    expect(mailService.sendMail).toHaveBeenCalledTimes(1);
  });

  it('waits when the first reminder is not due yet', async () => {
    const { service, mailService } = build([
      { id: 'r1', attempts: 0, notifiedAt: null, joinedAt: hoursAgo(10) },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(0);
    expect(mailService.sendMail).not.toHaveBeenCalled();
  });

  it('sends the first reminder 24h after the send at add time', async () => {
    // attempts === 1 means exactly one send landed — the one at add time — so the
    // first reminder is due 24h after THAT send, not 72h.
    const { service, mailService } = build([
      {
        id: 'r1',
        attempts: 1,
        notifiedAt: hoursAgo(30),
        joinedAt: hoursAgo(100),
      },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(1);
    expect(mailService.sendMail).toHaveBeenCalledTimes(1);
  });

  it('waits before the second reminder', async () => {
    // Two sends landed, so the 72h delay runs from the second one.
    const { service, mailService } = build([
      {
        id: 'r1',
        attempts: 2,
        notifiedAt: hoursAgo(30),
        joinedAt: hoursAgo(100),
      },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(0);
    expect(mailService.sendMail).not.toHaveBeenCalled();
  });

  it('sends the second reminder once 72h have passed', async () => {
    const { service, mailService } = build([
      {
        id: 'r1',
        attempts: 2,
        notifiedAt: hoursAgo(73),
        joinedAt: hoursAgo(200),
      },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(1);
    expect(mailService.sendMail).toHaveBeenCalledTimes(1);
  });

  it('stops at the notification cap so nobody is nagged forever', async () => {
    const { service, mailService } = build([
      {
        id: 'r1',
        attempts: CONSENT_MAX_NOTIFICATIONS,
        notifiedAt: hoursAgo(200),
        joinedAt: hoursAgo(400),
      },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(0);
    expect(mailService.sendMail).not.toHaveBeenCalled();
  });

  it('does not count a failed send as a delivered one', async () => {
    const { service } = build(
      [{ id: 'r1', attempts: 0, notifiedAt: null, joinedAt: hoursAgo(25) }],
      false,
    );

    await expect(service.sendDueReminders()).resolves.toBe(0);
  });
});

  async updateStatus(id: string, data: UpdateMatchStatusDto) {
    const setClause: Record<string, unknown> = {
      status: data.status,
      updatedAt: new Date(),
      revision: sql`${schema.matches.revision} + 1`,
    };

    if (data.status === 'ONGOING') {
      setClause.startedAt = new Date();
    } else if (data.status === 'COMPLETED') {
      setClause.completedAt = new Date();
    }

    const [updated] = await this.db
      .update(schema.matches)
      .set(setClause)
      .where(eq(schema.matches.id, id))
      .returning();

    return await this.findById(updated.id);
  }

  /**
   * Return the already completed leg of a two-legged football tie. Keeping
   * this query in the repository makes aggregate resolution deterministic and
   * avoids letting the service scan arbitrary matches from another tie.
   */
  async findCompletedTieLeg(tieId: string, currentMatchId: string) {
    const [leg] = await this.db
      .select()
      .from(schema.matches)
      .where(
        and(
          eq(schema.matches.tieId, tieId),
          ne(schema.matches.id, currentMatchId),
          eq(schema.matches.status, 'COMPLETED'),
          isNull(schema.matches.deletedAt),
        ),
      )
      .orderBy(schema.matches.leg)
      .limit(1);
    return leg ?? null;
  }

  async completeMatch(
    id: string,
    winnerId: string | null,
    matchDetails: {
      nextMatchId?: string | null;
      loserNextMatchId?: string | null;
      matchOrder: number;
      participant1Id: string | null;
      participant2Id: string | null;
      groupId?: string | null;
      isRoundRobin: boolean;
      p1SetsWon: number;
      p2SetsWon: number;
      scoreDetails: Record<string, unknown> | null | undefined;
      auditUserId?: string | null;
      expectedRevision?: number;
    },
  ) {
    return await this.db.transaction(async (tx) => {
      const updated = await this.completeMatchInTx(tx, id, winnerId, {
        p1SetsWon: matchDetails.p1SetsWon,
        p2SetsWon: matchDetails.p2SetsWon,
        scoreDetails: matchDetails.scoreDetails,
        auditUserId: matchDetails.auditUserId,
        expectedRevision: matchDetails.expectedRevision,
      });

      // A stale-revision completion surfaces as a conflict — standings must NOT
      // run for it (the transaction did not win the completion).
      if (updated && typeof updated === 'object' && 'conflict' in updated) {
        return updated;
      }

      // 5. Update standings if Round Robin
      if (matchDetails.isRoundRobin && updated) {
        // Query custom win/draw/loss points from sportRules
        const [group] = await tx
          .select({
            tournamentId: schema.tournamentStages.tournamentId,
          })
          .from(schema.tournamentGroups)
          .innerJoin(
            schema.tournamentStages,
            eq(schema.tournamentGroups.stageId, schema.tournamentStages.id),
          )
          .where(eq(schema.tournamentGroups.id, updated.groupId))
          .limit(1);

        let winPoints = 3;
        let drawPoints = 1;
        let lossPoints = 0;

        if (group) {
          const [tournament] = await tx
            .select({
              sportRules: schema.tournaments.sportRules,
            })
            .from(schema.tournaments)
            .where(eq(schema.tournaments.id, group.tournamentId))
            .limit(1);

          if (tournament && tournament.sportRules) {
            const rules = tournament.sportRules as Record<string, unknown>;
            const scoring =
              (rules.scoring as Record<string, unknown> | undefined) ?? rules;
            if (typeof scoring.winPoints === 'number')
              winPoints = scoring.winPoints;
            if (typeof scoring.drawPoints === 'number')
              drawPoints = scoring.drawPoints;
            if (typeof scoring.lossPoints === 'number')
              lossPoints = scoring.lossPoints;
          }
        }

        const p1Id = updated.participant1Id;
        const p2Id = updated.participant2Id;
        const participants = [p1Id, p2Id];
        const isDraw = !winnerId && p1Id && p2Id;

        // points_for/points_against = TỔNG điểm ghi được qua các set (chuẩn
        // hiệu số điểm), không phải số set thắng. totalPoints giữ nguyên 3/1/0.
        const { p1: team1Total, p2: team2Total } = sumSetPoints(
          matchDetails.scoreDetails,
        );

        for (const pId of participants) {
          if (!pId) continue;
          const isWinner = pId === winnerId;
          const pointsEarned = isDraw
            ? drawPoints
            : isWinner
              ? winPoints
              : lossPoints;
          const pointsFor = pId === p1Id ? team1Total : team2Total;
          const pointsAgainst = pId === p1Id ? team2Total : team1Total;

          // Atomic upsert (NOTE-2): INSERT ... ON CONFLICT DO UPDATE with
          // SQL-side increments. Replaces read-modify-write, so concurrent
          // completions for the same group/participant never lose an update.
          await tx
            .insert(schema.groupStandings)
            .values({
              groupId: updated.groupId,
              participantId: pId,
              played: 1,
              won: isWinner ? 1 : 0,
              lost: !isWinner && !isDraw ? 1 : 0,
              draws: isDraw ? 1 : 0,
              pointsFor: pointsFor,
              pointsAgainst: pointsAgainst,
              totalPoints: pointsEarned,
              updatedAt: new Date(),
            })
            .onConflictDoUpdate({
              target: [
                schema.groupStandings.groupId,
                schema.groupStandings.participantId,
              ],
              set: {
                played: sql`${schema.groupStandings.played} + 1`,
                won: sql`${schema.groupStandings.won} + ${isWinner ? 1 : 0}`,
                lost: sql`${schema.groupStandings.lost} + ${!isWinner && !isDraw ? 1 : 0}`,
                draws: sql`${schema.groupStandings.draws} + ${isDraw ? 1 : 0}`,
                pointsFor: sql`${schema.groupStandings.pointsFor} + ${pointsFor}`,
                pointsAgainst: sql`${schema.groupStandings.pointsAgainst} + ${pointsAgainst}`,
                totalPoints: sql`${schema.groupStandings.totalPoints} + ${pointsEarned}`,
                updatedAt: new Date(),
              },
            });
        }
      }

      return updated;
    });
  }

  private async completeMatchInTx(
    tx: any,
    id: string,
    winnerId: string | null,
    details: {
      p1SetsWon: number;
      p2SetsWon: number;
      scoreDetails: Record<string, unknown> | null | undefined;
      auditUserId?: string | null;
      isBye?: boolean;
      expectedRevision?: number;
    },
  ) {
    const [existing] = await tx
      .select()
      .from(schema.matches)
      .where(eq(schema.matches.id, id))
      .limit(1);
…
  }

  async getEloHistory(
…
  ) {
    if (query.genderRestriction && query.genderRestriction !== '__NONE__') {
      const normalizedGenderRestriction = normalizeGenderRestriction(
        query.genderRestriction,
      );
      if (!normalizedGenderRestriction) {
        throw new BadRequestException('Invalid gender restriction');
      }
      return this.rankingsRepository.getEloHistory(userId, {
        ...query,
        genderRestriction: normalizedGenderRestriction,
      });
    }
    return this.rankingsRepository.getEloHistory(userId, query);
  }

  // Recalculate ELO for a single match manually (via Admin Endpoint)
  async updateMatchElo(dto: UpdateEloDto) {
    const db = this.rankingsRepository.getDbInstance();
    const [matchContext] = await db
      .select({
        status: schema.matches.status,
        isRanked: schema.tournaments.isRanked,
        tournamentType: schema.tournaments.tournamentType,
        communityId: schema.tournaments.communityId,
        categoryId: schema.tournaments.categoryId,
        matchType: schema.tournaments.matchType,
        genderRestriction: schema.tournaments.genderRestriction,
        divisionMatchType: schema.tournamentDivisions.matchType,
        divisionGenderRestriction: schema.tournamentDivisions.genderRestriction,
      })
      .from(schema.matches)
      .innerJoin(
        schema.tournaments,
        eq(schema.matches.tournamentId, schema.tournaments.id),
      )
      .innerJoin(
        schema.tournamentStages,
        eq(schema.matches.stageId, schema.tournamentStages.id),
      )
      .leftJoin(
        schema.tournamentDivisions,
        eq(
          schema.tournamentStages.tournamentDivisionId,
          schema.tournamentDivisions.id,
        ),
      )
      .where(eq(schema.matches.id, dto.matchId))
      .limit(1);

    if (!matchContext) {
      throw new BadRequestException('Trận đấu không tồn tại.');
    }
    if (matchContext.status !== 'COMPLETED') {
      throw new BadRequestException('Chỉ trận đã hoàn tất mới được tính ELO.');
    }
    if (!matchContext.isRanked) {
      throw new BadRequestException('Trận đấu thuộc giải không xếp hạng ELO.');
    }

    if (!(await this.hasEligibleRankingConsent(dto.matchId))) {
      throw new BadRequestException(
        'ELO is unavailable until every roster player has consented before match completion.',
      );
    }
    const effectiveMatchType =
      matchContext.divisionMatchType ?? matchContext.matchType;
    const rawEffectiveGenderRestriction =
      matchContext.divisionGenderRestriction ?? matchContext.genderRestriction;
    const effectiveGenderRestriction = rawEffectiveGenderRestriction
      ? normalizeGenderRestriction(rawEffectiveGenderRestriction)
      : null;
    if (rawEffectiveGenderRestriction && !effectiveGenderRestriction) {
      throw new BadRequestException('Cấu hình giới tính của trận đấu không hợp lệ.');
    }
    const requestedGenderRestriction = dto.genderRestriction
      ? normalizeGenderRestriction(dto.genderRestriction)
      : null;
    if (dto.genderRestriction && !requestedGenderRestriction) {
      throw new BadRequestException('Cấu hình giới tính không hợp lệ.');
    }
    if (
      effectiveMatchType === 'DOUBLES' ||
      effectiveMatchType === 'MIXED_DOUBLES'
    ) {
      throw new BadRequestException(
        'Trận đôi phải được tính ELO qua luồng hoàn tất trận, không dùng endpoint ELO thủ công cho user đơn.',
