        and(
          eq(schema.footballTeamMembers.teamId, schema.footballTeams.id),
          eq(schema.footballTeamMembers.userId, userId),
          eq(schema.footballTeamMembers.status, 'ACTIVE'),
        ),
      )
      .innerJoin(
        schema.users,
        eq(schema.users.id, schema.footballTeamMembers.userId),
      )
      .where(
