import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { Type } from 'class-transformer';
import {
  ArrayMaxSize,
  ArrayMinSize,
  IsArray,
  IsEmail,
  IsIn,
  IsOptional,
  IsString,
  IsUUID,
  MaxLength,
  ValidateIf,
  ValidateNested,
} from 'class-validator';

export const ADD_ATHLETE_SOURCES = ['FRIENDS', 'CLUB', 'DIRECT'] as const;
export type AddAthleteSource = (typeof ADD_ATHLETE_SOURCES)[number];

export const ADD_ATHLETE_ROLES = ['MAIN', 'PARTNER', 'RESERVE'] as const;
export type AddAthleteRole = (typeof ADD_ATHLETE_ROLES)[number];

export class AddAthletePlayerDto {
  @ApiPropertyOptional({ description: 'ID tài khoản ứng viên đã chọn' })
  @ValidateIf((player: AddAthletePlayerDto) => !player.displayName)
  @IsUUID()
  userId?: string;

  @ApiPropertyOptional({ description: 'Tên khách mời nhập trực tiếp' })
  @ValidateIf((player: AddAthletePlayerDto) => !player.userId)
  @IsString()
  @MaxLength(255)
  displayName?: string;

  @ApiPropertyOptional({ description: 'Email liên hệ khách mời' })
  @IsOptional()
  @IsEmail()
  @MaxLength(320)
  email?: string;

  @ApiPropertyOptional({ description: 'Số điện thoại liên hệ khách mời' })
  @IsOptional()
  @IsString()
  @MaxLength(30)
  phone?: string;

  @ApiPropertyOptional({ enum: ADD_ATHLETE_ROLES })
  @IsOptional()
  @IsIn(ADD_ATHLETE_ROLES)
  role?: AddAthleteRole;
}

export class AddAthletesDto {
  @ApiProperty({ enum: ADD_ATHLETE_SOURCES })
  @IsIn(ADD_ATHLETE_SOURCES)
  source: AddAthleteSource;

  @ApiPropertyOptional({ description: 'ID division / nội dung thi đấu' })
  @IsOptional()
  @IsUUID()
  divisionId?: string;

  @ApiPropertyOptional({ description: 'Tên đội / cặp đấu' })
  @IsOptional()
  @IsString()
  @MaxLength(255)
  teamName?: string;

  @ApiPropertyOptional({ description: 'Ghi chú ngắn của ban tổ chức' })
  @IsOptional()
  @IsString()
  @MaxLength(280)
  organizerNote?: string;

  @ApiProperty({ type: [AddAthletePlayerDto], maxItems: 30 })
  @IsArray()
  @ArrayMinSize(1)
  @ArrayMaxSize(30)
  @ValidateNested({ each: true })
  @Type(() => AddAthletePlayerDto)
  players: AddAthletePlayerDto[];
}

import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { Type } from 'class-transformer';
import { IsIn, IsInt, IsOptional, IsString, IsUUID, Max, MaxLength, Min } from 'class-validator';

export const ADD_ATHLETE_CANDIDATE_SOURCES = ['FRIENDS', 'CLUB'] as const;
export type AddAthleteCandidateSource = (typeof ADD_ATHLETE_CANDIDATE_SOURCES)[number];

export class AddAthleteCandidatesDto {
  @ApiProperty({ enum: ADD_ATHLETE_CANDIDATE_SOURCES })
  @IsIn(ADD_ATHLETE_CANDIDATE_SOURCES)
  source: AddAthleteCandidateSource;

  @ApiPropertyOptional()
  @IsOptional()
  @IsUUID()
  divisionId?: string;

  @ApiPropertyOptional({ maxLength: 100 })
  @IsOptional()
  @IsString()
  @MaxLength(100)
  search?: string;

  @ApiPropertyOptional({ maxLength: 1024 })
  @IsOptional()
  @IsString()
  @MaxLength(1024)
  cursor?: string;

  @ApiPropertyOptional({ minimum: 1, maximum: 100, default: 20 })
  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(100)
  limit?: number;
}

import { ApiProperty } from '@nestjs/swagger';
import { IsString, Length } from 'class-validator';

export class ClaimGuestRosterDto {
  @ApiProperty({ description: 'Bearer claim token from the one-time invitation' })
  @IsString()
  @Length(32, 128)
  claimToken: string;
}

