import { BadRequestException, Inject, Injectable } from '@nestjs/common';
import { PG_CONNECTION } from '../../../database/database.module';
import type { AppDb, AppDbOrTx } from '../../../database/db.types';
import * as schema from '../../../database/schema';
import { and, count, eq, inArray } from 'drizzle-orm';
import {
  CAPACITY_RESERVING_TEAM_STATUSES,
  calculateOccupiedCapacity,
  calculateRequestedTeamSlots,
  type CapacityEntry,
} from '../utils/tournament-participant-status';
import {
  IMPORT_SOURCES,
  type ImportSource,
} from '../dto/roster-import.dto';

/** Capacity is always expressed in team slots; `maxParticipants` stays a team limit. */
export interface TournamentCapacitySnapshot {
  occupiedTeamSlots: number;
  occupiedMemberSlots: number;
  maxTeamSlots: number | null;
  isFull: boolean;
}

/** The subset a caller needs to decide whether a claim fits. */
export type DivisionCapacityLimit = Pick<
  TournamentCapacitySnapshot,
  'occupiedTeamSlots' | 'maxTeamSlots' | 'isFull'
>;

/** Batched occupancy keyed by division id or tournament id. */
export type CapacityByScopeId = Record<string, TournamentCapacitySnapshot>;

export interface CapacityOwnerContext {
  tournamentConfig?: unknown;
}

/**
 * Single source of truth for tournament/division occupancy.
 *
 * Doubles pairing divisions consume one team slot per two active roster
 * members, so a single unpaired member occupies half a team. Singles and team
 * sports keep one participant/team record per slot. Only capacity-reserving
 * statuses count; waitlisted and terminal rows release their seats.
 */
…
/**
…
 *
 * A division-scoped claim reads its division's effective capacity, which
 * already inherits a parent cap that governs an uncapped division; a pair that
 * belongs to the tournament only is limited by the tournament itself.
 */
export async function readEffectiveCapacity(
  executor: AppDbOrTx,
  scope: { tournamentId: string; divisionId?: string | null },
): Promise<TournamentCapacitySnapshot> {
  if (!scope.divisionId) {
    return readTournamentCapacity(executor, scope.tournamentId);
  }

  return readDivisionCapacity(executor, scope.divisionId);
}

/** Tournament-wide occupancy for a page of tournaments in two queries. */
export async function readTournamentCapacities(
  executor: AppDbOrTx,
  tournamentIds: readonly string[],
): Promise<CapacityByScopeId> {
  const ids = [...new Set(tournamentIds.filter(Boolean))];
  if (ids.length === 0) return {};

  const tournaments = await selectTournamentOwners(executor, ids);
  return buildTournamentSnapshots(
    tournaments,
    ids,
    await selectParticipantEntries(executor, { tournamentIds: ids }),
  );
}

async function selectTournamentOwners(
  executor: AppDbOrTx,
  tournamentIds: readonly string[],
): Promise<CapacityOwnerRow[]> {
  return await executor
    .select({
      id: schema.tournaments.id,
      tournamentId: schema.tournaments.id,
      matchType: schema.tournaments.matchType,
      maxParticipants: schema.tournaments.maxParticipants,
      tournamentConfig: schema.tournaments.tournamentConfig,
    })
    .from(schema.tournaments)
    .where(inArray(schema.tournaments.id, [...tournamentIds]));
}

function buildTournamentSnapshots(
  tournaments: readonly CapacityOwnerRow[],
  tournamentIds: readonly string[],
  entries: readonly CapacityEntryRow[],
): CapacityByScopeId {
  const snapshots: CapacityByScopeId = {};
  const entriesByTournament = groupEntriesByScope(entries);

  for (const tournament of tournaments) {
    snapshots[tournament.id] = buildSnapshot(
      tournament,
      entriesByTournament[tournament.id] ?? [],
    );
  }
…
}

import { BadRequestException } from '@nestjs/common';

export const FOOTBALL_TEAM_SIZES = [5, 7, 11] as const;
export type FootballTeamSize = (typeof FOOTBALL_TEAM_SIZES)[number];

export interface FootballTeamConfigResolution {
  isTeamSport: boolean;
  mainSize: number;
  maxReserve: number;
  maxTotalSize: number;
}

export interface FootballTeamConfigValidationOptions {
  requireTeamSize?: boolean;
}

/**
 * Validate the persisted tournamentConfig boundary before registration starts.
 * The DTO intentionally keeps tournamentConfig extensible for other sports,
 * so football-specific invariants belong here instead of being trusted only
 * by the web/app selectors.
 */
export function assertValidFootballTeamConfig(
  input: unknown,
  options: FootballTeamConfigValidationOptions = {},
): void {
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    throw new BadRequestException('Cấu hình bóng đá không hợp lệ.');
  }

  const record = input as Record<string, unknown>;
  const rawTeamSize = record.teamSize;
  const rawMinTeamSize = record.minTeamSize;
  const teamSize = rawTeamSize === undefined ? undefined : Number(rawTeamSize);
  const minTeamSize = rawMinTeamSize === undefined ? undefined : Number(rawMinTeamSize);
  const isAllowedSize = (value: number | undefined): value is FootballTeamSize =>
    value !== undefined && Number.isInteger(value) && FOOTBALL_TEAM_SIZES.includes(value as FootballTeamSize);

  if (options.requireTeamSize && !isAllowedSize(teamSize)) {
    throw new BadRequestException('Bóng đá phải chọn sân 5, 7 hoặc 11 người.');
  }
  if (teamSize !== undefined && !isAllowedSize(teamSize)) {
    throw new BadRequestException('teamSize bóng đá chỉ nhận 5, 7 hoặc 11.');
  }
  if (minTeamSize !== undefined && !isAllowedSize(minTeamSize)) {
    throw new BadRequestException('minTeamSize bóng đá chỉ nhận 5, 7 hoặc 11.');
  }
  if (teamSize !== undefined && minTeamSize !== undefined && teamSize !== minTeamSize) {
    throw new BadRequestException('teamSize và minTeamSize phải cùng một cỡ sân.');
  }

  if (record.teamSizeOptions !== undefined) {
    if (!Array.isArray(record.teamSizeOptions) || record.teamSizeOptions.length === 0) {
      throw new BadRequestException('teamSizeOptions bóng đá không được rỗng.');
    }
    const optionsAreValid = record.teamSizeOptions.every((value) => isAllowedSize(Number(value)));
    if (!optionsAreValid || (teamSize !== undefined && !record.teamSizeOptions.some((value) => Number(value) === teamSize))) {
      throw new BadRequestException('teamSizeOptions bóng đá không khớp cỡ sân đã chọn.');
    }
  }

  const maxReserve = record.maxReserve === undefined ? 0 : Number(record.maxReserve);
  if (!Number.isInteger(maxReserve) || maxReserve < 0 || maxReserve > 20) {
    throw new BadRequestException('Số cầu thủ dự bị phải từ 0 đến 20.');
  }
  if (record.allowReserve === false && maxReserve > 0) {
    throw new BadRequestException('Không cho phép dự bị thì maxReserve phải bằng 0.');
  }

  const mainSize = teamSize ?? minTeamSize;
  const maxTeamSize = record.maxTeamSize === undefined ? undefined : Number(record.maxTeamSize);
  if (maxTeamSize !== undefined) {
    if (!Number.isInteger(maxTeamSize) || maxTeamSize < 0 || (mainSize !== undefined && maxTeamSize < mainSize)) {
      throw new BadRequestException('maxTeamSize phải đủ số cầu thủ chính của sân.');
    }
    if (mainSize !== undefined && maxTeamSize - mainSize < maxReserve) {
      throw new BadRequestException('maxTeamSize không đủ chỗ cho số cầu thủ dự bị.');
    }
  }

  for (const key of ['twoLegged', 'awayGoalsRule', 'penaltyShootout', 'allowDraw']) {
    if (record[key] !== undefined && typeof record[key] !== 'boolean') {
      throw new BadRequestException(`${key} bóng đá phải là boolean.`);
    }
  }
}

/**
 * Resolve all football roster limits from the legacy and current config shapes.
 * `teamSize` remains the selected format; `teamSizeOptions` is only a legacy
 * fallback for records created before the selector stored that value.
 */

export class TournamentPaymentRepository {
  constructor(@Inject(PG_CONNECTION) private readonly db: AppDb) {}
  async assertEntryFeeChangeAllowed(
    tx: AppDbOrTx,
    tournament: {
      id: string;
      status: string;
      isRegistrationLocked: boolean | null;
    },
    currentEntryFee: string | number | null | undefined,
    nextEntryFee: number | null | undefined,
    currentOverrideEnabled?: boolean | null,
    nextOverrideEnabled?: boolean | null,
  ) {
