  async addAthletes(
    tournamentId: string,
    userId: string,
    systemRoles: string[],
    dto: AddAthletesDto,
    broadcast: RegistrationChanged,
  ) {
    await this.getManagedAddableTournament(tournamentId, userId, systemRoles);
    this.assertAddAthletePayload(dto);

    const created = await this.db.transaction(async (tx) => {
      await lockCapacityOwner(tx, {
        tournamentId,
        divisionId: dto.divisionId,
      });
      const tournament = await this.getTransactionalTournament(tx, tournamentId);
      this.assertAddableTournament(tournament);
      const division = dto.divisionId
        ? await this.getTournamentDivision(tx, tournamentId, dto.divisionId)
        : null;
      const players = await this.resolveAddAthletes(
        tx,
        tournament,
        userId,
        dto,
      );
      const matchType = division?.matchType ?? tournament.matchType;
      this.assertRosterComposition(
        tournament,
        matchType,
        players,
      );
      await this.assertNoExistingRoster(
        tx,
        tournamentId,
        dto.divisionId ?? null,
        players,
      );
      const capacity = await readEffectiveCapacity(tx, {
        tournamentId,
        divisionId: dto.divisionId,
      });
      assertDivisionHasRoom(
        capacity,
        matchType,
        players.length,
        { tournamentConfig: tournament.tournamentConfig },
      );

      const entryFee = await this.tournamentPaymentRepository
        .resolveDivisionEntryFee(tx, tournament, dto.divisionId)
        .then(Number);
      if (!Number.isFinite(entryFee) || entryFee < 0) {
        throw new BadRequestException('Lệ phí giải đấu không hợp lệ.');
      }
      const [participant] = await tx
        .insert(schema.tournamentParticipants)
        .values({
          tournamentId,
          tournamentDivisionId: dto.divisionId ?? null,
          registeredBy: userId,
          teamName:
            dto.teamName?.trim() ||
            players.map((player) => player.displayName).join(' / '),
          teamStatus: 'COMPLETE',
          rankingConsent: Boolean(tournament.isRanked),
          organizerNote: dto.organizerNote?.trim() || null,
          isPaid: entryFee === 0,
          isPresent: false,
          entryFeeAtRegistration: entryFee.toFixed(2),
          isMock: false,
          isWildcard: false,
        })
        .returning();
      if (!participant) {
        throw new BadRequestException('Không thể thêm VĐV vào giải đấu.');
      }

      const accountPlayers = players.filter(
        (player): player is ResolvedAddAthlete & { userId: string } =>
          player.userId !== null,
      );
      const rosters =
        accountPlayers.length > 0
          ? await tx
              .insert(schema.tournamentRosters)
              .values(
                accountPlayers.map((player) => ({
                  participantId: participant.id,
                  userId: player.userId,
                  role: player.role,
                  status: 'ACTIVE',
                })),
              )
              .returning({
                id: schema.tournamentRosters.id,
                userId: schema.tournamentRosters.userId,
              })
          : [];

      const pendingGuests = await this.insertGuestRosters(
        tx,
        participant.id,
        players.filter((player) => player.userId === null),
      );
      await this.auditService.logCreate(
        tx,
        userId,
        'tournament_participants',
        participant.id,
        participant,
      );
      for (const roster of rosters) {
        await this.auditService.logCreate(
          tx,
          userId,
          'tournament_rosters',
          roster.id,
          {
            participantId: participant.id,
            userId: roster.userId,
          },
        );
      }
      for (const guest of pendingGuests) {
        await this.auditService.logCreate(
          tx,
          userId,
          'tournament_guest_rosters',
          guest.guestId,
          {
            participantId: participant.id,
            role: guest.role,
            claimExpiresAt: guest.claimExpiresAt,
          },
        );
      }
      return { participant, rosters, pendingGuests };
    });

    const claims = await this.deliverGuestClaims(
      created.pendingGuests,
      tournamentId,
      created.participant.tournamentId,
      created.participant.teamName,
    );
    await this.notifyAddedAccounts(
      created.rosters,
      tournamentId,
      created.participant.teamName,
      created.participant.tournamentDivisionId,
    );
    broadcast(tournamentId, {
      participantId: created.participant.id,
      divisionId: created.participant.tournamentDivisionId,
      action: 'PARTICIPANT_ADDED',
    });
    return { participant: created.participant, claims };
  }

  async claimGuestRoster(
    tournamentId: string,
    guestId: string,
    userId: string,
    claimToken: string,
    broadcast: RegistrationChanged,
  ) {
…
  }

