  async claimGuestRoster(
    tournamentId: string,
    guestId: string,
    userId: string,
    claimToken: string,
    broadcast: RegistrationChanged,
  ) {
    const claimHash = createHash('sha256').update(claimToken).digest('hex');
    const claimed = await this.db.transaction(async (tx) => {
      const [user] = await tx
        .select({
          email: schema.users.email,
          isEmailVerified: schema.users.isEmailVerified,
          deletedAt: schema.users.deletedAt,
        })
        .from(schema.users)
        .where(eq(schema.users.id, userId))
        .for('share')
        .limit(1);
      if (!user || !user.isEmailVerified || user.deletedAt) {
        throw new ForbiddenException('Cần email đã xác minh để nhận suất.');
      }

      const [guest] = await tx
        .select()
        .from(schema.tournamentGuestRosters)
        .where(eq(schema.tournamentGuestRosters.id, guestId))
        .for('update')
        .limit(1);
      if (
        !guest ||
        guest.claimExpiresAt <= new Date() ||
        !isMatchingClaimHash(guest.claimTokenHash, claimHash)
      ) {
        throw new ConflictException('Mã nhận suất không hợp lệ hoặc đã hết hạn.');
      }
      if (
        guest.contactEmail &&
        normalizeEmail(guest.contactEmail) !== normalizeEmail(user.email)
      ) {
        throw new ForbiddenException(
          'Tài khoản phải dùng email đã nhận lời mời.',
        );
      }

      const [context] = await tx
        .select({
          participantId: schema.tournamentParticipants.id,
          tournamentId: schema.tournamentParticipants.tournamentId,
          divisionId: schema.tournamentParticipants.tournamentDivisionId,
          participantStatus: schema.tournamentParticipants.teamStatus,
          tournamentName: schema.tournaments.name,
          tournamentStatus: schema.tournaments.status,
          tournamentEndDate: schema.tournaments.endDate,
          tournamentDeletedAt: schema.tournaments.deletedAt,
          isRanked: schema.tournaments.isRanked,
        })
        .from(schema.tournamentParticipants)
        .innerJoin(
          schema.tournaments,
          eq(
            schema.tournaments.id,
            schema.tournamentParticipants.tournamentId,
          ),
        )
        .where(eq(schema.tournamentParticipants.id, guest.participantId))
        .for('share')
        .limit(1);
      this.assertClaimContext(context, tournamentId);
      await this.assertNoExistingRoster(
        tx,
        tournamentId,
        null,
        [{ userId, displayName: '', email: null, phone: null, role: guest.role }],
      );

      const [roster] = await tx
        .insert(schema.tournamentRosters)
        .values({
          participantId: guest.participantId,
          userId,
          role: guest.role,
          status: 'ACTIVE',
        })
        .returning({
          id: schema.tournamentRosters.id,
          participantId: schema.tournamentRosters.participantId,
          userId: schema.tournamentRosters.userId,
        });
      if (!roster) {
        throw new ConflictException('Không thể nhận suất tham gia.');
      }
      await tx
        .delete(schema.tournamentGuestRosters)
        .where(eq(schema.tournamentGuestRosters.id, guestId));
      await this.auditService.logDelete(
        tx,
        userId,
        'tournament_guest_rosters',
        guestId,
        { participantId: guest.participantId, role: guest.role },
      );
      await this.auditService.logCreate(
        tx,
        userId,
        'tournament_rosters',
        roster.id,
        {
          participantId: roster.participantId,
          userId: roster.userId,
          role: guest.role,
        },
      );
      return { roster, context };
    });

    await this.notifyAddedAccounts(
      [{ id: claimed.roster.id, userId }],
      tournamentId,
      claimed.context.tournamentName,
      claimed.context.divisionId,
    );
    broadcast(tournamentId, {
      participantId: claimed.roster.participantId,
      divisionId: claimed.context.divisionId,
      action: 'GUEST_CLAIMED',
    });
…
  }

