  private decodeCandidateCursor(
    encoded: string | undefined,
    scope: Pick<AddAthleteCursor, 'source' | 'divisionId' | 'search'>,
  ): AddAthleteCursor | null {
    if (!encoded) return null;
    const cursor =
      CursorPaginationHelper.decodeCursor<Partial<AddAthleteCursor>>(encoded);
    if (
      !cursor ||
      typeof cursor.displayName !== 'string' ||
      typeof cursor.userId !== 'string' ||
      !isUuid(cursor.userId) ||
      cursor.source !== scope.source ||
      cursor.divisionId !== scope.divisionId ||
      cursor.search !== scope.search
    ) {
      throw new BadRequestException('Cursor ứng viên không hợp lệ.');
    }
    return cursor as AddAthleteCursor;
  }

