  private async getSourceUserIds(
    executor: AppDbOrTx,
    tournament: AdminTournament,
    managerId: string,
    source: 'FRIENDS' | 'CLUB',
    selectedIds?: string[],
  ): Promise<string[]> {
    if (source === 'FRIENDS') {
      return this.getAcceptedFriendIds(executor, managerId, selectedIds);
    }
    return this.getJoinedClubMemberIds(
      executor,
      tournament.communityId,
      selectedIds,
    );
  }

  private async getAcceptedFriendIds(
    executor: AppDbOrTx,
    managerId: string,
    selectedIds?: string[],
  ): Promise<string[]> {
    if (selectedIds?.length === 0) return [];
    const selection =
      selectedIds && selectedIds.length > 0
        ? or(
            and(
              eq(schema.friendships.senderId, managerId),
              inArray(schema.friendships.receiverId, selectedIds),
            ),
            and(
              eq(schema.friendships.receiverId, managerId),
              inArray(schema.friendships.senderId, selectedIds),
            ),
          )
        : undefined;
    const relations = await executor
      .select({
        senderId: schema.friendships.senderId,
        receiverId: schema.friendships.receiverId,
      })
      .from(schema.friendships)
      .where(
        and(
          eq(schema.friendships.status, 'ACCEPTED'),
          isNull(schema.friendships.deletedAt),
          or(
            eq(schema.friendships.senderId, managerId),
            eq(schema.friendships.receiverId, managerId),
          ),
          selection,
        ),
      )
      .for('share');
    return [
      ...new Set(
        relations.map((relation) =>
          relation.senderId === managerId
            ? relation.receiverId
            : relation.senderId,
        ),
      ),
    ];
  }

  private async getJoinedClubMemberIds(
    executor: AppDbOrTx,
    communityId: string | null,
    selectedIds?: string[],
  ): Promise<string[]> {
    if (!communityId || selectedIds?.length === 0) return [];
    const members = await executor
      .select({ userId: schema.communityMembers.userId })
      .from(schema.communityMembers)
      .where(
        and(
          eq(schema.communityMembers.communityId, communityId),
          eq(schema.communityMembers.status, 'JOINED'),
          selectedIds?.length
            ? inArray(schema.communityMembers.userId, selectedIds)
            : undefined,
        ),
      )
      .for('share');
    return [...new Set(members.map((member) => member.userId))];
  }

  private assertAddAthletePayload(dto: AddAthletesDto): void {
    if (!dto.players.length) {
      throw new BadRequestException('Cần chọn ít nhất một VĐV.');
    }
    const userIds = new Set<string>();
    const emails = new Set<string>();
    for (const player of dto.players) {
      if (dto.source === 'DIRECT') {
        if (player.userId || !player.displayName?.trim()) {
          throw new BadRequestException('Thông tin VĐV nhập trực tiếp không hợp lệ.');
        }
        const email = player.email ? normalizeEmail(player.email) : '';
        if (email && emails.has(email)) {
          throw new BadRequestException('Email khách mời bị trùng.');
        }
        if (email) emails.add(email);
      } else if (
        !player.userId ||
        player.displayName !== undefined ||
        player.email !== undefined ||
        player.phone !== undefined
      ) {
        throw new BadRequestException('Danh sách ứng viên không hợp lệ.');
      }
      if (player.userId && userIds.has(player.userId)) {
        throw new BadRequestException('Không thể thêm trùng VĐV.');
      }
      if (player.userId) userIds.add(player.userId);
    }
  }

