    };
    const guest = {
      id: 'guest-1',
      participantId: 'participant-1',
      displayName: 'Athlete',
      role: 'MAIN',
      contactEmail: 'ATHLETE@example.com',
      contactPhone: null,
      claimTokenHash: createHash('sha256').update(claimToken).digest('hex'),
      claimExpiresAt: new Date(Date.now() + 60_000),
      createdAt: new Date(),
    };
    const participantContext = {
      participantId: 'participant-1',
      tournamentId: 'tournament-1',
      divisionId: null,
      participantStatus: 'COMPLETE',
      tournamentName: 'Open event',
      tournamentStatus: 'REGISTRATION_OPEN',
      tournamentEndDate: new Date(Date.now() + 60_000),
      tournamentDeletedAt: null,
      isRanked: true,
    };
    const roster = {
      id: 'roster-1',
      participantId: 'participant-1',
      userId: 'user-1',
    };
    const readRows = (table: unknown) => {
      if (table === schema.users) return [claimant];
      if (table === schema.tournamentGuestRosters) {
        return guestDeleted ? [] : [guest];
      }
      if (table === schema.tournamentParticipants) return [participantContext];
      return [];
    };
    type MockQuery = {
      from: (table: unknown) => MockQuery;
      innerJoin: (..._args: unknown[]) => MockQuery;
      where: (..._args: unknown[]) => MockQuery;
      for: (..._args: unknown[]) => MockQuery;
      limit: (..._args: unknown[]) => MockQuery;
      then: (
        resolve: (value: unknown) => unknown,
        reject?: (reason: unknown) => unknown,
      ) => Promise<unknown>;
    };
    const transactionExecutor = {
      select: () => {
        let table: unknown;
        let query: MockQuery;
        query = {
          from: (value) => {
            table = value;
            return query;
          },
          innerJoin: () => query,
          where: () => query,
          for: () => query,
          limit: () => query,
          then: (resolve, reject) =>
            Promise.resolve(readRows(table)).then(resolve, reject),
        };
        return query;
      },
      insert: (table: unknown) => ({
        values: (values: Record<string, unknown>) => {
          if (table === schema.tournamentRosters) insertedRoster = values;
          return { returning: async () => [roster] };
        },
      }),
      delete: () => ({
        where: async () => {
          guestDeleted = true;
        },
      }),
    };
    dbMock.transaction.mockImplementation((callback) =>
      Promise.resolve(callback(transactionExecutor)),
    );
    const broadcast = jest.fn();

    await expect(
      admin.claimGuestRoster(
        'tournament-1',
        'guest-1',
        'user-1',
        claimToken,
        broadcast,
      ),
    ).resolves.toEqual({ participantId: 'participant-1', claimed: true });
    await expect(
      admin.claimGuestRoster(
        'tournament-1',
        'guest-1',
        'user-1',
        claimToken,
        broadcast,
      ),
    ).rejects.toBeInstanceOf(ConflictException);

    expect(insertedRoster).toMatchObject({ role: 'MAIN', status: 'ACTIVE' });
    expect(broadcast).toHaveBeenCalledTimes(1);
    expect(guestDeleted).toBe(true);
  });

});

