    const readRows = (table: unknown) => {
      if (table === schema.users) return [claimant];
      if (table === schema.tournamentGuestRosters) {
        return guestDeleted ? [] : [guest];
      }
      if (table === schema.tournamentParticipants) return [participantContext];
      return [];
    };
    type MockQuery = {
      from: (table: unknown) => MockQuery;
      innerJoin: (..._args: unknown[]) => MockQuery;
      where: (..._args: unknown[]) => MockQuery;
      for: (..._args: unknown[]) => MockQuery;
      limit: (..._args: unknown[]) => MockQuery;
      then: (
        resolve: (value: unknown) => unknown,
        reject?: (reason: unknown) => unknown,
      ) => Promise<unknown>;
    };
    const transactionExecutor = {
      select: () => {
        let table: unknown;
        let query: MockQuery;
        query = {
          from: (value) => {
            table = value;
            return query;
          },
          innerJoin: () => query,
          where: () => query,
          for: () => query,
          limit: () => query,
          then: (resolve, reject) =>
            Promise.resolve(readRows(table)).then(resolve, reject),
        };
        return query;
      },
      insert: (table: unknown) => ({
        values: (values: Record<string, unknown>) => {
          if (table === schema.tournamentRosters) insertedRoster = values;
          return { returning: async () => [roster] };
        },
      }),
      delete: () => ({
        where: async () => {
          guestDeleted = true;
        },
      }),
    };
    dbMock.transaction.mockImplementation((callback) =>
