import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { Type } from 'class-transformer';
import {
  ArrayMaxSize,
  ArrayMinSize,
  IsArray,
  IsEmail,
  IsIn,
  IsOptional,
  IsString,
  IsUUID,
  MaxLength,
  ValidateIf,
  ValidateNested,
} from 'class-validator';

export const ADD_ATHLETE_SOURCES = ['FRIENDS', 'CLUB', 'DIRECT'] as const;
export type AddAthleteSource = (typeof ADD_ATHLETE_SOURCES)[number];

export const ADD_ATHLETE_ROLES = ['MAIN', 'PARTNER', 'RESERVE'] as const;
export type AddAthleteRole = (typeof ADD_ATHLETE_ROLES)[number];

export class AddAthletePlayerDto {
  @ApiPropertyOptional({ description: 'ID tài khoản ứng viên đã chọn' })
  @ValidateIf((player: AddAthletePlayerDto) => !player.displayName)
  @IsUUID()
  userId?: string;

  @ApiPropertyOptional({ description: 'Tên khách mời nhập trực tiếp' })
  @ValidateIf((player: AddAthletePlayerDto) => !player.userId)
  @IsString()
  @MaxLength(255)
  displayName?: string;

  @ApiPropertyOptional({ description: 'Email liên hệ khách mời' })
  @IsOptional()
  @IsEmail()
  @MaxLength(320)
  email?: string;

  @ApiPropertyOptional({ description: 'Số điện thoại liên hệ khách mời' })
  @IsOptional()
  @IsString()
  @MaxLength(30)
  phone?: string;

  @ApiPropertyOptional({ enum: ADD_ATHLETE_ROLES })
  @IsOptional()
  @IsIn(ADD_ATHLETE_ROLES)
  role?: AddAthleteRole;
}

export class AddAthletesDto {
  @ApiProperty({ enum: ADD_ATHLETE_SOURCES })
  @IsIn(ADD_ATHLETE_SOURCES)
  source: AddAthleteSource;

  @ApiPropertyOptional({ description: 'ID division / nội dung thi đấu' })
  @IsOptional()
  @IsUUID()
  divisionId?: string;

  @ApiPropertyOptional({ description: 'Tên đội / cặp đấu' })
  @IsOptional()
  @IsString()
  @MaxLength(255)
  teamName?: string;

  @ApiPropertyOptional({ description: 'Ghi chú ngắn của ban tổ chức' })
  @IsOptional()
  @IsString()
  @MaxLength(280)
  organizerNote?: string;

  @ApiProperty({ type: [AddAthletePlayerDto], maxItems: 30 })
  @IsArray()
  @ArrayMinSize(1)
  @ArrayMaxSize(30)
  @ValidateNested({ each: true })
  @Type(() => AddAthletePlayerDto)
  players: AddAthletePlayerDto[];
}

/**
 * Resolve all football roster limits from the legacy and current config shapes.
 * `teamSize` remains the selected format; `teamSizeOptions` is only a legacy
 * fallback for records created before the selector stored that value.
 */
export function resolveFootballTeamConfig(input: unknown): FootballTeamConfigResolution {
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    return { isTeamSport: false, mainSize: 0, maxReserve: 0, maxTotalSize: Number.MAX_SAFE_INTEGER };
  }

  const record = input as Record<string, unknown>;
  const explicitSize = Number(record.teamSize);
  const minSize = Number(record.minTeamSize);
  const option = Array.isArray(record.teamSizeOptions)
    ? record.teamSizeOptions.map(Number).find((size) => FOOTBALL_TEAM_SIZES.includes(size as FootballTeamSize))
    : undefined;
  const mainSize = [explicitSize, minSize, option ?? 0].find(
    (size) => Number.isInteger(size) && FOOTBALL_TEAM_SIZES.includes(size as FootballTeamSize),
  ) ?? 0;
  const isTeamSport = mainSize > 0 || record.teamSize !== undefined || record.minTeamSize !== undefined || option !== undefined;
  if (!isTeamSport) {
    return { isTeamSport: false, mainSize: 0, maxReserve: 0, maxTotalSize: Number.MAX_SAFE_INTEGER };
  }

  const configuredReserve = Number(record.maxReserve ?? 0);
  const maxReserve = record.allowReserve === false
    ? 0
    : Number.isFinite(configuredReserve) && configuredReserve > 0
      ? Math.floor(configuredReserve)
      : 0;
  const configuredMax = Number(record.maxTeamSize);
  const maxTotalSize = Number.isInteger(configuredMax) && configuredMax >= mainSize
    ? configuredMax
    : mainSize + maxReserve;

  return { isTeamSport: true, mainSize, maxReserve, maxTotalSize };
}

/** Preserve legacy non-team tournaments while resolving football team sizes once. */
export function getRequiredFootballMainRosterCount(config: unknown): number {
  const resolved = resolveFootballTeamConfig(config);
  return resolved.isTeamSport ? resolved.mainSize : 1;
}

