import { Category } from "./category";
import type { RegistrationFormConfig } from "@/features/tournaments/registration-form";

export enum MatchTypeUI {
  MALE_SINGLES = "MALE_SINGLES",
  FEMALE_SINGLES = "FEMALE_SINGLES",
  MALE_DOUBLES = "MALE_DOUBLES",
  FEMALE_DOUBLES = "FEMALE_DOUBLES",
  MIXED_DOUBLES = "MIXED_DOUBLES",
}

export enum MatchTypeDB {
  SINGLES = "SINGLES",
  DOUBLES = "DOUBLES",
  MIXED_DOUBLES = "MIXED_DOUBLES",
}

export enum GenderRestriction {
  MALE = "MALE",
  FEMALE = "FEMALE",
  MIXED = "MIXED",
}

export type SportRuleKind =
  | "BADMINTON"
  | "TABLE_TENNIS"
  | "PICKLEBALL_RALLY"
  | "PICKLEBALL_SIDE_OUT"
  | "TENNIS"
  | "FOOTBALL";
export type SportScoringModel =
  "RALLY_POINT_SET" | "TENNIS_SET" | "PICKLEBALL_SIDE_OUT";

export interface SportRuleScoringConfig {
  mode?: "LITE" | "STRICT";
  /** Legacy/Quick scoring discriminator; FREE and OPEN mean unbounded sets. */
  scoringMode?: string;
  scoring_mode?: string;
  rulesPreset?: string;
  kind?: SportRuleKind;
  scoringModel?: SportScoringModel;
  setsToWin?: number;
  sets_to_win?: number;
  pointsPerSet?: number;
  points_per_set?: number;
  winByTwo?: boolean;
  mustWinByTwo?: boolean;
  deuceEnabled?: boolean;
  deuce_enabled?: boolean;
  tiebreakAt?: number;
  tiebreak_at?: number;
  tiebreakPoints?: number;
  tiebreak_points?: number;
  maxPoints?: number;
  max_points?: number;
  maxPointsPerSet?: number;
  maxDeucePoints?: number | null;
  superTiebreakEnabled?: boolean;
  superTiebreakSetIndex?: number | null;
  superTiebreakPoints?: number | null;
  [key: string]: unknown;
}

export interface SportRulesEnvelope extends SportRuleScoringConfig {
  version?: number;
  kind?: SportRuleKind;
  scoringModel?: SportScoringModel;
  format?: Record<string, unknown>;
  scoring?: SportRuleScoringConfig;
}

export interface StageRoundRuleConfig extends SportRuleScoringConfig {
  venue_id?: string | null;
  scheduled_date?: string | null;
  custom_notes?: string | null;
}

export interface StageRoundConfig extends SportRuleScoringConfig {
  roundsToPlay?: number;
  rounds_to_play?: number;
  max_sets?: number;
  deuce_gap?: number;
  scoring_type?: string;
  advance_count?: number;
  allow_player_choice_court?: boolean;
  time_limit_minutes?: number;
  custom_notes?: string | null;
  rounds?: Record<string, StageRoundRuleConfig>;
  advanceMapping?: {
    numGroups?: number;
    teamsAdvancing?: number;
    allowWildcard?: boolean;
    wildcardTeams?: number;
    totalAdvancing?: number;
  };
}
/**
 * Additive roster-weighted capacity projection for a division.
 *
 * `maxParticipants` is a TEAM limit, so doubles/mixed divisions report
 * fractional `occupiedTeamSlots`: one active roster member holds half a team.
 * WAITLISTED and terminal states reserve nothing. Aggregates only — the
 * projection never carries participant identity. `_count.participants` and
 * `_summary.participantCount` stay plain participant row counts.
 */
export interface TournamentDivisionCapacity {
  occupiedTeamSlots: number;
  occupiedMemberSlots: number;
  maxTeamSlots: number | null;
  isFull: boolean;
}

export interface ParentTournament {
  id: string;
  name: string;
  description?: string;
  bannerUrl?: string;
  logoUrl?: string;
  createdBy: string;
  createdAt: string;
  updatedAt: string;
}

export interface Tournament {
  id: string;
  name: string;
  description?: string;
  bannerUrl?: string;
  startDate?: string;
  endDate?: string;
  city?: string | null;
  locationAddress?: string;
  registrationStartDate?: string;
  registrationEndDate?: string;
  sportRules?: SportRulesEnvelope;
  status:
    | "DRAFT"
    | "PENDING_APPROVAL"
    | "PENDING_DELETE"
    | "UPCOMING"
    | "REGISTRATION_OPEN"
    | "REGISTRATION_CLOSED"
    | "IN_PROGRESS"
    | "ONGOING"
    | "COMPLETED"
    | "CANCELLED";
  format:
    | "SINGLE_ELIMINATION"
    | "DOUBLE_ELIMINATION"
    | "ROUND_ROBIN"
    | "GROUP_STAGE_KNOCKOUT";
  maxParticipants?: number;
  entryFee?: number;
  platformFeePercentage?: string;
  platformFeeThreshold?: string;
  platformFeeFixedAmount?: string;
  platformFeePerPlayer?: number;
  tournamentType?: "CLUB" | "PUBLIC";
  matchType?: "SINGLES" | "DOUBLES" | "MIXED_DOUBLES";
  communityId?: string | null;
  inviteCode?: string | null;
  visibility?: "PUBLIC" | "PRIVATE";
  genderRestriction?: "MALE" | "FEMALE" | "MIXED" | null;
  venueId?: string | null;
  isRanked?: boolean;
  isRegistrationLocked?: boolean;
  isLite?: boolean;
  venue?: {
    id: string;
    name: string;
    locationAddress: string;
  } | null;
  courtsCount?: number;
  courtCount?: number;
  currency: string;
  categoryId: string;
  logoUrl?: string | null;
  galleryImages?: string[];
  prizeDescription?: string | null;
  contactInfo?: {
    phone?: string;
    email?: string;
    [key: string]: string | undefined;
  } | null;
  category?: Category;
  organizerId: string;
  organizer?: {
    id: string;
    fullName: string;
    avatarUrl?: string | null;
    isTrusted?: boolean;
  };
  _count?: {
    participants: number;
    matches: number;
  };
  _summary?: {
    participantCount: number;
    matchesTotal: number;
    matchesCompleted: number;
    matchesLive: number;
  };
  /** Division-level server capacity projection when the read exposes one. */
  capacity?: TournamentDivisionCapacity | null;
  parentId?: string | null;
  parent?: ParentTournament | null;
  divisions?:
    | {
        id: string;
        name: string;
        matchType: string;
        genderRestriction?: string | null;
        status: string;
        categoryId: string;
        _count?: {
          participants: number;
          matches: number;
        };
        maxParticipants?: number;
        /** Server capacity projection; see {@link TournamentDivisionCapacity}. */
        capacity?: TournamentDivisionCapacity | null;
        entryFee?: number;
        entryFeeOverride?: number | null;
        effectiveEntryFee?: number;
        entryFeeOverrideEnabled?: boolean;
        inviteCode?: string | null;
      }[]
    | null;
  tournamentConfig?: {
    isLite?: boolean;
    mode?: "LITE" | "ADVANCED" | "STRICT";
    scoringMode?: string;
    scoring_mode?: string;
    bracketType?: string;
    maxTeams?: number;
    seedingMethod?: "ELO" | "RANDOM" | "MANUAL";
    thirdPlaceMatch?: boolean;
    minElo?: number | null;
    maxElo?: number | null;
    maxCombinedElo?: number | null;
    maxTeammateGap?: number | null;
    registrationMode?: "OPEN" | "APPROVAL" | "INVITE_ONLY";
    doublesPairingMode?: "ORGANIZER" | "SELF";
    registrationForm?: RegistrationFormConfig;
    hideFeaturedCardText?: boolean;
    // Team sport (bóng đá)
    teamSize?: 5 | 7 | 11;
    teamSizeOptions?: Array<5 | 7 | 11>;
    minTeamSize?: number;
    maxTeamSize?: number;
    maxReserve?: number;
    location?: {
      venueName?: string;
      address?: string;
      province?: string;
      district?: string;
      ward?: string;
      display?: string;
    };
    twoLegged?: boolean;
    awayGoalsRule?: boolean;
    penaltyShootout?: boolean;
    allowDraw?: boolean;
    recurring?: {
      enabled?: boolean;
      frequency?: "DAILY" | "WEEKLY" | "BIWEEKLY" | "MONTHLY" | string;
      dayOfWeek?: number;
      daysOfWeek?: number[];
      time?: string;
      [key: string]: unknown;
    };
  } | null;
  /** Normalized by GET /tournaments/public for banner rendering. */
  hideFeaturedCardText?: boolean;
  createdAt?: string;
  updatedAt?: string;
}

export interface GroupStageKnockoutConfig {
  groupsConfig: {
    numGroups: number;
    teamsPerGroup: number;
    roundsToPlay: number;
  };
  advancementConfig: {
    teamsAdvancing: number;
    allowWildcardThird: boolean;
