                                        ? `${registrationTranslate('paidStatus')}: ${Number(paymentAmount).toLocaleString(locale === 'vi' ? 'vi-VN' : 'en-US')} ${paymentCurrency}`
                                        : registrationTranslate('paidStatus')
                                      : registrationTranslate('unpaidStatus')
                                }
                                className="h-5 w-5 cursor-pointer rounded border-slate-300 text-blue-600 focus:ring-2 focus:ring-blue-500 disabled:cursor-wait"
                              />
                              {hasSystemPayment(participant) ? (
                                <span className="text-[10px] font-semibold uppercase tracking-wide text-slate-400">
                                  {registrationTranslate('paymentHeader')}
                                </span>
                              ) : null}
                            </div>
                          )}
