      !cursor ||
      typeof cursor.displayName !== 'string' ||
      typeof cursor.userId !== 'string' ||
      !isUuid(cursor.userId) ||
      cursor.source !== scope.source ||
      cursor.divisionId !== scope.divisionId ||
      cursor.search !== scope.search
    ) {
      throw new BadRequestException('Cursor ứng viên không hợp lệ.');
    }
    return cursor as AddAthleteCursor;
  }

  private async getSourceUserIds(
    executor: AppDbOrTx,
    tournament: AdminTournament,
    managerId: string,
    source: 'FRIENDS' | 'CLUB',
    selectedIds?: string[],
  ): Promise<string[]> {
    if (source === 'FRIENDS') {
      return this.getAcceptedFriendIds(executor, managerId, selectedIds);
    }
    return this.getJoinedClubMemberIds(
      executor,
      tournament.communityId,
      selectedIds,
    );
  }

  private async getAcceptedFriendIds(
    executor: AppDbOrTx,
    managerId: string,
    selectedIds?: string[],
  ): Promise<string[]> {
    if (selectedIds?.length === 0) return [];
    const selection =
      selectedIds && selectedIds.length > 0
        ? or(
            and(
              eq(schema.friendships.senderId, managerId),
              inArray(schema.friendships.receiverId, selectedIds),
            ),
            and(
              eq(schema.friendships.receiverId, managerId),
              inArray(schema.friendships.senderId, selectedIds),
            ),
          )
        : undefined;
    const relations = await executor
      .select({
        senderId: schema.friendships.senderId,
        receiverId: schema.friendships.receiverId,
      })
      .from(schema.friendships)
      .where(
        and(
          eq(schema.friendships.status, 'ACCEPTED'),
          isNull(schema.friendships.deletedAt),
          or(
            eq(schema.friendships.senderId, managerId),
            eq(schema.friendships.receiverId, managerId),
          ),
          selection,
        ),
      )
      .for('share');
    return [
      ...new Set(
        relations.map((relation) =>
          relation.senderId === managerId
            ? relation.receiverId
            : relation.senderId,
        ),
      ),
    ];
  }

