            Xin chào ${escapeHtml(args.participantName ?? 'bạn')},
          </p>
          <p style="font-size: 14px; color: #334155; margin: 0 0 16px;">
            Ban tổ chức đã thêm bạn vào giải
            <strong>${escapeHtml(args.tournamentName)}</strong>.
          </p>
          <div style="background-color: #fef3c7; border-left: 4px solid #f59e0b; padding: 12px 16px; margin-bottom: 20px;">
            <p style="font-size: 14px; color: #78350f; margin: 0;">
              Muốn được tính Elo và lưu lịch sử trận đấu, bạn cần bấm xác nhận.
              <br />
              Chỉ những trận <strong>hoàn thành từ lúc bạn xác nhận</strong> mới được
              tính — các trận đã đấu trước đó không tính.
            </p>
          </div>
          <a href="${escapeHtml(args.link)}" style="background-color: #2563eb; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 8px; font-weight: bold; font-size: 14px; display: inline-block;">
            Đăng nhập để xác nhận
          </a>
          <p style="font-size: 13px; color: #64748b; margin: 20px 0 0;">
            Không xác nhận? Bạn vẫn thi đấu bình thường, chỉ là không có Elo.
          </p>
        </div>
      </div>
    `;
  }

  private buildGuestClaimHtml(args: {
    displayName: string;
    tournamentName: string;
    link: string;
  }): string {
    return `
      <div style="font-family: system-ui, -apple-system, sans-serif; max-width: 560px;">
        <p>Xin chào ${escapeHtml(args.displayName)},</p>
        <p>Ban tổ chức đã ghi danh bạn vào giải <strong>${escapeHtml(args.tournamentName)}</strong>.</p>
        <p>Đăng nhập bằng email này để nhận suất tham gia:</p>
        <a href="${escapeHtml(args.link)}">Nhận suất tham gia</a>
      </div>
    `;
  }
}

const HTML_ESCAPE_MAP: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => HTML_ESCAPE_MAP[character]);
}

