  React.useEffect(() => {
…
    setSelectedIds([]);
    setPlayers(createPlayers(initialRequiredPlayerCount));
    setTeamName('');
    setOrganizerNote('');
    setCandidateError(false);
    setSubmitError('');
  }, [initialDivisionId, initialRequiredPlayerCount, open]);

  const switchSource = (value: AddAthleteSource) => {
    setSource(value);
    setSelectedIds([]);
    setRows([]);
    setNextCursor(null);
    setCandidateError(false);
  };

  const submit = async () => {
    if (submitting || requiredPlayerCount === 0) return;
    const rosterCountValid = players.length >= requiredPlayerCount && players.length <= maxPlayerCount;
    if (source === 'DIRECT' && (!rosterCountValid || players.some((player) => !player.displayName.trim()))) return;
    if (source !== 'DIRECT' && (!rosterCountValid || selectedIds.length < requiredPlayerCount || selectedIds.length > maxPlayerCount)) return;
    setSubmitting(true);
    setSubmitError('');
    try {
      const response = await tournamentsApi.addAthletes(tournament.id, {
        source,
        ...(divisionId ? { divisionId } : {}),
        ...(teamName.trim() ? { teamName: teamName.trim() } : {}),
        players: source === 'DIRECT'
          ? players.map((player, index) => ({
              displayName: player.displayName.trim(),
              ...(player.email.trim() ? { email: player.email.trim() } : {}),
              ...(player.phone.trim() ? { phone: player.phone.trim() } : {}),
              role: rosterRoleForIndex(index, isTeamSport, requiredPlayerCount),
            }))
          : selectedIds.map((userId, index) => ({
              userId,
              role: rosterRoleForIndex(index, isTeamSport, requiredPlayerCount),
            })),
        ...(organizerNote.trim() ? { organizerNote: organizerNote.trim().slice(0, 280) } : {}),
      });
      if (!response.data) throw new Error(t('addFailed'));
      const payload = response.data.data ?? response.data;
