  async listAddAthleteCandidates(
    tournamentId: string,
    userId: string,
    systemRoles: string[],
    dto: AddAthleteCandidatesDto,
  ) {
    const tournament = await this.getManagedAddableTournament(
      tournamentId,
      userId,
      systemRoles,
    );
    if (dto.divisionId) {
      await this.getTournamentDivision(this.db, tournamentId, dto.divisionId);
    }
    const sourceUserIds = await this.getSourceUserIds(
      this.db,
      tournament,
      userId,
      dto.source,
    );
    if (sourceUserIds.length === 0) return { items: [], nextCursor: null };

    const limit = dto.limit ?? 20;
    const search = dto.search?.trim() ?? '';
    const cursor = this.decodeCandidateCursor(dto.cursor, {
      source: dto.source,
      divisionId: dto.divisionId ?? null,
      search,
    });
    const activeRosterQuery = this.db
      .select({ id: schema.tournamentRosters.id })
