  private async getManagedAddableTournament(
    tournamentId: string,
    userId: string,
    systemRoles: string[],
  ): Promise<AdminTournament> {
    const tournament = await this.tournamentsRepository.findById(tournamentId);
    if (!tournament || tournament.deletedAt) {
      throw new NotFoundException('Giải đấu không tồn tại');
    }
    const allowed = await this.tournamentAccessService.isManager(
      tournament,
      userId,
      systemRoles,
    );
    if (!allowed) throw new ForbiddenException('Bạn không có quyền quản lý giải đấu');
    this.assertAddableTournament(tournament);
    return tournament;
  }

  private assertAddableTournament(tournament: AddableTournament): void {
    if (tournament.deletedAt) throw new NotFoundException('Giải đấu không tồn tại');
    if (
      tournament.status === 'COMPLETED' ||
      tournament.status === 'CANCELLED' ||
      (tournament.endDate && tournament.endDate <= new Date())
    ) {
      throw new BadRequestException('Không thể thêm VĐV vào giải đã kết thúc.');
    }
    if (
      tournament.isRegistrationLocked ||
      ['REGISTRATION_CLOSED', 'IN_PROGRESS', 'ONGOING', 'PENDING_DELETE'].includes(
        tournament.status,
      )
    ) {
      throw new BadRequestException('Đăng ký giải đấu đã đóng.');
    }
  }

