      if (table === schema.tournamentParticipants) return [participantContext];
      return [];
    };
    const queryEvents: Array<{ table: unknown; lock: unknown }> = [];
    type MockQuery = {
      from: (table: unknown) => MockQuery;
      innerJoin: (..._args: unknown[]) => MockQuery;
      where: (..._args: unknown[]) => MockQuery;
      for: (..._args: unknown[]) => MockQuery;
      limit: (..._args: unknown[]) => MockQuery;
