    const transactionExecutor = {
      select: () => {
        let table: unknown;
        let event: { table: unknown; lock: unknown } | undefined;
        let query: MockQuery;
        query = {
          from: (value) => {
            table = value;
            event = { table, lock: null };
            queryEvents.push(event);
            return query;
          },
          innerJoin: () => query,
          where: () => query,
          for: (mode) => {
            if (event) event.lock = mode;
            return query;
