    );
    const duplicateCheckIndex = eventsAfterFirstClaim.findIndex(
      (event) => event.table === schema.tournamentRosters,
    );
    expect(ownerLockIndex).toBeGreaterThanOrEqual(0);
    expect(ownerLockIndex).toBeLessThan(duplicateCheckIndex);
    expect(insertedRoster).toMatchObject({ role: 'MAIN', status: 'ACTIVE' });
    expect(broadcast).toHaveBeenCalledTimes(1);
