      }
    } catch (err) {
      console.warn(
        'Failed to fetch scoreDetails for admin ELO update, scoreFactor disabled:',
        err.message,
      );
    }

    const result = await db.transaction(async (tx) => {
      await tx.execute(
        sql`select pg_advisory_xact_lock(hashtext(${dto.matchId}))`,
