      .where(
        and(
          eq(schema.tournamentRosters.userId, schema.users.id),
          eq(schema.tournamentRosters.status, 'ACTIVE'),
          eq(schema.tournamentParticipants.tournamentId, tournamentId),
          inArray(
            schema.tournamentParticipants.teamStatus,
            [...CAPACITY_RESERVING_TEAM_STATUSES],
          ),
          dto.divisionId
            ? eq(
                schema.tournamentParticipants.tournamentDivisionId,
                dto.divisionId,
              )
            : undefined,
        ),
      );
    const rows = await this.db
      .select({
        userId: schema.users.id,
        displayName: schema.profiles.fullName,
        avatarUrl: schema.profiles.avatarUrl,
      })
      .from(schema.profiles)
      .innerJoin(schema.users, eq(schema.users.id, schema.profiles.userId))
      .where(
        and(
          inArray(schema.users.id, sourceUserIds),
          eq(schema.users.isMock, false),
          isNull(schema.users.deletedAt),
          notExists(activeRosterQuery),
          search ? ilike(schema.profiles.fullName, `%${search}%`) : undefined,
          cursor
            ? or(
                gt(schema.profiles.fullName, cursor.displayName),
                and(
                  eq(schema.profiles.fullName, cursor.displayName),
                  gt(schema.users.id, cursor.userId),
                ),
              )
            : undefined,
        ),
      )
      .orderBy(asc(schema.profiles.fullName), asc(schema.users.id))
      .limit(limit + 1);

    const hasMore = rows.length > limit;
    const candidateRows = rows.slice(0, limit).map((row) => ({
      ...row,
      source: dto.source,
    }));
    const last = candidateRows[candidateRows.length - 1];
    return {
      rows: candidateRows,
      nextCursor:
        hasMore && last
          ? CursorPaginationHelper.encodeCursor({
              displayName: last.displayName,
              divisionId: dto.divisionId ?? null,
              search,
              source: dto.source,
              userId: last.userId,
            })
          : null,
    };
  }

