import type { AppDb } from '../../database/db.types';
import * as schema from '../../database/schema';
import type { AuditService } from '../audit/audit.service';
import { MatchesRepository } from './matches.repository';

const MATCH_COMPLETED_AT = new Date('2026-06-01T10:00:00.000Z');
const CONSENTED_BEFORE_MATCH = new Date('2026-06-01T09:00:00.000Z');
const CONSENTED_AFTER_MATCH = new Date('2026-06-01T11:00:00.000Z');

type EnqueueOptions = {
  consentedAt?: Date | null;
  completedAt?: Date | null;
  participant2Id?: string | null;
  hasGuestRoster?: boolean;
  isRanked?: boolean;
};

function createCompletionHarness(options: EnqueueOptions = {}) {
  const participant2Id =
    options.participant2Id === undefined ? 'participant-2' : options.participant2Id;
  const existing = {
    id: 'match-1',
    tournamentId: 'tournament-1',
    status: 'ONGOING',
    participant1Id: 'participant-1',
    participant2Id,
    winnerId: null,
    nextMatchId: null,
    loserNextMatchId: null,
    tieId: null,
    leg: null,
    groupId: null,
    isBye: false,
    p1SetsWon: 0,
    p2SetsWon: 0,
  };
  const updated = {
    ...existing,
    status: 'COMPLETED',
    winnerId: 'participant-1',
    completedAt:
      options.completedAt === undefined
        ? MATCH_COMPLETED_AT
        : options.completedAt,
    scoreDetails: {},
  };
  const participantIds = [existing.participant1Id, existing.participant2Id].filter(
    (participantId): participantId is string => participantId !== null,
  );
  const consentedAt =
    options.consentedAt === undefined
      ? CONSENTED_BEFORE_MATCH
      : options.consentedAt;
  const outboxRows: unknown[] = [];

  type Query = {
    from: (table: unknown) => Query;
    innerJoin: (...args: unknown[]) => Query;
    leftJoin: (...args: unknown[]) => Query;
    where: (...args: unknown[]) => Query;
    limit: (...args: unknown[]) => Query;
    then: (
      resolve: (value: unknown) => unknown,
      reject?: (reason: unknown) => unknown,
    ) => Promise<unknown>;
  };

  const transaction = {
    select: () => {
      let table: unknown;
      let joined = false;
      let query: Query;
      query = {
        from: (value) => {
          table = value;
          return query;
        },
        innerJoin: () => {
          joined = true;
          return query;
        },
        leftJoin: () => {
          joined = true;
          return query;
        },
        where: () => query,
        limit: () => query,
        then: (resolve, reject) =>
          Promise.resolve(
            table === schema.matches
              ? [existing]
              : table === schema.tournaments
                ? [{ isRanked: options.isRanked ?? true }]
                : table === schema.tournamentParticipants
                  ? participantIds.map(() => ({ isMock: false }))
                  : table === schema.tournamentRosters && joined
                    ? []
                    : table === schema.tournamentRosters
                      ? participantIds.map((participantId) => ({
                          participantId,
                          rankingConsentAt: consentedAt,
                        }))
                      : table === schema.tournamentGuestRosters &&
                          options.hasGuestRoster
                        ? [{ participantId: 'participant-1' }]
                        : [],
          ).then(resolve, reject),
      };
      return query;
    },
    update: () => ({
      set: () => ({
        where: () => ({ returning: async () => [updated] }),
      }),
    }),
    insert: (table: unknown) => ({
      values: (value: unknown) => {
        if (table === schema.matchEloOutbox) outboxRows.push(value);
        return { onConflictDoNothing: async () => undefined };
      },
    }),
  };
  const audit = { logUpdate: jest.fn().mockResolvedValue(undefined) };
  const repository = new MatchesRepository(
    {} as AppDb,
    audit as unknown as AuditService,
  );
  const completeMatchInTx = (
    repository as unknown as {
      completeMatchInTx: (
        tx: unknown,
        id: string,
        winnerId: string | null,
        details: {
          p1SetsWon: number;
          p2SetsWon: number;
          scoreDetails: Record<string, unknown> | null;
        },
      ) => Promise<unknown>;
    }
  ).completeMatchInTx;

  return {
    complete: () =>
      completeMatchInTx.call(repository, transaction, 'match-1', 'participant-1', {
        p1SetsWon: 1,
        p2SetsWon: 0,
        scoreDetails: {},
      }),
    outboxRows,
  };
}

describe('MatchesRepository ranked ELO outbox consent gate', () => {
  it('enqueues when both participant rosters consented before completion', async () => {
    const harness = createCompletionHarness();

    await harness.complete();

    expect(harness.outboxRows).toHaveLength(1);
  });

  it('does not enqueue when consent was recorded after completion', async () => {
    const harness = createCompletionHarness({
      consentedAt: CONSENTED_AFTER_MATCH,
    });

    await harness.complete();

    expect(harness.outboxRows).toHaveLength(0);
  });

  it('does not enqueue a participant with an unclaimed guest roster', async () => {
    const harness = createCompletionHarness({ hasGuestRoster: true });

    await harness.complete();

    expect(harness.outboxRows).toHaveLength(0);
  });

  it('does not enqueue when either match side is missing', async () => {
    const harness = createCompletionHarness({ participant2Id: null });

    await harness.complete();

    expect(harness.outboxRows).toHaveLength(0);
  });

  it('does not enqueue when the completion timestamp is missing', async () => {
    const harness = createCompletionHarness({ completedAt: null });

    await harness.complete();

    expect(harness.outboxRows).toHaveLength(0);
  });
});

