  await page.getByRole('button', { name: 'Thêm VĐV' }).click();
  const dialog = page.getByRole('dialog', { name: 'Thêm VĐV' });
  const checkboxes = dialog.getByRole('checkbox');
  await expect(checkboxes).toHaveCount(7);
  for (let index = 0; index < 7; index += 1) {
    await checkboxes.nth(index).check();
  }
  await expect(dialog.getByText('VĐV chính', { exact: true })).toHaveCount(5);
  await expect(dialog.getByText('VĐV dự bị', { exact: true })).toHaveCount(2);
  await dialog.getByRole('button', { name: 'Thêm vào giải' }).click();

  await expect.poll(() => addRequest).toEqual({
    source: 'FRIENDS',
    divisionId,
    players: [
      { userId: 'registered-1', role: 'MAIN' },
      { userId: 'registered-2', role: 'MAIN' },
      { userId: 'registered-3', role: 'MAIN' },
      { userId: 'registered-4', role: 'MAIN' },
      { userId: 'registered-5', role: 'MAIN' },
      { userId: 'registered-6', role: 'RESERVE' },
      { userId: 'registered-7', role: 'RESERVE' },
    ],
  });
});

