import { Injectable, Inject, Logger, Optional } from '@nestjs/common';
import {
  and,
  eq,
  gt,
  inArray,
  isNull,
  lt,
  notInArray,
  or,
} from 'drizzle-orm';
import { PG_CONNECTION } from '../../../database/database.module';
import type { AppDb } from '../../../database/db.types';
import * as schema from '../../../database/schema';
import { MailService } from '../../../providers/mail/mail.service';
import { CAPACITY_RESERVING_TEAM_STATUSES } from '../utils/tournament-participant-status';

/**
 * Thông báo consent không mang token và chỉ gửi cho roster user đã xác minh email.
 * Claim guest sử dụng một link token riêng, một-lần, gửi trực tiếp về email nhập.
 *
 * Tự động nhắc tối đa 3 lần rồi dừng; không có nút gửi lại phía ban tổ chức.
 */
export const CONSENT_MAX_NOTIFICATIONS = 3;

/** Số giờ chờ trước mỗi lần nhắc, tính từ lần gửi gần nhất. */
export const CONSENT_REMINDER_DELAYS_HOURS = [24, 72] as const;

const FINAL_TOURNAMENT_STATUSES: Record<string, true> = {
  CANCELLED: true,
  COMPLETED: true,
};

type ConsentDispatchKind = 'INITIAL' | 'REMINDER';

interface ConsentScheduleRow {
  attempts: number;
  consentNotifiedAt: Date | null;
  joinedAt: Date | null;
}

@Injectable()
export class RankingConsentService {
  private readonly logger = new Logger(RankingConsentService.name);

  constructor(
    @Inject(PG_CONNECTION) private readonly db: AppDb,
    @Optional() private readonly mailService?: MailService,
  ) {}

  private buildFrontendLink(path: string, claimToken?: string): string | null {
    const configuredUrl =
      process.env.FRONTEND_URL ?? 'http://localhost:3001';
    try {
      const base = new URL(configuredUrl);
      if (
        (base.protocol !== 'http:' && base.protocol !== 'https:') ||
        base.username ||
        base.password
      ) {
        return null;
      }

      const link = new URL(path, base.origin);
      if (link.origin !== base.origin) return null;
      if (claimToken) {
        link.hash = new URLSearchParams({ token: claimToken }).toString();
      }
      return link.toString();
    } catch {
      return null;
    }
  }

  /** Gửi ngay cho một roster row cụ thể (dùng khi vừa thêm người). */
  async sendConfirmationRequest(rosterId: string): Promise<boolean> {
    return this.dispatch(rosterId, 'INITIAL');
  }

  async sendGuestClaimInvite(args: {
    email: string;
    displayName: string;
    tournamentName: string;
    tournamentId: string;
    guestId: string;
    claimToken: string;
  }): Promise<boolean> {
    if (!this.mailService) return false;
    const link = this.buildFrontendLink(
      `/tournaments/${encodeURIComponent(args.tournamentId)}/guest-claim/${encodeURIComponent(args.guestId)}`,
      args.claimToken,
    );
    if (!link) return false;

    const tournamentName = args.tournamentName.replace(/[\r\n]+/g, ' ').trim();
    try {
      return await this.mailService.sendMail(
        args.email,
        `[Sporto] Xác nhận suất tham gia: ${tournamentName}`,
        this.buildGuestClaimHtml({
          displayName: args.displayName,
          tournamentName,
          link,
        }),
      );
    } catch {
      this.logger.warn('Gửi mail claim guest thất bại.');
      return false;
    }
  }

  /** Nhắc lại cho những ai đã quá hạn mà chưa xác nhận. */
  async sendDueReminders(): Promise<number> {
    if (!this.mailService) return 0;
    const now = new Date();

    // Keep rows whose notifiedAt is NULL: failed delivery must not consume an
    // attempt or silently end all reminders.
    const due = await this.db
      .select({
        id: schema.tournamentRosters.id,
        attempts: schema.tournamentRosters.consentNotifiedCount,
        consentNotifiedAt: schema.tournamentRosters.consentNotifiedAt,
        joinedAt: schema.tournamentRosters.joinedAt,
      })
      .from(schema.tournamentRosters)
      .innerJoin(
        schema.users,
        eq(schema.users.id, schema.tournamentRosters.userId),
      )
      .innerJoin(
        schema.tournamentParticipants,
        eq(
          schema.tournamentParticipants.id,
          schema.tournamentRosters.participantId,
        ),
      )
      .innerJoin(
        schema.tournaments,
        eq(schema.tournaments.id, schema.tournamentParticipants.tournamentId),
      )
      .where(
        and(
          isNull(schema.tournamentRosters.rankingConsentAt),
          eq(schema.tournamentRosters.status, 'ACTIVE'),
          inArray(
            schema.tournamentParticipants.teamStatus,
            [...CAPACITY_RESERVING_TEAM_STATUSES],
          ),
          eq(schema.users.isEmailVerified, true),
          isNull(schema.users.deletedAt),
          eq(schema.tournaments.isRanked, true),
          isNull(schema.tournaments.deletedAt),
          notInArray(schema.tournaments.status, [
            'COMPLETED',
            'CANCELLED',
          ]),
          or(
            isNull(schema.tournaments.endDate),
            gt(schema.tournaments.endDate, now),
          ),
          lt(
            schema.tournamentRosters.consentNotifiedCount,
            CONSENT_MAX_NOTIFICATIONS,
          ),
        ),
      );

    let sent = 0;
    for (const row of due) {
      if (!this.isReminderDue(row, now)) continue;
      if (await this.dispatch(row.id, 'REMINDER')) sent += 1;
    }
    return sent;
  }

  private isReminderDue(row: ConsentScheduleRow, now: Date): boolean {
    if (row.attempts >= CONSENT_MAX_NOTIFICATIONS) return false;
    const anchor = row.consentNotifiedAt ?? row.joinedAt;
    if (!anchor) return false;
    const delayHours =
      CONSENT_REMINDER_DELAYS_HOURS[
        Math.min(
          Math.max(row.attempts - 1, 0),
          CONSENT_REMINDER_DELAYS_HOURS.length - 1,
        )
      ];
    return now.getTime() - new Date(anchor).getTime() >= delayHours * 3_600_000;
  }

  /**
   * Gửi 1 mail và ghi nhận số lần đã gửi.
   *
   * Chỉ tăng bộ đếm khi gửi THÀNH CÔNG — nếu không, một hệ thống mail hỏng sẽ đốt
   * hết 3 lượt nhắc rồi im lặng, biến "chưa gửi được" thành "đã bỏ qua".
   */
  private async dispatch(
    rosterId: string,
    kind: ConsentDispatchKind,
  ): Promise<boolean> {
    const mailService = this.mailService;
    if (!mailService) return false;

    try {
      return await this.db.transaction(async (tx) => {
        const [row] = await tx
          .select({
            userEmail: schema.users.email,
            userEmailVerified: schema.users.isEmailVerified,
            userDeletedAt: schema.users.deletedAt,
            participantName: schema.tournamentParticipants.teamName,
            participantStatus: schema.tournamentParticipants.teamStatus,
            tournamentName: schema.tournaments.name,
            tournamentId: schema.tournaments.id,
            tournamentStatus: schema.tournaments.status,
            tournamentEndDate: schema.tournaments.endDate,
            tournamentDeletedAt: schema.tournaments.deletedAt,
            isRanked: schema.tournaments.isRanked,
            attempts: schema.tournamentRosters.consentNotifiedCount,
            consentNotifiedAt: schema.tournamentRosters.consentNotifiedAt,
            consentedAt: schema.tournamentRosters.rankingConsentAt,
            joinedAt: schema.tournamentRosters.joinedAt,
            rosterStatus: schema.tournamentRosters.status,
          })
          .from(schema.tournamentRosters)
          .innerJoin(
…
          )
          .innerJoin(
…
          )
          .innerJoin(
…
          )
          .where(eq(schema.tournamentRosters.id, rosterId))
          .for('update')
          .limit(1);
…
      });
    } catch {
…
    }
  }
…
}

@Injectable()
export class RankingConsentService {
…
  private async dispatch(
…
  ): Promise<boolean> {
…
    try {
      return await this.db.transaction(async (tx) => {
        const [row] = await tx
          .select({
…
            attempts: schema.tournamentRosters.consentNotifiedCount,
            consentNotifiedAt: schema.tournamentRosters.consentNotifiedAt,
            consentedAt: schema.tournamentRosters.rankingConsentAt,
            joinedAt: schema.tournamentRosters.joinedAt,
            rosterStatus: schema.tournamentRosters.status,
          })
          .from(schema.tournamentRosters)
          .innerJoin(
            schema.users,
            eq(schema.users.id, schema.tournamentRosters.userId),
          )
          .innerJoin(
            schema.tournamentParticipants,
            eq(
              schema.tournamentParticipants.id,
              schema.tournamentRosters.participantId,
            ),
          )
          .innerJoin(
            schema.tournaments,
            eq(
              schema.tournaments.id,
              schema.tournamentParticipants.tournamentId,
            ),
          )
          .where(eq(schema.tournamentRosters.id, rosterId))
          .for('update')
          .limit(1);

        const now = new Date();
        if (
          !row ||
          !row.userEmail ||
          !row.userEmailVerified ||
          row.userDeletedAt ||
          !row.isRanked ||
          row.consentedAt ||
          row.rosterStatus !== 'ACTIVE' ||
          !CAPACITY_RESERVING_TEAM_STATUSES.some(
            (status) => status === row.participantStatus,
          ) ||
          row.tournamentDeletedAt ||
          FINAL_TOURNAMENT_STATUSES[row.tournamentStatus] ||
          (row.tournamentEndDate && row.tournamentEndDate <= now) ||
          row.attempts >= CONSENT_MAX_NOTIFICATIONS ||
          (kind === 'INITIAL' && row.attempts !== 0) ||
          (kind === 'REMINDER' && !this.isReminderDue(row, now))
        ) {
          return false;
        }

        const link = this.buildFrontendLink(
          `/tournaments/${encodeURIComponent(row.tournamentId)}`,
        );
        if (!link) return false;
        const isReminder = kind === 'REMINDER';
        const subject = isReminder
          ? 'Nhắc xác nhận tham gia giải đấu'
          : 'Xác nhận tham gia giải đấu';
        const tournamentName = row.tournamentName
          .replace(/[\r\n]+/g, ' ')
          .trim();
        const sent = await mailService.sendMail(
          row.userEmail,
          `[Sporto] ${subject}: ${tournamentName}`,
          this.buildHtml({
            participantName: row.participantName,
            tournamentName,
            link,
            isReminder,
          }),
        );
        if (!sent) return false;

        await tx
          .update(schema.tournamentRosters)
          .set({
            consentNotifiedAt: now,
            consentNotifiedCount: row.attempts + 1,
          })
          .where(eq(schema.tournamentRosters.id, rosterId));
        return true;
      });
    } catch {
      this.logger.warn(`Gửi mail xác nhận thất bại cho roster ${rosterId}.`);
      return false;
    }
  }

  private buildHtml(args: {
    participantName: string | null;
    tournamentName: string;
    link: string;
    isReminder: boolean;
  }): string {
    const heading = args.isReminder
      ? 'Bạn chưa xác nhận tham gia'
      : 'Bạn được thêm vào một giải đấu';
    return `
      <div style="font-family: system-ui, -apple-system, sans-serif; max-width: 560px;">
        <div style="background-color: #0f172a; padding: 20px; border-radius: 8px 8px 0 0;">
          <h1 style="color: #ffffff; font-size: 18px; margin: 0;">${heading}</h1>
        </div>
        <div style="background-color: #ffffff; padding: 24px; border: 1px solid #e2e8f0; border-top: none;">
          <p style="font-size: 14px; color: #0f172a; margin: 0 0 16px;">
            Xin chào ${escapeHtml(args.participantName ?? 'bạn')},
          </p>
          <p style="font-size: 14px; color: #334155; margin: 0 0 16px;">
            Ban tổ chức đã thêm bạn vào giải
            <strong>${escapeHtml(args.tournamentName)}</strong>.
          </p>
          <div style="background-color: #fef3c7; border-left: 4px solid #f59e0b; padding: 12px 16px; margin-bottom: 20px;">
            <p style="font-size: 14px; color: #78350f; margin: 0;">
              Muốn được tính Elo và lưu lịch sử trận đấu, bạn cần bấm xác nhận.
              <br />
              Chỉ những trận <strong>hoàn thành từ lúc bạn xác nhận</strong> mới được
              tính — các trận đã đấu trước đó không tính.
            </p>
          </div>
          <a href="${escapeHtml(args.link)}" style="background-color: #2563eb; color: #ffffff; padding: 12px 28px; text-decoration: none; border-radius: 8px; font-weight: bold; font-size: 14px; display: inline-block;">
            Đăng nhập để xác nhận
          </a>
          <p style="font-size: 13px; color: #64748b; margin: 20px 0 0;">
            Không xác nhận? Bạn vẫn thi đấu bình thường, chỉ là không có Elo.
          </p>
        </div>
      </div>
    `;
  }

  private buildGuestClaimHtml(args: {
    displayName: string;
    tournamentName: string;
    link: string;
  }): string {
    return `
      <div style="font-family: system-ui, -apple-system, sans-serif; max-width: 560px;">
        <p>Xin chào ${escapeHtml(args.displayName)},</p>
        <p>Ban tổ chức đã ghi danh bạn vào giải <strong>${escapeHtml(args.tournamentName)}</strong>.</p>
        <p>Đăng nhập bằng email này để nhận suất tham gia:</p>
        <a href="${escapeHtml(args.link)}">Nhận suất tham gia</a>
      </div>
    `;
  }
}

import { Injectable, Logger, Inject } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { PG_CONNECTION } from '../../database/database.module';
import type { AppDb } from '../../database/db.types';
import * as schema from '../../database/schema';
import { eq, and, lte, ne, isNull, isNotNull, sql } from 'drizzle-orm';
import {
  evaluateTournamentCleanup,
  TOURNAMENT_CLEANUP_GRACE_DAYS,
} from './utils/tournament-cleanup-policy';
import { TournamentRegistrationService } from './services/tournament-registration.service';
import { RankingConsentService } from './services/ranking-consent.service';

@Injectable()
export class TournamentSchedulerService {
  private readonly logger = new Logger(TournamentSchedulerService.name);

  constructor(
    @Inject(PG_CONNECTION) private readonly db: AppDb,
    private readonly tournamentRegistrationService: TournamentRegistrationService,
    private readonly rankingConsentService: RankingConsentService,
  ) {}

  /**
   * Nhắc xác nhận ELO tự động, tối đa 3 lần rồi dừng.
   *
   * Hourly, not 5-minutely: the delays are measured in hours, so a finer tick would
 * only re-check the same rows and burn queries.
   */
  @Cron(CronExpression.EVERY_HOUR)
  async handleRankingConsentReminders() {
    try {
      const sent = await this.rankingConsentService.sendDueReminders();
      if (sent > 0) {
        this.logger.log(`Đã gửi ${sent} nhắc xác nhận Elo.`);
      }
    } catch (err) {
      this.logger.error(
        `Nhắc xác nhận Elo thất bại: ${
          err instanceof Error ? err.message : String(err)
        }`,
      );
    }
  }
  @Cron('*/5 * * * *')
  async handleRegistrationsTimeout() {
    await this.tournamentRegistrationService.processPendingRegistrationTimeout();
  }

  @Cron(CronExpression.EVERY_5_MINUTES)
  async handleAutoCloseRegistration() {
    this.logger.log('Running auto-close registration cron job...');
    try {
      const now = new Date();
      // Find tournaments that are open but past registration end date
      const expiredTournaments = await this.db
        .select()
        .from(schema.tournaments)
        .where(
          and(
            eq(schema.tournaments.status, 'REGISTRATION_OPEN'),
            lte(schema.tournaments.registrationEndDate, now)
          )
        );

      if (expiredTournaments.length === 0) {
        return;
      }

      this.logger.log(`Found ${expiredTournaments.length} tournament(s) to close registration.`);

      for (const tournament of expiredTournaments) {
        await this.db
          .update(schema.tournaments)
          .set({
            status: 'REGISTRATION_CLOSED',
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(schema.tournaments.id, tournament.id),
              eq(schema.tournaments.status, 'REGISTRATION_OPEN'),
            ),
          );

        this.logger.log(`Tournament ${tournament.id} ("${tournament.name}") registration auto-closed.`);
      }
    } catch (err) {
      this.logger.error('Error in handleAutoCloseRegistration cron job:', err.message);
    }
  }

  /** Đồng bộ các giải đã qua thời điểm kết thúc về trạng thái COMPLETED. */
  @Cron(CronExpression.EVERY_5_MINUTES)
  async handleAutoCompleteExpiredTournaments() {
    this.logger.log('Running auto-complete expired tournaments cron job...');
    try {
      const now = new Date();
      const completed = await this.db
        .update(schema.tournaments)
        .set({ status: 'COMPLETED', updatedAt: now })
        .where(
          and(
            isNull(schema.tournaments.deletedAt),
            isNotNull(schema.tournaments.endDate),
            lte(schema.tournaments.endDate, now),
            sql`${schema.tournaments.status} IN ('REGISTRATION_OPEN', 'REGISTRATION_CLOSED', 'UPCOMING', 'IN_PROGRESS')`,
          ),
        )
        .returning({ id: schema.tournaments.id, name: schema.tournaments.name });

      if (completed.length > 0) {
        this.logger.log(`Auto-completed ${completed.length} expired tournament(s).`);
      }
    } catch (err) {
      this.logger.error('Error in handleAutoCompleteExpiredTournaments cron job:', err.message);
    }
  }

  @Cron(CronExpression.EVERY_5_MINUTES)
  async handleAutoOpenRegistration() {
    this.logger.log('Running auto-open registration cron job...');
    try {
      const now = new Date();
      // REGISTRATION_OPEN is an explicit organizer decision. Never downgrade
      // it because a stale/future registrationStartDate is still stored: the
      // "open now" action intentionally overrides that date. New scheduled
      // tournaments are created as UPCOMING and are handled below.
      const openingTournaments = await this.db
        .select()
        .from(schema.tournaments)
        .where(
          and(
            eq(schema.tournaments.status, 'UPCOMING'),
            lte(schema.tournaments.registrationStartDate, now),
            eq(schema.tournaments.isRegistrationLocked, false),
          )
        );

      if (openingTournaments.length === 0) return;

      this.logger.log(`Found ${openingTournaments.length} tournament(s) to open registration.`);

      for (const tournament of openingTournaments) {
        await this.db
          .update(schema.tournaments)
          .set({
            status: 'REGISTRATION_OPEN',
            updatedAt: now,
          })
          .where(eq(schema.tournaments.id, tournament.id));

        // Gửi thông báo cho người theo dõi
        const followers = await this.db
          .select({ userId: schema.tournamentFollows.userId })
          .from(schema.tournamentFollows)
          .where(eq(schema.tournamentFollows.tournamentId, tournament.id));

        if (followers.length > 0) {
          const notiData = followers.map(f => ({
            receiverId: f.userId,
            type: 'TOURNAMENT_REGISTRATION_OPEN',
            title: `${tournament.name} đã mở đăng ký`,
            content: `Giải đấu "${tournament.name}" đã mở đăng ký tham gia.`,
            redirectUrl: `/tournaments/${tournament.id}`,
          }));
          await this.db.insert(schema.notifications).values(notiData);
          this.logger.log(`Sent ${notiData.length} notifications to followers of ${tournament.id}`);
        }

        this.logger.log(`Tournament ${tournament.id} ("${tournament.name}") registration auto-opened.`);
      }
    } catch (err) {
      this.logger.error('Error in handleAutoOpenRegistration cron job:', err.message);
    }
  }

  calculateNextRecurringDate(frequency: string, daysOfWeek: number[] | number, timeOfDay: string, fromDate = new Date()): Date {
    const [hours, minutes] = (timeOfDay || '18:00').split(':').map(Number);
    const target = new Date(fromDate);
    target.setHours(hours, minutes, 0, 0);

    if (frequency === 'DAILY') {
      target.setDate(target.getDate() + 1);
      return target;
    }

    if (frequency === 'MONTHLY') {
      target.setMonth(target.getMonth() + 1);
      return target;
    }

    const days: number[] = Array.isArray(daysOfWeek)
      ? daysOfWeek.length > 0 ? daysOfWeek : [6]
      : [typeof daysOfWeek === 'number' ? daysOfWeek : 6];
…
  }
