import { expect, test } from '@playwright/test';
import { fulfillApi, openManage, tournamentId } from './support/organizer-manage';

const divisionId = 'synthetic-wide-division';

test('organizer keeps a one-time guest handoff link available until finishing', async ({ page }) => {
  let addRequest: Record<string, unknown> | undefined;
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes/candidates**`, async (route) => {
    await fulfillApi(route, { data: { rows: [], nextCursor: null } });
  });
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes`, async (route) => {
    addRequest = route.request().postDataJSON();
    await fulfillApi(route, {
      data: {
        participant: { id: 'new-participant' },
        claims: [{ guestId: 'guest-1', delivery: 'HANDOFF', claimToken: 'one-time-secret' }],
      },
    }, 201);
  });
  await openManage(page, { tab: 'registration' });

  await page.getByRole('button', { name: 'Thêm VĐV' }).click();
  const dialog = page.getByRole('dialog');
  await dialog.getByRole('button', { name: 'Nhập trực tiếp' }).click();
  await dialog.getByLabel('Tên VĐV').fill('Guest Athlete');
  await dialog.getByLabel('Ghi chú ban tổ chức').fill('Arrives late');
  await dialog.getByRole('button', { name: 'Thêm vào giải' }).click();

  await expect.poll(() => addRequest).toEqual({
    source: 'DIRECT',
    divisionId,
    players: [{ displayName: 'Guest Athlete', role: 'MAIN' }],
    organizerNote: 'Arrives late',
  });
  const handoffUrl =
    `${new URL(page.url()).origin}/tournaments/${tournamentId}/guest-claim/guest-1#token=one-time-secret`;
  const claimLink = dialog.getByLabel('Liên kết nhận suất một lần 1');
  await expect(claimLink).toHaveValue(handoffUrl);
  expect(new URL(handoffUrl).search).toBe('');

  await page.keyboard.press('Escape');
  await expect(dialog).toBeVisible();
  await expect(claimLink).toHaveValue(handoffUrl);
  await dialog.getByRole('button', { name: 'Đã chia sẻ xong' }).click();
  await expect(dialog).toBeHidden();
});

test('organizer can add a directly entered athlete without a division', async ({ page }) => {
  let addRequest: Record<string, unknown> | undefined;
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes/candidates**`, async (route) => {
    await fulfillApi(route, { data: { rows: [], nextCursor: null } });
  });
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes`, async (route) => {
    addRequest = route.request().postDataJSON();
    await fulfillApi(route, {
      data: { participant: { id: 'single-athlete-participant' }, claims: [] },
    }, 201);
  });
  await openManage(page, { tab: 'registration', divisions: [] });

  await page.getByRole('button', { name: 'Thêm VĐV' }).click();
  const dialog = page.getByRole('dialog', { name: 'Thêm VĐV' });
  await dialog.getByRole('button', { name: 'Nhập trực tiếp' }).click();
  await dialog.getByLabel('Tên VĐV').fill('No-division athlete');
  await expect(dialog.getByRole('button', { name: 'Thêm vào danh sách' })).toBeEnabled();
  await dialog.getByRole('button', { name: 'Thêm vào danh sách' }).click();

  await expect.poll(() => addRequest).toEqual({
    source: 'DIRECT',
    players: [{ displayName: 'No-division athlete', role: 'MAIN' }],
  });
});

