export const bracketFixture = {
…
};


const participant = {
  id: 'synthetic-wide-participant',
  tournamentId,
  tournamentDivisionId: divisionFixture.id,
  teamName: 'Wide overlay entrant',
  teamStatus: 'COMPLETE',
  isPaid: true,
  registeredAt: '2026-10-01T10:00:00.000Z',
  members: [{ userId: 'synthetic-wide-player', fullName: 'Wide overlay entrant', role: 'PLAYER' }],
};

export async function fulfillApi(route: Route, payload: unknown, status = 200) {
  const requestHeaders = route.request().headers();
  const headers = createApiFixtureCorsHeaders(requestHeaders, 'http://127.0.0.1:3001');

  if (route.request().method() === 'OPTIONS') {
    await route.fulfill({ status: 204, headers });
    return;
  }

  await route.fulfill({ status, headers, json: payload });
}

export async function openManage(
  page: Page,
  options: {
    divisions?: Array<typeof divisionFixture>;
    tab?: string;
    matchType?: 'SINGLES' | 'DOUBLES';
    withBracket?: boolean;
    tournamentConfig?: {
      teamSize?: 5 | 7 | 11;
      maxReserve?: number;
      maxTeamSize?: number;
    };
  } = {},
) {
  const matchType = options.matchType ?? 'SINGLES';
  const divisions = options.divisions ?? [{ ...divisionFixture, matchType }];
  const withBracket = options.withBracket ?? false;
  const currentTournament = {
    ...tournament,
    matchType,
    tournamentConfig: { ...tournament.tournamentConfig, ...options.tournamentConfig },
  };
…
}

export async function openManage(
…
) {
…
  const currentTournament = {
…
  };

  await page.addInitScript((user) => {
    localStorage.setItem('auth-storage', JSON.stringify({
      state: { user, isAuthenticated: true },
      version: 0,
    }));
  }, organizer);

  await page.route('**/api/v1/**', async (route) => {
    const pathname = new URL(route.request().url()).pathname;

    if (pathname.endsWith('/users/profile')) {
      await fulfillApi(route, { data: organizer });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}`) {
      await fulfillApi(route, { data: currentTournament });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}/divisions`) {
      await fulfillApi(route, { data: divisions });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}/bracket`) {
      await fulfillApi(route, { data: withBracket ? bracketFixture : { stages: [] } });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}/manage/participants`) {
      await fulfillApi(route, { data: divisions.length === 0 ? [] : [participant] });
      return;
    }

    await fulfillApi(route, { data: [] });
  });

  const tab = options.tab ? `?tab=${options.tab}` : '';
  await page.goto(`/organizer/tournaments/${tournamentId}/manage${tab}`, { waitUntil: 'domcontentloaded' });
}

const [isMockDataModalOpen, setIsMockDataModalOpen] = React.useState(false);
const [isWildcardModalOpen, setIsWildcardModalOpen] = React.useState(false);
const [selectedParticipant, setSelectedParticipant] = React.useState<TournamentParticipant | null>(null);
// Fee paid is organizer-owned truth, so the row is editable directly. Only
// clearing a mark that came from a real system payment moves money, and that
// one is confirmed first.
const [feePaymentBusyId, setFeePaymentBusyId] = React.useState<string | null>(null);
const [feePaymentPrompt, setFeePaymentPrompt] = React.useState<TournamentParticipant | null>(null);
const registrationFormFields = React.useMemo(
  () => readRegistrationFormConfig(tournament.tournamentConfig?.registrationForm, divisions.map((division) => division.id)).fields,
  [tournament.tournamentConfig?.registrationForm, divisions],
);
const selectedDivisionName = selectedParticipant
  ? divisions.find((division) => division.id === selectedParticipant.tournamentDivisionId)?.name || ''
  : '';
const selectedDivision = selectedParticipant
  ? divisions.find((division) => division.id === selectedParticipant.tournamentDivisionId)
  : undefined;
const selectedIsPair = Boolean(
  selectedParticipant &&
    (selectedDivision?.matchType === 'DOUBLES' || selectedDivision?.matchType === 'MIXED_DOUBLES' || selectedParticipant.members.length > 1),
);
const selectedLeader = selectedParticipant?.members.find((member) => member.role === 'MAIN') ?? selectedParticipant?.members[0];
const selectedDisplayName = selectedParticipant
  ? selectedIsPair && selectedParticipant.members.length > 1 && selectedParticipant.teamName === selectedLeader?.fullName
    ? selectedParticipant.members.map((member) => member.fullName).filter(Boolean).join(' & ')
    : selectedParticipant.teamName
  : '';
const selectedParticipantFee = Number(selectedParticipant?.entryFeeAtRegistration ?? 0);
const locale = useLocale();
const displayTranslate = useTranslations('TournamentDisplay');
const registrationTranslate = useTranslations('OrganizerRegistration');
const emailRegistrationTranslate = useTranslations('tournament.registration');
const exportTranslate = useTranslations('tournament.export');
const participantStatusLabels = {
  participantComplete: displayTranslate('participantComplete'),
  participantPendingPartner: displayTranslate('participantPendingPartner'),
  participantPendingApproval: displayTranslate('participantPendingApproval'),
  participantWaitlisted: displayTranslate('participantWaitlisted'),
  participantRejected: displayTranslate('participantRejected'),
  participantWithdrawn: displayTranslate('participantWithdrawn'),
  participantKicked: displayTranslate('participantKicked'),
  participantDisqualified: displayTranslate('participantDisqualified'),
  participantNoShow: displayTranslate('participantNoShow'),
  participantReplaced: displayTranslate('participantReplaced'),
  unknownParticipant: displayTranslate('unknownParticipant'),
};
const search = participantSearch;
const setSearch = setParticipantSearch;
const filter = participantFilter;

if (!Number.isFinite(entryFee) || entryFee < 0) {
  throw new BadRequestException('Lệ phí giải đấu không hợp lệ.');
}
const [participant] = await tx
  .insert(schema.tournamentParticipants)
  .values({
    tournamentId,
    tournamentDivisionId: dto.divisionId ?? null,
    registeredBy: userId,
    teamName:
      dto.teamName?.trim() ||
      players.map((player) => player.displayName).join(' / '),
    teamStatus: 'COMPLETE',
    rankingConsent: false,
    organizerNote: dto.organizerNote?.trim() || null,
    isPaid: entryFee === 0,
    isPresent: false,
    entryFeeAtRegistration: entryFee.toFixed(2),
    isMock: false,
    isWildcard: false,
  })
  .returning();
if (!participant) {
  throw new BadRequestException('Không thể thêm VĐV vào giải đấu.');
}

const accountPlayers = players.filter(
  (player): player is ResolvedAddAthlete & { userId: string } =>
    player.userId !== null,
);
const rosters =
  accountPlayers.length > 0
    ? await tx
        .insert(schema.tournamentRosters)
        .values(
          accountPlayers.map((player) => ({
            participantId: participant.id,
            userId: player.userId,
            role: player.role,
            status: 'ACTIVE',
          })),
        )
        .returning({
          id: schema.tournamentRosters.id,
          userId: schema.tournamentRosters.userId,
        })
    : [];

const pendingGuests = await this.insertGuestRosters(
  tx,
  participant.id,
  players.filter((player) => player.userId === null),
);
await this.auditService.logCreate(
  tx,
  userId,
