import {
  RankingConsentService,
  CONSENT_MAX_NOTIFICATIONS,
} from './ranking-consent.service';

const HOUR = 3_600_000;
const NOW = new Date('2026-06-10T12:00:00Z');

/** What dispatch finds for the roster row it is about to notify. */
interface ReminderDetail {
  userEmail: string | null;
  participantName: string | null;
  tournamentName: string;
  tournamentId: string;
  attempts: number;
  consentNotifiedAt: Date | null;
  consentedAt: Date | null;
  rosterStatus: string;
  participantStatus: string;
  isRanked: boolean;
  tournamentStatus: string;
  tournamentEndDate: Date | null;
  userEmailVerified: boolean;
  userDeletedAt: Date | null;
  tournamentDeletedAt: Date | null;
  joinedAt: Date | null;
}

const detailRow = (
  overrides: Partial<ReminderDetail> = {},
): ReminderDetail => ({
  userEmail: 'player@example.com',
  participantName: 'Nguyễn Văn A',
  tournamentName: 'Cup Đông Nam',
  tournamentId: 't-1',
  joinedAt: new Date('2026-05-01T00:00:00Z'),
  attempts: 0,
  consentNotifiedAt: null,
  consentedAt: null,
  rosterStatus: 'ACTIVE',
  participantStatus: 'COMPLETE',
  isRanked: true,
  tournamentStatus: 'REGISTRATION_OPEN',
  tournamentEndDate: null,
  userEmailVerified: true,
  userDeletedAt: null,
  tournamentDeletedAt: null,
  ...overrides,
});

describe('RankingConsentService.sendDueReminders', () => {
  const hoursAgo = (h: number) => new Date(NOW.getTime() - h * HOUR);

  const createDb = (
    candidates: unknown[],
    details: ReminderDetail = detailRow(),
  ) => {
    const candidate =
      candidates.length === 1 &&
      typeof candidates[0] === 'object' &&
      candidates[0] !== null
        ? (candidates[0] as Partial<ReminderDetail>)
        : null;
    const dispatchDetails = candidate ? detailRow(candidate) : details;
    const createQuery = (rows: unknown[]) => {
      const query: Record<string, unknown> = {};
      const self = () => query;
      query.from = jest.fn(self);
      query.innerJoin = jest.fn(self);
      query.where = jest.fn(self);
      query.limit = jest.fn(self);
      query.for = jest.fn(self);
      query.orderBy = jest.fn(self);
      query.set = jest.fn(self);
      query.then = (resolve: (value: unknown) => unknown) =>
        Promise.resolve().then(() => resolve(rows));
      return query;
    };
    const createExecutor = () => ({
      select: (fields: Record<string, unknown>) =>
        createQuery('userEmail' in fields ? [dispatchDetails] : candidates),
      update: () => createQuery([]),
    });
    const executor = createExecutor();
    return {
      ...executor,
      transaction: (
        callback: (transaction: unknown) => Promise<unknown>,
      ) => callback(createExecutor()),
    };
  };

  const build = (
    candidates: unknown[],
    sendOk = true,
    details: ReminderDetail = detailRow(),
  ) => {
    const db = createDb(candidates, details);
    const mailService = { sendMail: jest.fn().mockResolvedValue(sendOk) };
    const service = new RankingConsentService(
      db as never,
      mailService as never,
    );
    return { service, mailService };
  };


  beforeEach(() => {
    jest.useFakeTimers().setSystemTime(NOW);
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('retries a send that never landed, anchoring on the join time', async () => {
    // The reason notifiedAt NULL rows stay in scope: one mail outage must not
    // permanently silence the reminders, or the player never learns their
    // matches will go unscored.
    const { service, mailService } = build([
      { id: 'r1', attempts: 0, consentNotifiedAt: null, joinedAt: hoursAgo(25) },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(1);
    expect(mailService.sendMail).toHaveBeenCalledTimes(1);
  });

  it('waits when the first reminder is not due yet', async () => {
    const { service, mailService } = build([
      { id: 'r1', attempts: 0, consentNotifiedAt: null, joinedAt: hoursAgo(10) },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(0);
    expect(mailService.sendMail).not.toHaveBeenCalled();
  });

  it('sends the first reminder 24h after the send at add time', async () => {
    // attempts === 1 means exactly one send landed — the one at add time — so the
    // first reminder is due 24h after THAT send, not 72h.
    const { service, mailService } = build([
      {
        id: 'r1',
        attempts: 1,
        consentNotifiedAt: hoursAgo(30),
        joinedAt: hoursAgo(100),
      },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(1);
    expect(mailService.sendMail).toHaveBeenCalledTimes(1);
  });

  it('waits before the second reminder', async () => {
    // Two sends landed, so the 72h delay runs from the second one.
    const { service, mailService } = build([
      {
        id: 'r1',
        attempts: 2,
        consentNotifiedAt: hoursAgo(30),
        joinedAt: hoursAgo(100),
      },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(0);
    expect(mailService.sendMail).not.toHaveBeenCalled();
  });

  it('sends the second reminder once 72h have passed', async () => {
    const { service, mailService } = build([
      {
        id: 'r1',
        attempts: 2,
        consentNotifiedAt: hoursAgo(73),
        joinedAt: hoursAgo(200),
      },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(1);
    expect(mailService.sendMail).toHaveBeenCalledTimes(1);
  });

  it('stops at the notification cap so nobody is nagged forever', async () => {
    const { service, mailService } = build([
      {
        id: 'r1',
        attempts: CONSENT_MAX_NOTIFICATIONS,
        consentNotifiedAt: hoursAgo(200),
        joinedAt: hoursAgo(400),
      },
    ]);

    await expect(service.sendDueReminders()).resolves.toBe(0);
    expect(mailService.sendMail).not.toHaveBeenCalled();
  });

  it('does not count a failed send as a delivered one', async () => {
    const { service } = build(
      [{ id: 'r1', attempts: 0, consentNotifiedAt: null, joinedAt: hoursAgo(25) }],
      false,
    );

    await expect(service.sendDueReminders()).resolves.toBe(0);
  });
  it.each([
    ['unverified email', { userEmailVerified: false }],
    ['removed roster row', { rosterStatus: 'REMOVED' }],
    ['completed tournament', { tournamentStatus: 'COMPLETED' }],
    ['ended tournament', { tournamentEndDate: NOW }],
  ])('does not notify a player with %s', async (_reason, overrides) => {
    const { service, mailService } = build(
      [],
      true,
      detailRow(overrides as Partial<ReminderDetail>),
    );

    await service.sendConfirmationRequest('r1');

    expect(mailService.sendMail).not.toHaveBeenCalled();
  });

  it('escapes user-controlled names in the email body', async () => {
    const { service, mailService } = build(
      [],
      true,
      detailRow({
        participantName: '<img src=x onerror="alert(1)">',
        tournamentName: 'Cup <script>alert(1)</script>',
      }),
    );

    await service.sendConfirmationRequest('r1');

    const html = mailService.sendMail.mock.calls[0][2];
    expect(html).toContain('&lt;img src=x onerror=&quot;alert(1)&quot;&gt;');
    expect(html).toContain('Cup &lt;script&gt;alert(1)&lt;/script&gt;');
    expect(html).not.toContain('<script>');
  });

  it('rejects unsafe frontend URL schemes before sending', async () => {
    const previousFrontendUrl = process.env.FRONTEND_URL;
    process.env.FRONTEND_URL = 'javascript:alert(1)';
    try {
      const { service, mailService } = build([]);

      await service.sendConfirmationRequest('r1');

      expect(mailService.sendMail).not.toHaveBeenCalled();
    } finally {
      if (previousFrontendUrl === undefined) {
        delete process.env.FRONTEND_URL;
      } else {
        process.env.FRONTEND_URL = previousFrontendUrl;
      }
    }
  });
  it('serializes simultaneous reminder runs before sending', async () => {
    let attempts = 1;
    let notifiedAt: Date | null = hoursAgo(30);
    let transactionTail: Promise<void> = Promise.resolve();

    const makeExecutor = () => {
      const select = (fields: Record<string, unknown>) => {
        const query: Record<string, unknown> = {};
        const self = () => query;
        query.from = jest.fn(self);
        query.innerJoin = jest.fn(self);
        query.where = jest.fn(self);
        query.limit = jest.fn(self);
        query.for = jest.fn(self);
        query.then = (resolve: (value: unknown) => unknown) => {
          const rows =
            'userEmail' in fields
              ? [
                  detailRow({
                    attempts,
                    consentNotifiedAt: notifiedAt,
                  }),
                ]
              : [
                  {
                    id: 'r1',
                    attempts,
                    consentNotifiedAt: notifiedAt,
                    joinedAt: hoursAgo(40),
                  },
                ];
          return Promise.resolve().then(() => resolve(rows));
        };
        return query;
      };
      const update = () => {
        const query: Record<string, unknown> = {};
        query.set = jest.fn((values: Record<string, unknown>) => {
          if (typeof values.consentNotifiedCount === 'number') {
            attempts = values.consentNotifiedCount;
            notifiedAt = values.consentNotifiedAt as Date;
          }
          return query;
        });
        query.where = jest.fn(() => query);
        query.then = (resolve: (value: unknown) => unknown) =>
          Promise.resolve().then(() => resolve([]));
        return query;
      };
      return { select, update };
    };
    const transactionalExecutor = makeExecutor();
    const db = {
      ...makeExecutor(),
      transaction: async (callback: (tx: unknown) => Promise<unknown>) => {
        const previous = transactionTail;
        let release: () => void = () => undefined;
        transactionTail = new Promise<void>((resolve) => {
          release = resolve;
        });
        await previous;
        try {
          return await callback(transactionalExecutor);
        } finally {
          release();
        }
      },
    };
    const mailService = { sendMail: jest.fn().mockResolvedValue(true) };
    const service = new RankingConsentService(
      db as never,
      mailService as never,
    );

    const sends = await Promise.all([
      service.sendDueReminders(),
      service.sendDueReminders(),
    ]);

    expect(sends[0] + sends[1]).toBe(1);
    expect(mailService.sendMail).toHaveBeenCalledTimes(1);
  });
});

