 * shape: it is the only place a stale session bootstrap can resurface after a
 * logout, because the store writes through to storage on every update.
 */
async function readPersistedAuthState(page: Page): Promise<Record<string, unknown>> {
  const blob: unknown = await page.evaluate(() => {
    const raw = window.localStorage.getItem('auth-storage');
    if (!raw) return null;
    const parsed: unknown = JSON.parse(raw);
    if (parsed && typeof parsed === 'object' && 'state' in parsed) return parsed.state;
    return null;
  });
  return blob !== null && typeof blob === 'object' ? (blob as Record<string, unknown>) : {};
