test('registration waits for session validation, then reads the current registration', async ({ page }) => {
  const session = await stubRegistrationApi(page, { holdProfileRequests: 1 });

  await page.goto(`/tournaments/${tournamentId}/register?divisionId=${divisionId}`, {
    waitUntil: 'domcontentloaded',
  });

  // The tournament shell has rendered, so the page has had every chance to read
  // the current-registration status already.
  await expect(page.getByRole('heading', { level: 1, name: tournamentName })).toBeVisible();

  // Session validation is still in flight: report progress, never a failure,
  // and keep the protected registration request out of the way.
  await expect.poll(() => session.profileRequests.length).toBeGreaterThan(0);
  await expect(page.getByRole('status').filter({ hasText: validatingSessionStatusText })).toBeVisible();
  await expect(page.getByRole('alert').filter({ hasText: failedStatusText })).toHaveCount(0);
  // Observe a bounded window with /users/profile still held: the protected call
  // must stay absent for its whole duration, not merely be zero at one instant.
  await page.waitForTimeout(pendingObservationWindowMs);
  await expect.poll(() => session.myRegistrationRequests.length).toBe(0);

  // The pending flag and the request-ownership token are transient: neither may
  // reach storage, or a reload would resurrect a pending frame for a session
  // nobody is validating.
  const persistedState = await readPersistedAuthState(page);
  expect('isAuthenticated' in persistedState ? persistedState.isAuthenticated : undefined).toBe(true);
  // The pending flag and both request/session ids are transient: none of them
  // may reach storage, or a reload would carry a live session scope across a
  // browser restart.
  expect(Object.keys(persistedState)).not.toContain('isSessionValidationPending');
  expect(Object.keys(persistedState)).not.toContain('sessionValidationId');
  expect(Object.keys(persistedState)).not.toContain('authSessionGeneration');

  session.releaseProfile();

  // A validated session unlocks the registration read and the form itself.
  await expect(page.locator('form button[type="submit"]')).toBeVisible();
  await expect.poll(() => session.myRegistrationRequests.length).toBeGreaterThan(0);
  await expect(page.getByRole('status').filter({ hasText: validatingSessionStatusText })).toHaveCount(0);
  await expect(page.getByRole('status').filter({ hasText: checkingRegistrationStatusText })).toHaveCount(0);
  await expect(page.getByRole('alert').filter({ hasText: failedStatusText })).toHaveCount(0);
});

