  const session = await stubRegistrationApi(page, {
    // The app shell's read is held and answers with an older snapshot; the
    // profile page's own read answers immediately with the current one.
    holdProfileRequests: 1,
    profileBodies: [staleProfileResponse, profileResponse],
  });

  await page.goto(`/tournaments/${tournamentId}/register?divisionId=${divisionId}`, {
    waitUntil: 'domcontentloaded',
  });
