  // Client-side navigation keeps the shell mounted, so its request is still
  // open when the profile page becomes the newer owner of the session check.
  await page.getByRole('button', { name: accountMenuLabel }).click();
  await page.getByRole('link', { name: profileLinkLabel }).click();
  await page.waitForURL('**/profile');
  await expect.poll(() => session.profileRequests.length).toBe(2);

  // The newer owner read the current profile for itself.
  await expect
    .poll(async () => (await readPersistedAuthState(page)).user)
    .toMatchObject({ fullName: player.fullName });

  // The older owner's answer finally lands. It describes an earlier snapshot of
  // the same person and belongs to a check that is no longer the current one,
  // so it must not become the visible identity.
  session.releaseProfile();
  await page.waitForTimeout(pendingObservationWindowMs);
  const persistedState = await readPersistedAuthState(page);
  expect(persistedState.user).toMatchObject({ id: player.id, fullName: player.fullName });
});

