async function stubRegistrationApi(
…
  options: {
…
    /** Status of the token refresh the 401 path performs between attempts. */
    refreshStatus?: number;
    /** Path suffixes that answer 401, so a protected read can end the session. */
    rejectedPathSuffixes?: string[];
    /** The account `/auth/login` signs in, when the test drives a real switch. */
    loginUser?: unknown;
    /** Optional fixtures for an already-registered player. */
    myRegistrationPayload?: unknown;
    tournamentPayload?: unknown;
    divisionPayload?: unknown;
  } = {},
): Promise<SessionStub> {
  if (options.authenticated !== false) {
    await page.addInitScript((user) => {
      localStorage.setItem('auth-storage', JSON.stringify({
        state: { user, isAuthenticated: true },
        version: 0,
      }));
    }, player);
  }

  let releaseProfile: () => void = () => {};
  const profileGate = new Promise<void>((resolve) => {
    releaseProfile = resolve;
  });
  const profileRequests: string[] = [];
  const refreshRequests: string[] = [];
  const myRegistrationRequests: string[] = [];

  await page.route('**/api/v1/**', async (route) => {
    const request = route.request();
    const pathname = new URL(request.url()).pathname;

    if (pathname.endsWith('/users/profile')) {
      profileRequests.push(request.url());
      if (profileRequests.length <= (options.holdProfileRequests ?? 0)) {
        await profileGate;
      }
      const statuses = options.profileStatuses;
      const status = statuses?.[Math.min(profileRequests.length - 1, statuses.length - 1)];
      if (status && status !== 200) {
        await fulfillApi(
          route,
          { message: 'Máy chủ đang bận, vui lòng thử lại sau.' },
          status,
        );
        return;
      }
      const bodies = options.profileBodies;
      await fulfillApi(route, bodies?.[Math.min(profileRequests.length - 1, bodies.length - 1)] ?? profileResponse);
      return;
    }
    if (pathname.endsWith('/auth/refresh')) {
      refreshRequests.push(request.url());
      await fulfillApi(route, { message: 'ok' }, options.refreshStatus ?? 200);
      return;
    }
    if (options.loginUser && pathname.endsWith('/auth/login')) {
      await fulfillApi(route, { data: { user: options.loginUser } });
      return;
    }
    if (options.rejectedPathSuffixes?.some((suffix) => pathname.endsWith(suffix))) {
      await fulfillApi(route, { message: 'Phiên đăng nhập đã hết hạn.' }, 401);
      return;
    }
    if (pathname.endsWith(`/tournaments/${tournamentId}/my-registration`)) {
      myRegistrationRequests.push(request.url());
      await fulfillApi(
        route,
        options.myRegistrationPayload ?? {
          data: { registered: false, paymentEligible: true, participant: null },
        },
      );
      return;
    }
    if (pathname.endsWith(`/tournaments/${tournamentId}/divisions`)) {
      await fulfillApi(route, { data: options.divisionPayload ?? [division] });
      return;
    }
    if (pathname.endsWith(`/tournaments/${tournamentId}/results`)) {
      await fulfillApi(route, { data: null });
      return;
    }
    if (pathname.endsWith(`/tournaments/${tournamentId}`)) {
      await fulfillApi(route, { data: options.tournamentPayload ?? tournament });
      return;
    }

    await fulfillApi(route, { data: [] });
  });

