    // Mock fixtures are useful for previewing a bracket, but they must never
    // create an ELO outbox item.  The processor also guards this path, yet
    // skipping at enqueue keeps the ranked history clean and avoids needless
    // background work when a mock bracket is finalized.
    const mockParticipants = participantIds.length
      ? await tx
          .select({ isMock: schema.tournamentParticipants.isMock })
          .from(schema.tournamentParticipants)
          .where(inArray(schema.tournamentParticipants.id, participantIds))
      : [];
    const mockRosterUsers = participantIds.length
      ? await tx
          .select({ isMock: schema.users.isMock })
          .from(schema.tournamentRosters)
          .innerJoin(
            schema.users,
            eq(schema.tournamentRosters.userId, schema.users.id),
          )
          .where(
            inArray(schema.tournamentRosters.participantId, participantIds),
          )
      : [];
    const hasMockParticipant =
      mockParticipants.some((participant) => participant.isMock) ||
      mockRosterUsers.some((roster) => roster.isMock);
    // Consent lives on tournament_rosters, one row per USER — matching how
    // processMatchResult applies ELO (rankings.service.ts:600-617 / 628-645 read
    // tournamentRosters.userId per participant). Reading it off the participant
    // would let one team-mate's confirmation hand every other user their score.
    //
    // The roster predicate must stay exactly `.where(eq(participantId, X))` — no
    // status filter. Adding `status = 'ACTIVE'` would give a REMOVED/INVITED row
    // a NULL consent forever and silently kill ELO for the whole participant.
    //
    // A participant with NO roster row (Excel import, no account) must fail:
    // `[].every()` is true, so an empty roster would otherwise pass the gate and
    // such entrants — who have no account to confirm — would be scored anyway.
    //
    // All-or-nothing is deliberate: scoring only the consenting side would let a
    // player farm rating by facing opponents who never confirmed.
    const completionTime = updated.completedAt?.getTime() ?? null;
    const canCheckRankedElo =
      eloTournament?.isRanked === true &&
      participantIds.length === 2 &&
      participantIds[0] !== participantIds[1] &&
      completionTime !== null &&
      Number.isFinite(completionTime);
    const consentRosterRows = canCheckRankedElo
      ? await tx
          .select({
            participantId: schema.tournamentRosters.participantId,
            rankingConsentAt: schema.tournamentRosters.rankingConsentAt,
          })
          .from(schema.tournamentRosters)
          .where(inArray(schema.tournamentRosters.participantId, participantIds))
      : [];
    const guestRosterRows = canCheckRankedElo
      ? await tx
          .select({
            participantId: schema.tournamentGuestRosters.participantId,
          })
          .from(schema.tournamentGuestRosters)
          .where(inArray(schema.tournamentGuestRosters.participantId, participantIds))
      : [];
    const allParticipantsConsented =
      canCheckRankedElo &&
      consentRosterRows.length > 0 &&
      guestRosterRows.length === 0 &&
      participantIds.every((participantId) => {
        const rows = consentRosterRows.filter(
          (row) => row.participantId === participantId,
        );
        return (
          rows.length > 0 &&
          rows.every(
            (row) =>
              row.rankingConsentAt !== null &&
              Number.isFinite(row.rankingConsentAt.getTime()) &&
              row.rankingConsentAt.getTime() <= completionTime,
          )
        );
      });

    const footballTeamRows = participantIds.length
      ? await tx
          .select({
            footballTeamId: schema.tournamentParticipants.footballTeamId,
          })
          .from(schema.tournamentParticipants)
          .where(inArray(schema.tournamentParticipants.id, participantIds))
      : [];
    const isFootballTeamMatch =
      footballTeamRows.length === participantIds.length &&
      footballTeamRows.length === 2 &&
      footballTeamRows.every((row) => Boolean(row.footballTeamId));

    // Football group-stage draws have no winner, but still produce a team-ELO
    // event. Individual/pair ELO keeps the historical winner-only contract.
    if (
      eloTournament?.isRanked &&
      (winnerId || isFootballTeamMatch) &&
      allParticipantsConsented &&
      !hasMockParticipant
    ) {
      await tx
        .insert(schema.matchEloOutbox)
        .values({
          matchId: id,
          status: 'PENDING',
          attempts: 0,
          nextAttemptAt: new Date(),
        })
        .onConflictDoNothing({ target: schema.matchEloOutbox.matchId });
    }

    // 2. Two-legged knockout (bóng đá): chỉ advance khi CẢ2 leg COMPLETED.
