'use client';

import * as React from 'react';
import { useTranslations } from 'next-intl';
import { Loader2, Search, UserPlus } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Textarea } from '@/components/ui/Textarea';
import { Modal, ModalContent, ModalDescription, ModalFooter, ModalHeader, ModalTitle } from '@/components/ui/Modal';
import { tournamentsApi, type AddAthleteCandidate, type AddAthleteSource, type Division } from '@/features/tournaments/api';
import type { Tournament } from '@/types/tournament';
import { getErrorMessage } from '@/utils/error';
import toast from 'react-hot-toast';

interface AddAthleteModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  tournament: Tournament;
  divisions: Division[];
  selectedDivisionId: string;
  onSuccess: () => Promise<void> | void;
}

const SOURCES: AddAthleteSource[] = ['FRIENDS', 'CLUB', 'DIRECT'];

type AddAthleteRole = 'MAIN' | 'PARTNER' | 'RESERVE';

function isFootballTeamSize(size: number | undefined): size is 5 | 7 | 11 {
  return size === 5 || size === 7 || size === 11;
}

function getAddAthleteRosterCounts(tournament: Tournament, matchType: string) {
  if (matchType === 'DOUBLES' || matchType === 'MIXED_DOUBLES') {
    return { isTeamSport: false, requiredPlayerCount: 2, maxPlayerCount: 2, maxReserveCount: 0 };
  }

  const config = tournament.tournamentConfig;
  const optionSize = config?.teamSizeOptions?.find(isFootballTeamSize);
  const mainSize = [config?.teamSize, config?.minTeamSize, optionSize].find(isFootballTeamSize);
  const isTeamSport = mainSize !== undefined || config?.teamSize !== undefined || config?.minTeamSize !== undefined;
  if (!isTeamSport) {
    return { isTeamSport: false, requiredPlayerCount: 1, maxPlayerCount: 1, maxReserveCount: 0 };
  }
  if (mainSize === undefined) {
    return { isTeamSport: true, requiredPlayerCount: 0, maxPlayerCount: 0, maxReserveCount: 0 };
  }

  const configuredReserves = Number(config?.maxReserve ?? 0);
  const maxReserves = config?.allowReserve === false || !Number.isFinite(configuredReserves) || configuredReserves <= 0
    ? 0
    : Math.floor(configuredReserves);
  const configuredMaxTeamSize = Number(config?.maxTeamSize);
  const maxTeamSize = Number.isInteger(configuredMaxTeamSize) && configuredMaxTeamSize >= mainSize
    ? configuredMaxTeamSize
    : mainSize + maxReserves;
  const maxPlayerCount = Math.min(mainSize + maxReserves, maxTeamSize);

  return {
    isTeamSport: true,
    requiredPlayerCount: mainSize,
    maxPlayerCount,
    maxReserveCount: maxPlayerCount - mainSize,
  };
}

function createPlayers(count: number) {
  return Array.from({ length: Math.max(1, count) }, () => ({ displayName: '', email: '', phone: '' }));
}

function rosterRoleForIndex(index: number, isTeamSport: boolean, requiredPlayerCount: number): AddAthleteRole {
  if (isTeamSport && index >= requiredPlayerCount) return 'RESERVE';
  if (index === 0 || isTeamSport) return 'MAIN';
  return 'PARTNER';
}

function roleTranslationKey(role: AddAthleteRole): 'roleMain' | 'rolePartner' | 'roleReserve' {
  if (role === 'RESERVE') return 'roleReserve';
  if (role === 'PARTNER') return 'rolePartner';
  return 'roleMain';
}

export function AddAthleteModal({ open, onOpenChange, tournament, divisions, selectedDivisionId, onSuccess }: AddAthleteModalProps) {
  const t = useTranslations('AddAthlete');
  const initialDivisionId = selectedDivisionId || divisions[0]?.id || '';
  const initialMatchType = divisions.find((division) => division.id === initialDivisionId)?.matchType ?? tournament.matchType ?? 'SINGLES';
  const initialRequiredPlayerCount = getAddAthleteRosterCounts(tournament, initialMatchType).requiredPlayerCount;
  const [divisionId, setDivisionId] = React.useState(initialDivisionId);
  const [source, setSource] = React.useState<AddAthleteSource>('FRIENDS');
  const [search, setSearch] = React.useState('');
  const [rows, setRows] = React.useState<AddAthleteCandidate[]>([]);
  const [nextCursor, setNextCursor] = React.useState<string | null>(null);
  const [selectedIds, setSelectedIds] = React.useState<string[]>([]);
  const [pageLoading, setPageLoading] = React.useState(false);
  const [candidateError, setCandidateError] = React.useState(false);
  const [submitError, setSubmitError] = React.useState('');
  const candidateRequestId = React.useRef(0);
  const [submitting, setSubmitting] = React.useState(false);
  const [players, setPlayers] = React.useState(() => createPlayers(initialRequiredPlayerCount));
  const [teamName, setTeamName] = React.useState('');
  const [organizerNote, setOrganizerNote] = React.useState('');
  const [handoffLinks, setHandoffLinks] = React.useState<Array<{ guestId: string; url: string }>>([]);
  const selectedDivision = divisions.find((division) => division.id === divisionId);
  const matchType = selectedDivision?.matchType ?? tournament.matchType ?? 'SINGLES';
  const { isTeamSport, requiredPlayerCount, maxPlayerCount, maxReserveCount } =
    getAddAthleteRosterCounts(tournament, matchType);

  const loadCandidates = React.useCallback(async (cursor?: string, append = false) => {
    if (source === 'DIRECT' || !open) return;
    const requestId = ++candidateRequestId.current;
    setPageLoading(true);
    setCandidateError(false);
    if (!append) {
      setRows([]);
      setNextCursor(null);
    }
    try {
      const response = await tournamentsApi.getAddAthleteCandidates(tournament.id, {
        source,
        divisionId: divisionId || undefined,
        search: search.trim() || undefined,
        cursor,
        limit: 20,
      });
      const payload = response.data?.data ?? response.data;
      if (requestId !== candidateRequestId.current) return;
      setRows((current) => append ? [...current, ...(payload?.rows ?? [])] : (payload?.rows ?? []));
      setNextCursor(payload?.nextCursor ?? null);
    } catch (error) {
      if (requestId !== candidateRequestId.current) return;
      setCandidateError(true);
      toast.error(getErrorMessage(error));
      if (!append) {
        setRows([]);
        setNextCursor(null);
      }
    } finally {
      if (requestId === candidateRequestId.current) setPageLoading(false);
    }
  }, [divisionId, open, search, source, tournament.id]);

  React.useEffect(() => {
    if (open && source !== 'DIRECT') void loadCandidates();
  }, [loadCandidates, open, source]);

  React.useEffect(() => {
    if (!open) return;
    setDivisionId(initialDivisionId);
    setSource('FRIENDS');
    setSearch('');
    setSelectedIds([]);
    setPlayers(createPlayers(initialRequiredPlayerCount));
    setTeamName('');
    setOrganizerNote('');
    setCandidateError(false);
    setSubmitError('');
  }, [initialDivisionId, initialRequiredPlayerCount, open]);

  const switchSource = (value: AddAthleteSource) => {
    setSource(value);
    setSelectedIds([]);
    setRows([]);
    setNextCursor(null);
    setCandidateError(false);
  };

  const submit = async () => {
    const playerCount = source === 'DIRECT' ? players.length : selectedIds.length;
    if (submitting || requiredPlayerCount === 0 || playerCount < requiredPlayerCount ||
      playerCount > maxPlayerCount || (source === 'DIRECT' && players.some((player) => !player.displayName.trim()))) return;
    setSubmitting(true);
    setSubmitError('');
    try {
      const response = await tournamentsApi.addAthletes(tournament.id, {
        source,
        ...(divisionId ? { divisionId } : {}),
        ...(teamName.trim() ? { teamName: teamName.trim() } : {}),
        players: source === 'DIRECT'
          ? players.map((player, index) => ({
              displayName: player.displayName.trim(),
              ...(player.email.trim() ? { email: player.email.trim() } : {}),
              ...(player.phone.trim() ? { phone: player.phone.trim() } : {}),
              role: rosterRoleForIndex(index, isTeamSport, requiredPlayerCount),
            }))
          : selectedIds.map((userId, index) => ({
              userId,
              role: rosterRoleForIndex(index, isTeamSport, requiredPlayerCount),
            })),
        ...(organizerNote.trim() ? { organizerNote: organizerNote.trim().slice(0, 280) } : {}),
      });
      if (!response.data) throw new Error(t('addFailed'));
      const payload = response.data.data ?? response.data;
      const claimLinks = (payload?.claims ?? []).flatMap((claim) => {
        if (claim.delivery !== 'HANDOFF' || !claim.claimToken) return [];
        return [{
          guestId: claim.guestId,
          url: `${window.location.origin}/tournaments/${encodeURIComponent(tournament.id)}/guest-claim/${encodeURIComponent(claim.guestId)}#token=${encodeURIComponent(claim.claimToken)}`,
        }];
      });
      setHandoffLinks(claimLinks);
      if (claimLinks.length === 0) onOpenChange(false);
      void Promise.resolve(onSuccess()).catch((error) => toast.error(getErrorMessage(error)));
    } catch (error) {
      const message = getErrorMessage(error, t('addFailed'));
      setSubmitError(message);
      toast.error(message);
    } finally {
      setSubmitting(false);
    }
  };

  const copyHandoffLink = async (url: string) => {
    try {
      await navigator.clipboard.writeText(url);
      toast.success(t('claimLinkCopied'));
    } catch {
      toast.error(t('copyLinkFailed'));
    }
  };

  const canSubmit = requiredPlayerCount > 0 && (source === 'DIRECT'
    ? players.length >= requiredPlayerCount && players.length <= maxPlayerCount && players.every((player) => player.displayName.trim().length > 0)
    : selectedIds.length >= requiredPlayerCount && selectedIds.length <= maxPlayerCount);

  return (
    <Modal
      open={open}
      onOpenChange={(nextOpen) => {
        if (!nextOpen && (submitting || handoffLinks.length > 0)) return;
        onOpenChange(nextOpen);
      }}
    >
      <ModalContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl" aria-describedby="add-athlete-description">
        <ModalHeader>
          <ModalTitle>{handoffLinks.length > 0 ? t('handoffTitle') : t('title')}</ModalTitle>
          <ModalDescription id="add-athlete-description">
            {handoffLinks.length > 0 ? t('claimTokenHandoff') : t('description')}
          </ModalDescription>
        </ModalHeader>
        {handoffLinks.length > 0 ? (
          <section
            role="region"
            aria-live="polite"
            aria-label={t('handoffTitle')}
            className="space-y-4 rounded-md border border-amber-200 bg-amber-50 p-4"
          >
            {handoffLinks.map((handoff, index) => (
              <div key={handoff.guestId}>
                <label
                  htmlFor={`guest-claim-link-${index}`}
                  className="mb-1 block text-sm font-medium"
                >
                  {t('claimLinkLabel', { number: index + 1 })}
                </label>
                <div className="flex flex-col gap-2 sm:flex-row">
                  <Input
                    id={`guest-claim-link-${index}`}
                    readOnly
                    value={handoff.url}
                    onFocus={(event) => event.currentTarget.select()}
                    className="font-mono text-xs"
                  />
                  <Button
                    type="button"
                    onClick={() => void copyHandoffLink(handoff.url)}
                    className="min-h-11 shrink-0"
                  >
                    {t('copyClaimLink')}
                  </Button>
                </div>
              </div>
            ))}
          </section>
        ) : (
        <div className="space-y-4">
          {divisions.length > 1 && <div>
            <label htmlFor="add-athlete-division" className="mb-1 block text-sm font-medium">{t('division')}</label>
            <select id="add-athlete-division" value={divisionId} onChange={(event) => {
              const nextDivisionId = event.target.value;
              const nextDivision = divisions.find((division) => division.id === nextDivisionId);
              const nextMatchType = nextDivision?.matchType ?? tournament.matchType ?? 'SINGLES';
              const nextRosterCounts = getAddAthleteRosterCounts(tournament, nextMatchType);
              setDivisionId(nextDivisionId);
              setSelectedIds([]);
              setPlayers(createPlayers(nextRosterCounts.requiredPlayerCount));
            }} className="h-10 w-full rounded-md border border-slate-300 bg-white px-3 text-sm">
              {divisions.map((division) => <option key={division.id} value={division.id}>{division.name}</option>)}
            </select>
          </div>}
          <div role="group" aria-label={t('source')} className="flex flex-wrap gap-2">
            {SOURCES.map((option) => <button key={option} type="button" aria-pressed={source === option} onClick={() => switchSource(option)} className={`min-h-11 rounded-md border px-3 text-sm font-medium focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 ${source === option ? 'border-blue-600 bg-blue-50 text-blue-800' : 'border-slate-300 text-slate-700 hover:bg-slate-50'}`}>{t(`source${option}`)}</button>)}
          </div>
          {source !== 'DIRECT' ? <>
            <label className="relative block">
              <span className="sr-only">{t('search')}</span>
              <Search aria-hidden="true" className="absolute left-3 top-3 h-4 w-4 text-slate-400" />
              <Input aria-label={t('search')} value={search} onChange={(event) => setSearch(event.target.value)} className="pl-9" placeholder={t('search')} />
            </label>
            {isTeamSport && requiredPlayerCount > 0 && (
              <p className="text-xs text-slate-500">{t('teamSelectionHint', { required: requiredPlayerCount, reserves: maxReserveCount })}</p>
            )}
            <div aria-live="polite" aria-busy={pageLoading} className="max-h-64 space-y-1 overflow-y-auto rounded-md border border-slate-200 p-2">
              {pageLoading && rows.length === 0 ? (
                <p className="p-4 text-center text-sm text-slate-500"><Loader2 className="mr-2 inline h-4 w-4 animate-spin" />{t('loading')}</p>
              ) : candidateError && rows.length === 0 ? (
                <div role="alert" className="p-4 text-center text-sm text-rose-700"><p>{t('loadCandidatesFailed')}</p><Button type="button" variant="outline" size="sm" className="mt-3 min-h-11" disabled={pageLoading} onClick={() => void loadCandidates()}>{t('retry')}</Button></div>
              ) : rows.length === 0 ? (
                <p className="p-4 text-center text-sm text-slate-500">{t('empty')}</p>
              ) : rows.map((candidate) => {
                const selectionIndex = selectedIds.indexOf(candidate.userId);
                const selectedRole = selectionIndex >= 0
                  ? rosterRoleForIndex(selectionIndex, isTeamSport, requiredPlayerCount)
                  : null;
                return (
                  <label key={candidate.userId} className="flex cursor-pointer items-center gap-3 rounded-md p-2 hover:bg-slate-50">
                    <input type="checkbox" checked={selectionIndex >= 0} disabled={selectionIndex < 0 && selectedIds.length >= maxPlayerCount} onChange={() => setSelectedIds((current) => current.includes(candidate.userId) ? current.filter((id) => id !== candidate.userId) : [...current, candidate.userId])} />
                    {candidate.avatarUrl ? <img src={candidate.avatarUrl} alt="" className="h-9 w-9 rounded-full object-cover" /> : <span aria-hidden="true" className="inline-flex h-9 w-9 items-center justify-center rounded-full bg-blue-100 text-sm font-semibold text-blue-700">{candidate.displayName.trim().split(/\s+/).map((part) => part[0]).slice(-2).join('').toUpperCase()}</span>}
                    <span className="text-sm font-medium">{candidate.displayName}</span>
                    {selectedRole && <span className="ml-auto text-xs font-medium text-slate-600">{t(roleTranslationKey(selectedRole))}</span>}
                  </label>
                );
              })}
              {candidateError && rows.length > 0 && <div role="alert" className="flex items-center justify-between gap-2 p-2 text-sm text-rose-700"><span>{t('loadCandidatesFailed')}</span><Button type="button" variant="outline" size="sm" className="min-h-11" disabled={pageLoading} onClick={() => void loadCandidates(nextCursor ?? undefined, Boolean(nextCursor))}>{t('retry')}</Button></div>}
              {nextCursor && <Button type="button" variant="outline" size="sm" disabled={pageLoading} onClick={() => void loadCandidates(nextCursor, true)} className="min-h-11 w-full">{pageLoading ? t('loadingMore') : t('nextPage')}</Button>}
            </div>
            <p className="text-xs text-slate-500">{isTeamSport
              ? t('selectedTeamCount', { selected: selectedIds.length, required: requiredPlayerCount, reserves: maxReserveCount })
              : t('selectedCount', { selected: selectedIds.length, required: requiredPlayerCount })}</p>
          </> : <>
            {players.map((player, index) => {
              const role = rosterRoleForIndex(index, isTeamSport, requiredPlayerCount);
              return (
                <div key={index} className="rounded-md border border-slate-200 p-3">
                  <p className="mb-2 text-xs font-semibold text-slate-600">{t(roleTranslationKey(role))}</p>
                  <div className="grid gap-3 sm:grid-cols-3">
                    <div><label htmlFor={`add-athlete-name-${index}`} className="mb-1 block text-sm font-medium">{t('name')} <span aria-hidden="true">*</span></label><Input id={`add-athlete-name-${index}`} required value={player.displayName} onChange={(event) => setPlayers((current) => current.map((item, i) => i === index ? { ...item, displayName: event.target.value } : item))} /></div>
                    <div><label htmlFor={`add-athlete-email-${index}`} className="mb-1 block text-sm font-medium">{t('email')}</label><Input id={`add-athlete-email-${index}`} type="email" value={player.email} onChange={(event) => setPlayers((current) => current.map((item, i) => i === index ? { ...item, email: event.target.value } : item))} /></div>
                    <div><label htmlFor={`add-athlete-phone-${index}`} className="mb-1 block text-sm font-medium">{t('phone')}</label><Input id={`add-athlete-phone-${index}`} type="tel" value={player.phone} onChange={(event) => setPlayers((current) => current.map((item, i) => i === index ? { ...item, phone: event.target.value } : item))} /></div>
                  </div>
                </div>
              );
            })}
            <div className="flex flex-wrap gap-2">
              {requiredPlayerCount > 0 && players.length > requiredPlayerCount && <Button type="button" variant="outline" onClick={() => setPlayers((current) => current.length > requiredPlayerCount ? current.slice(0, -1) : current)} className="min-h-11">{t('removePlayer')}</Button>}
              {players.length < maxPlayerCount && (
                <Button type="button" variant="outline" onClick={() => setPlayers((current) => current.length < maxPlayerCount ? [...current, { displayName: '', email: '', phone: '' }] : current)} className="min-h-11">{isTeamSport ? t('addReserve') : t('addPlayer')}</Button>
              )}
            </div>
          </>}
          <div><label htmlFor="add-athlete-team-name" className="mb-1 block text-sm font-medium">{t('teamName')}</label><Input id="add-athlete-team-name" value={teamName} onChange={(event) => setTeamName(event.target.value)} /></div>
          <div><label htmlFor="add-athlete-organizer-note" className="mb-1 block text-sm font-medium">{t('organizerNote')}</label><Textarea id="add-athlete-organizer-note" maxLength={280} rows={3} value={organizerNote} onChange={(event) => setOrganizerNote(event.target.value)} /><p className="mt-1 text-right text-xs text-slate-500">{organizerNote.length}/280</p></div>
          {submitError && <p role="alert" aria-live="polite" className="text-sm text-rose-700">{submitError}</p>}
          <p role="status" aria-live="polite" className="sr-only">{submitting ? t('submitting') : pageLoading ? t('loading') : ''}</p>
        </div>
        )}
        <ModalFooter>
          {handoffLinks.length > 0 ? (
            <Button
              type="button"
              onClick={() => {
                setHandoffLinks([]);
                onOpenChange(false);
              }}
            >
              {t('finishHandoff')}
            </Button>
          ) : (
            <>
              <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={submitting}>{t('cancel')}</Button>
              <Button
                type="button"
                onClick={() => void submit()}
                disabled={!canSubmit || submitting || (divisions.length > 0 && !divisionId)}
                aria-busy={submitting}
                className="min-h-11"
              >
                {submitting ? <Loader2 aria-hidden="true" className="mr-2 h-4 w-4 animate-spin" /> : <UserPlus aria-hidden="true" className="mr-2 h-4 w-4" />}
                {submitting ? t('submitting') : t('submit')}
              </Button>
            </>
          )}
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
}

