import axios, { AxiosRequestConfig } from 'axios';
import { useAuthStore } from './zustand/authStore';
import toast from 'react-hot-toast';
import { getErrorMessage } from '@/utils/error';

let lastServerErrorToastAt = 0;
const SERVER_ERROR_TOAST_COOLDOWN_MS = 10000;
const ANONYMOUS_CLIENT_ID_KEY = 'sporto_anonymous_client_id_v1';
const RATE_LIMIT_RETRY_KEY = '__rate_limit_retry_count';
const MAX_RATE_LIMIT_RETRIES = 1;
const SNAPSHOT_TTL_MS = 10 * 60 * 1000;

type ManagedRequestConfig = AxiosRequestConfig & {
  __sharedDedupeKey?: string;
  __skipSharedDedupe?: boolean;
  [RATE_LIMIT_RETRY_KEY]?: number;
  // Set once a 401'd request has been replayed after a successful refresh, so
  // a replay that comes back 401 fails instead of looping through refresh again.
  _retry?: boolean;
  extra?: Record<string, unknown>;
};

type Deferred<T> = {
  promise: Promise<T>;
  resolve: (value: T | PromiseLike<T>) => void;
  reject: (reason?: unknown) => void;
};

type Snapshot = { data: unknown; savedAt: number };

const inFlightGetRequests = new Map<string, Deferred<unknown>>();
const publicGetSnapshots = new Map<string, Snapshot>();

function createDeferred<T>(): Deferred<T> {
  let resolve!: (value: T | PromiseLike<T>) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<T>((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

class SharedGetRequestError extends Error {
  constructor(readonly sharedPromise: Promise<unknown>) {
    super('Request is already in flight');
    this.name = 'SharedGetRequestError';
  }
}

/**
 * Marks a 401'd request as being replayed after a successful refresh.
 *
 * `__skipSharedDedupe` is what keeps the replay out of the dedupe pool: the
 * original request is still parked in `inFlightGetRequests` waiting for this
 * very handler to settle it, so a replay that re-entered the interceptor would
 * join its own deferred and never resolve. The shared key is deliberately kept
 * on the config, so the replayed response still settles the original deferred
 * and the callers that joined the original request see the post-refresh result.
 */
function markSessionRetried(config: AxiosRequestConfig): void {
  const managedConfig = getRequestMeta(config);
  managedConfig._retry = true;
  managedConfig.__skipSharedDedupe = true;
}

function getRequestMeta(config: AxiosRequestConfig | undefined): ManagedRequestConfig {
  return (config ?? {}) as ManagedRequestConfig;
}

function stableParams(params: unknown): string {
  if (!params || typeof params !== 'object') return String(params ?? '');
  if (params instanceof URLSearchParams) return params.toString();
  const entries = Object.entries(params as Record<string, unknown>)
    .sort(([left], [right]) => left.localeCompare(right));
  return JSON.stringify(entries);
}

/**
 * Identifies a response, and therefore who is allowed to receive it.
 *
 * The leading entries are the two scopes a response must not cross. Cookies
 * carry the session, so nothing in the request's own headers says whose data is
 * coming back.
 *
 * `authSessionGeneration` advances on a sign-out and on a new or different
 * identity, so reads already in flight for the current sign-in keep sharing
 * with it, while anything issued after a new sign-in cannot pick up the
 * previous session's answer — the same person signing back in included. The
 * account id follows, so one account can never be handed another's data at
 * all.
 *
 * A profile read is the session check itself, and has a third owner problem:
 * the app shell and the profile page each run one, and neither may be handed
 * the other's answer. Its key therefore also carries the current bootstrap's
 * `sessionValidationId`, which is why it is scoped apart from ordinary reads.
 * The 401 replay is unaffected: it skips the dedupe pool and settles through
 * the key captured on its own config, so it never re-resolves this one.
 *
 * All of it is read from the auth store and never persisted with it. On the
 * server the store never hydrates, so the session scope is always the guest
 * value.
 */
function getRequestKey(config: AxiosRequestConfig): string {
  const headers = config.headers as Record<string, unknown> | undefined;
  const auth = headers?.Authorization ?? headers?.authorization ?? '';
  const clientId = headers?.['x-client-id'] ?? '';
  const { authSessionGeneration, sessionValidationId, user } = useAuthStore.getState();
  const isSessionCheck = (config.url ?? '').split('?')[0] === '/users/profile';
  return [
    authSessionGeneration,
    user?.id ?? 'guest',
    isSessionCheck ? sessionValidationId : '',
    config.baseURL ?? '',
    config.url ?? '',
…
  ].join('|');
}
