import { expect, test } from '@playwright/test';
import { fulfillApi, openManage, tournamentId } from './support/organizer-manage';

const divisionId = 'synthetic-wide-division';

test('organizer keeps a one-time guest handoff link available until finishing', async ({ page }) => {
  let addRequest: Record<string, unknown> | undefined;
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes/candidates**`, async (route) => {
    await fulfillApi(route, { data: { rows: [], nextCursor: null } });
  });
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes`, async (route) => {
    addRequest = route.request().postDataJSON();
    await fulfillApi(route, {
      data: {
        participant: { id: 'new-participant' },
        claims: [{ guestId: 'guest-1', delivery: 'HANDOFF', claimToken: 'one-time-secret' }],
      },
    }, 201);
  });
  await openManage(page, { tab: 'registration' });

  await page.getByRole('button', { name: 'Thêm VĐV' }).click();
  const dialog = page.getByRole('dialog');
  await dialog.getByRole('button', { name: 'Nhập trực tiếp' }).click();
  await dialog.getByLabel('Tên VĐV').fill('Guest Athlete');
  await dialog.getByLabel(/Ghi chú của BTC/).fill('Arrives late');
  await dialog.getByRole('button', { name: 'Thêm vào danh sách' }).click();

  await expect.poll(() => addRequest).toEqual({
    source: 'DIRECT',
    divisionId,
    players: [{ displayName: 'Guest Athlete', role: 'MAIN' }],
    organizerNote: 'Arrives late',
  });
  const handoffUrl =
    `${new URL(page.url()).origin}/tournaments/${tournamentId}/guest-claim/guest-1#token=one-time-secret`;
  const claimLink = dialog.getByLabel('Liên kết nhận suất một lần 1');
  await expect(claimLink).toHaveValue(handoffUrl);
  expect(new URL(handoffUrl).search).toBe('');

  await page.keyboard.press('Escape');
  await expect(dialog).toBeVisible();
  await expect(claimLink).toHaveValue(handoffUrl);
  await dialog.getByRole('button', { name: 'Đã chia sẻ xong' }).click();
  await expect(dialog).toBeHidden();
});

test('organizer can add a directly entered athlete without a division', async ({ page }) => {
  let addRequest: Record<string, unknown> | undefined;
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes/candidates**`, async (route) => {
    await fulfillApi(route, { data: { rows: [], nextCursor: null } });
  });
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes`, async (route) => {
    addRequest = route.request().postDataJSON();
    await fulfillApi(route, {
      data: { participant: { id: 'single-athlete-participant' }, claims: [] },
    }, 201);
  });
  await openManage(page, { tab: 'registration', divisions: [] });

  await page.getByRole('button', { name: 'Thêm VĐV' }).click();
  const dialog = page.getByRole('dialog', { name: 'Thêm VĐV' });
  await dialog.getByRole('button', { name: 'Nhập trực tiếp' }).click();
  await dialog.getByLabel('Tên VĐV').fill('No-division athlete');
  await expect(dialog.getByRole('button', { name: 'Thêm vào danh sách' })).toBeEnabled();
  await dialog.getByRole('button', { name: 'Thêm vào danh sách' }).click();

  await expect.poll(() => addRequest).toEqual({
    source: 'DIRECT',
    players: [{ displayName: 'No-division athlete', role: 'MAIN' }],
  });
});

test('organizer can add a football squad with required starters and optional reserves', async ({ page }) => {
  let addRequest: Record<string, unknown> | undefined;
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes/candidates**`, async (route) => {
    await fulfillApi(route, { data: { rows: [], nextCursor: null } });
  });
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes`, async (route) => {
    addRequest = route.request().postDataJSON();
    await fulfillApi(route, { data: { participant: { id: 'football-participant' }, claims: [] } }, 201);
  });
  await openManage(page, {
    tab: 'registration',
    tournamentConfig: { teamSize: 5, maxReserve: 2, maxTeamSize: 6 },
  });

  await page.getByRole('button', { name: 'Thêm VĐV' }).click();
  const dialog = page.getByRole('dialog', { name: 'Thêm VĐV' });
  await dialog.getByRole('button', { name: 'Nhập trực tiếp' }).click();
  const names = dialog.getByLabel('Tên VĐV');
  await expect(names).toHaveCount(5);
  for (let index = 0; index < 5; index += 1) {
    await names.nth(index).fill(`Starter ${index + 1}`);
  }

  const addReserve = dialog.getByRole('button', { name: 'Thêm cầu thủ dự bị' });
  await addReserve.click();
  await names.nth(5).fill('Reserve 1');
  await expect(addReserve).toHaveCount(0);
  await dialog.getByRole('button', { name: 'Thêm vào giải' }).click();
  await expect.poll(() => addRequest).toEqual({
    source: 'DIRECT',
    divisionId,
    players: [
      { displayName: 'Starter 1', role: 'MAIN' },
      { displayName: 'Starter 2', role: 'MAIN' },
      { displayName: 'Starter 3', role: 'MAIN' },
      { displayName: 'Starter 4', role: 'MAIN' },
      { displayName: 'Starter 5', role: 'MAIN' },
      { displayName: 'Reserve 1', role: 'RESERVE' },
    ],
  });
});

test('organizer assigns registered football candidates to starters and reserves', async ({ page }) => {
  let addRequest: Record<string, unknown> | undefined;
  const candidates = Array.from({ length: 7 }, (_, index) => ({
    userId: `registered-${index + 1}`,
    displayName: `Player ${index + 1}`,
    avatarUrl: null,
    source: 'FRIENDS',
  }));
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes/candidates**`, async (route) => {
    await fulfillApi(route, { data: { rows: candidates, nextCursor: null } });
  });
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes`, async (route) => {
    addRequest = route.request().postDataJSON();
    await fulfillApi(route, { data: { participant: { id: 'registered-football-participant' }, claims: [] } }, 201);
  });
  await openManage(page, {
    tab: 'registration',
    tournamentConfig: { teamSize: 5, maxReserve: 2 },
  });

  await page.getByRole('button', { name: 'Thêm VĐV' }).click();
  const dialog = page.getByRole('dialog', { name: 'Thêm VĐV' });
  const checkboxes = dialog.getByRole('checkbox');
  await expect(checkboxes).toHaveCount(7);
  for (let index = 0; index < 7; index += 1) {
    await checkboxes.nth(index).check();
  }
  await expect(dialog.getByText('VĐV chính', { exact: true })).toHaveCount(5);
  await expect(dialog.getByText('VĐV dự bị', { exact: true })).toHaveCount(2);
  await dialog.getByRole('button', { name: 'Thêm vào giải' }).click();

  await expect.poll(() => addRequest).toEqual({
    source: 'FRIENDS',
    divisionId,
    players: [
      { userId: 'registered-1', role: 'MAIN' },
      { userId: 'registered-2', role: 'MAIN' },
      { userId: 'registered-3', role: 'MAIN' },
      { userId: 'registered-4', role: 'MAIN' },
      { userId: 'registered-5', role: 'MAIN' },
      { userId: 'registered-6', role: 'RESERVE' },
      { userId: 'registered-7', role: 'RESERVE' },
    ],
  });
});

test('organizer can add a searched friend without exposing contact information', async ({ page }) => {
  const queries: URL[] = [];
  let addRequest: Record<string, unknown> | undefined;
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes/candidates**`, async (route) => {
    const url = new URL(route.request().url());
    queries.push(url);
    await fulfillApi(route, url.searchParams.get('cursor')
      ? { data: { rows: [], nextCursor: null } }
      : { data: { rows: [{ userId: 'friend-1', displayName: 'Friend Athlete', avatarUrl: null, source: 'FRIENDS' }], nextCursor: 'page-2' } });
  });
  await page.route(`**/api/v1/tournaments/${tournamentId}/add-athletes`, async (route) => {
    addRequest = route.request().postDataJSON();
    await fulfillApi(route, { data: { participant: { id: 'registered-participant' }, claims: [] } }, 201);
  });
  await openManage(page, { tab: 'registration' });
  await page.getByRole('button', { name: 'Thêm VĐV' }).click();
  const dialog = page.getByRole('dialog', { name: 'Thêm VĐV' });
  await dialog.getByRole('button', { name: 'Bạn bè' }).click();
  await dialog.getByLabel('Tìm VĐV').fill('Friend');
  await expect(dialog.getByText('Friend Athlete')).toBeVisible();
  await expect(dialog.getByText(/@|09\d{8}/)).toHaveCount(0);
  await dialog.getByRole('button', { name: 'Trang tiếp' }).click();
  await expect.poll(() => queries.some((url) => url.searchParams.get('cursor') === 'page-2')).toBe(true);
  expect(queries[0].searchParams.get('source')).toBe('FRIENDS');
  await dialog.getByRole('checkbox').check();
  await dialog.getByRole('button', { name: 'Thêm vào giải' }).click();

  await expect.poll(() => addRequest).toEqual({
    source: 'FRIENDS',
    divisionId,
    players: [{ userId: 'friend-1', role: 'MAIN' }],
  });
});

test('player claims a guest roster with the URL fragment and the fragment is removed', async ({ page }) => {
  let claimRequest: Record<string, unknown> | undefined;
  await openManage(page);
  await page.route(`**/api/v1/tournaments/${tournamentId}/guest-rosters/guest-1/claim`, async (route) => {
    claimRequest = route.request().postDataJSON();
    await fulfillApi(route, { data: { success: true } });
  });
  await page.goto(`/tournaments/${tournamentId}/guest-claim/guest-1#token=one-time-secret`, { waitUntil: 'domcontentloaded' });

  await expect(page.getByRole('heading', { name: 'Đã nhận vị trí thi đấu' })).toBeVisible();
  await expect.poll(() => claimRequest).toEqual({ claimToken: 'one-time-secret' });
  expect(new URL(page.url()).hash).toBe('');
  expect(new URL(page.url()).search).not.toContain('one-time-secret');
});

test('shows a neutral error and clears a rejected claim token', async ({ page }) => {
  const claimToken = 'rejected-one-time-secret';
  await openManage(page);
  await page.route(`**/api/v1/tournaments/${tournamentId}/guest-rosters/guest-1/claim`, async (route) => {
    await fulfillApi(route, { message: 'email mismatch' }, 403);
  });
  await page.goto(
    `/tournaments/${tournamentId}/guest-claim/guest-1#token=${claimToken}`,
    { waitUntil: 'domcontentloaded' },
  );

  await expect(
    page.getByRole('heading', { name: 'Không thể nhận vị trí thi đấu' }),
  ).toBeVisible();
  await expect(page.getByRole('alert')).toContainText('Liên kết không hợp lệ');
  expect(new URL(page.url()).hash).toBe('');
  expect(new URL(page.url()).search).not.toContain(claimToken);
});

test('does not show payment status without a positive fee snapshot', async ({ page }) => {
  await openManage(page, { tab: 'registration' });
  await page.getByRole('button', { name: 'Wide overlay entrant', exact: true }).click();

  const detail = page.getByRole('dialog');
  await expect(detail.getByText('Đã thanh toán', { exact: true })).toHaveCount(0);
  await expect(detail.getByText('Chưa thanh toán', { exact: true })).toHaveCount(0);
});

