                title={registrationTranslate('pairingQueueDescription')}
              >
                <Users className="h-3.5 w-3.5" />
                {registrationTranslate('pairNow')}
                <span className="rounded-full bg-blue-100 px-1.5 py-0.5 text-xs">{pairingPendingCount}</span>
              </Button>
            )}

            {/* Bên phải: 3-dots Dropdown Menu (Cài đặt / Thao tác - borderless, không khung) */}
            <DropdownMenu>
