                    <Shuffle className="h-4 w-4 text-slate-500" />
                  )}
                  <span>{isAutoSeeding ? registrationTranslate('seedingInProgress') : registrationTranslate('autoSeed')}</span>
                </DropdownMenuItem>

                <div className="my-1 border-t border-slate-100" />

                <DropdownMenuItem
